                  </div>
                </Card>

                <Card className="p-6">
                  <p className="eyebrow">
                    Quick system rules
                  </p>
                  <h3 className="mt-2 section-title">
                    What is protected?
                  </h3>
                  <div className="mt-6 space-y-4">
                    {[
                      "Finance actions stay online-only to protect ledger truth.",
                      "Retired modules stay hidden from operational workspaces.",
                      "User management stays school-linked and role-based.",
                    ].map((item) => (
                      <div
                        key={item}
                        className="flex items-start gap-3 rounded-[var(--radius)] border border-border bg-surface-muted px-4 py-4"
                      >
                        <ShieldCheck className="mt-0.5 h-5 w-5 text-accent" />
                        <p className="text-sm leading-6 text-foreground">{item}</p>
                      </div>
                    ))}
                  </div>
                </Card>
              </div>
            ),
          },
          {
            id: "fees",
            label: "Fee structure",
            panel: (
              <DataTable
                title="Fee structure"
                subtitle="Tuition, lunch, and other fee items stay plainly editable and easy to read."
                columns={feeColumns}
                rows={model.settings.feeStructure}
                getRowKey={(row) => row.id}
              />
            ),
          },
          {
            id: "users",
            label: "Users",
            panel: (
              <DataTable
                title="User management"
                subtitle="School users are shown without technical clutter."
                columns={userColumns}
                rows={model.settings.users}
                getRowKey={(row) => row.id}
              />
            ),
          },
        ]}
      />
    </div>
  );
}

export function ModuleScreen({
  role,
  moduleName,
  snapshot,
  online,
}: {
  role: DashboardRole;
  moduleName: string;
  snapshot: DashboardSnapshot;
  online: boolean;
}) {
  if (moduleName === "students") {
    return <StudentsPage role={role} snapshot={snapshot} online={online} />;
  }

  if (role === "exam-manager") {
    return <ExamsManagerModuleScreen role={role} moduleName={moduleName} snapshot={snapshot} online={online} />;
  }

  if (role === "dean") {
    return <DeanModuleScreen role={role} moduleName={moduleName} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "inventory") {
    return <InventoryModuleScreen role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "admissions") {
    return <AdmissionsModuleScreen role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "finance") {
    return <FinancePage role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "mpesa") {
    return <MpesaPage role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "academics") {
    return <AcademicsPage role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "communication") {
    return <CommunicationPage role={role} snapshot={snapshot} online={online} />;
  }

  if (moduleName === "reports") {
    return <ReportsPage role={role} snapshot={snapshot} online={online} />;
  }

  return <SettingsPage role={role} snapshot={snapshot} online={online} />;
}

"use client";

import {
  Bell,
  CircleAlert,
  ChevronDown,
  CircleUserRound,
  LoaderCircle,
  LogIn,
  LogOut,
  Menu,
  Search,
  ShieldCheck,
  Wifi,
  WifiOff,
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { startTransition, useDeferredValue, useState } from "react";

import { StatusPill } from "@/components/ui/status-pill";
import type { LiveAuthUser } from "@/lib/dashboard/api-client";
import { getRoleSidebar } from "@/lib/dashboard/role-config";
import { getDashboardWorkspaceHref } from "@/lib/dashboard/workspace-routes";
import { isProductionReadyHref } from "@/lib/features/module-readiness";
import type {
  AlertItem,
  CapabilityItem,
  DashboardRole,
  NotificationItem,
  QuickActionItem,
  SyncIndicator,
  TenantOption,
} from "@/lib/dashboard/types";

type SelectorOption = {
  id: string;
  label: string;
};

type SearchItem = {
  id: string;
  label: string;
  description: string;
  href: string;
  kind: "module" | "action" | "alert" | "notification" | "capability" | "student";
};

function normalizeSearchableText(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "");
}

export function Topbar({
  role,
  tenantId,
  tenants,
  notifications,
  alerts,
  quickActions,
  capabilities,
  sync,
  online,
  pageTitle,
  tenantName,
  onTenantChange,
  currentTerm,
  academicYear,
  termOptions,
  yearOptions,
  liveApiConfigured,
  liveUser,
  liveSessionLoading,
  liveSessionSubmitting,
  liveSessionError,
  onLiveLogin,
  onLiveLogout,
  onOpenSidebar,
  supplementalSearchItems = [],
}: {
  role: DashboardRole;
  tenantId: string;
  tenants: TenantOption[];
  notifications: NotificationItem[];
  alerts: AlertItem[];
  quickActions: QuickActionItem[];
  capabilities: CapabilityItem[];
  sync: SyncIndicator;
  online: boolean;
  pageTitle: string;
  pageDescription: string;
  tenantName: string;
  tenantCounty: string;
  onTenantChange: (tenantId: string) => void;
  currentTerm: string;
  academicYear: string;
  termOptions: SelectorOption[];
  yearOptions: SelectorOption[];
  liveApiConfigured: boolean;
  liveUser: LiveAuthUser | null;
  liveSessionLoading: boolean;
  liveSessionSubmitting: boolean;
  liveSessionError: string | null;
  onLiveLogin: (email: string, password: string) => Promise<void>;
  onLiveLogout: () => void;
  onOpenSidebar: () => void;
  supplementalSearchItems?: SearchItem[];
}) {
  const router = useRouter();
  const [searchTerm, setSearchTerm] = useState("");
  const [showSearchPanel, setShowSearchPanel] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSyncPanel, setShowSyncPanel] = useState(false);
  const [showProfilePanel, setShowProfilePanel] = useState(false);
  const [selectedTerm, setSelectedTerm] = useState(currentTerm);
  const [selectedYear, setSelectedYear] = useState(academicYear);
  const [liveEmail, setLiveEmail] = useState("");
  const [livePassword, setLivePassword] = useState("");
  const deferredSearchTerm = useDeferredValue(searchTerm);
  const normalizedSearchTerm = normalizeSearchableText(deferredSearchTerm);

  const searchItems: SearchItem[] = [
    ...getRoleSidebar(role).map((item) => ({
      id: `module-${item.id}`,
      label: item.label,
      description: `${item.label} workspace`,
      href: getDashboardWorkspaceHref(role, item.href),
      kind: "module" as const,
    })),
    ...quickActions.map((action) => ({
      id: `action-${action.id}`,
      label: action.label,
      description: action.description,
      href: getDashboardWorkspaceHref(role, action.href),
      kind: "action" as const,
    })),
    ...alerts.map((alert) => ({
      id: `alert-${alert.id}`,
      label: alert.title,
      description: alert.description,
      href: alert.href,
      kind: "alert" as const,
    })),
    ...notifications.map((notification) => ({
      id: `notification-${notification.id}`,
      label: notification.title,
      description: `Notification - ${notification.timeLabel}`,
      href: notification.href,
      kind: "notification" as const,
    })),
    ...capabilities.map((capability) => ({
      id: `capability-${capability.id}`,
      label: capability.label,
      description: capability.description,
      href: getDashboardWorkspaceHref(role, capability.href),
      kind: "capability" as const,
    })),
    ...supplementalSearchItems,
  ].filter((item) => isProductionReadyHref(item.href));

  const filteredSearchItems = searchItems
    .filter((item) => {
      if (!normalizedSearchTerm) {
        return false;
      }

      return normalizeSearchableText(
        `${item.label} ${item.description} ${item.kind}`,
      ).includes(normalizedSearchTerm);
    })
    .slice(0, 6);

  const closeFloatingPanels = () => {
    setShowSearchPanel(false);
    setShowNotifications(false);
    setShowSyncPanel(false);
    setShowProfilePanel(false);
  };

  const runSearchNavigation = (href: string) => {
    setSearchTerm("");
    closeFloatingPanels();

    startTransition(() => {
      router.push(href);
    });
  };

  const handleLiveLogin = async () => {
    if (!liveEmail.trim() || !livePassword.trim()) {
      return;
    }

    try {
      await onLiveLogin(liveEmail.trim(), livePassword);
      setLivePassword("");
    } catch {
      return;
    }
  };

  const unresolvedNotifications = notifications.filter(
    (n) => !n.isRead && (n.severity === "critical" || n.severity === "warning" || n.severity === "ok" || n.severity === "info" as any)
  ).length;

  return (
    <div
      data-testid="topbar"
      className="flex items-center gap-3 rounded-[var(--radius)] border border-border bg-surface px-4 py-2.5 shadow-xs"
    >
      {/* Mobile menu button */}
      <button
        type="button"
        onClick={onOpenSidebar}
        aria-label="Open sidebar"
        className="inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-sm)] text-muted transition-colors hover:bg-surface-strong hover:text-foreground md:hidden"
      >
        <Menu className="h-4 w-4" />
      </button>

      {/* Left: Page context */}
      <div className="hidden min-w-0 md:block">
        <div className="flex items-center gap-2">
          <p className="text-[13px] font-semibold text-foreground truncate">{tenantName}</p>
          <span className="text-border">·</span>
          <p className="text-[13px] text-muted truncate">{pageTitle}</p>
        </div>
      </div>

      {/* Mobile: school name only */}
      <p className="text-[13px] font-semibold text-foreground truncate md:hidden">{tenantName}</p>

      {/* Spacer */}
      <div className="flex-1" />

      {/* Search */}
      <div className="relative hidden sm:block sm:w-56 lg:w-64">
        <label className="flex items-center gap-2 rounded-[var(--radius-sm)] border border-border bg-surface-muted px-3 py-1.5">
          <Search className="h-3.5 w-3.5 text-muted" />
          <input
            type="search"
            aria-label="Global search"
            value={searchTerm}
            onChange={(event) => setSearchTerm(event.target.value)}
            onFocus={() => {
              setShowSearchPanel(true);
              setShowNotifications(false);
              setShowSyncPanel(false);
              setShowProfilePanel(false);
            }}
            onBlur={() => {
              window.setTimeout(() => setShowSearchPanel(false), 120);
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter" && filteredSearchItems[0]) {
                event.preventDefault();
                runSearchNavigation(filteredSearchItems[0].href);
              }
            }}
            placeholder="Search students, payments, or modules"
            className="w-full bg-transparent text-[13px] outline-none placeholder:text-muted"
          />
          <kbd className="hidden rounded border border-border bg-surface px-1.5 py-0.5 text-[10px] font-medium text-muted lg:inline">
            ⌘K
          </kbd>
        </label>

        {showSearchPanel && normalizedSearchTerm ? (
          <div
            data-testid="search-panel"
            className="fade-in-panel absolute left-0 right-0 top-[calc(100%+4px)] z-20 rounded-[var(--radius)] border border-border bg-surface p-1 shadow-lg"
          >
            {filteredSearchItems.length === 0 ? (
              <div className="rounded-[var(--radius-sm)] px-3 py-3 text-[13px] text-muted">
                No results for &ldquo;{deferredSearchTerm}&rdquo;
              </div>
            ) : (
              filteredSearchItems.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  data-testid="search-result"
                  onClick={() => runSearchNavigation(item.href)}
                  className="flex w-full items-center justify-between gap-3 rounded-[var(--radius-sm)] px-3 py-2 text-left transition-colors hover:bg-surface-muted"
                >
                  <div className="min-w-0">
                    <p className="text-[13px] font-medium text-foreground">{item.label}</p>
                    <p className="text-[11px] text-muted truncate">{item.description}</p>
                  </div>
                  <span className="badge badge-neutral shrink-0">
                    {item.kind}
                  </span>
                </button>
              ))
            )}
          </div>
        ) : null}
      </div>

      {/* Term/Year selector — hidden on small screens */}
      <div className="hidden items-center rounded-[var(--radius-sm)] border border-border bg-surface-muted lg:flex">
        <select
          aria-label="Select term"
          value={selectedTerm}
          onChange={(event) => setSelectedTerm(event.target.value)}
          className="bg-transparent px-2 py-1.5 text-[12px] font-medium text-foreground outline-none"
        >
          {termOptions.map((option) => (
            <option key={option.id} value={option.label}>
              {option.label}
            </option>
          ))}
        </select>
        <span className="text-border text-xs">|</span>
        <select
          aria-label="Select academic year"
          value={selectedYear}
          onChange={(event) => setSelectedYear(event.target.value)}
          className="bg-transparent px-2 py-1.5 text-[12px] font-medium text-foreground outline-none"
        >
          {yearOptions.map((option) => (
            <option key={option.id} value={option.label}>
              {option.label}
            </option>
          ))}
        </select>
      </div>

      {/* School selector - single line */}
      <label className="hidden items-center rounded-[var(--radius-sm)] border border-border bg-surface-muted px-2 py-1.5 lg:flex">
        <select
          aria-label="Switch school"
          value={tenantId}
          onChange={(event) => onTenantChange(event.target.value)}
          className="bg-transparent text-[12px] font-medium text-foreground outline-none"
        >
          {tenants.map((tenant) => (
            <option key={tenant.id} value={tenant.id}>
              {tenant.name}
            </option>
          ))}
        </select>
        <ChevronDown className="h-3 w-3 text-muted ml-1" />
      </label>

      {/* Sync indicator */}
      <div className="relative">
        <button
          type="button"
          aria-label={online ? "Current sync status" : "Offline queue status"}
          aria-expanded={showSyncPanel}
          onClick={() => {
            setShowSyncPanel((value) => !value);
            setShowNotifications(false);
            setShowProfilePanel(false);
          }}
          className="inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-sm)] text-muted transition-colors hover:bg-surface-strong"
        >
          {online ? (
            <Wifi className="h-4 w-4 text-success" />
          ) : (
            <WifiOff className="h-4 w-4 text-warning" />
          )}
        </button>

        {showSyncPanel ? (
          <div
            data-testid="sync-panel"
            className="fade-in-panel absolute right-0 top-[calc(100%+4px)] z-20 w-[260px] rounded-[var(--radius)] border border-border bg-surface p-3.5 shadow-lg"
          >
            <div className="flex items-center justify-between gap-3">
              <p className="section-title">Sync status</p>
              <StatusPill label={online ? sync.label : "Offline mode active"} tone={online ? sync.state : "warning"} />
            </div>
            <div className="mt-3 grid grid-cols-3 gap-2">
              <div className="rounded-[var(--radius-sm)] bg-surface-muted px-3 py-2">
                <p className="text-[10px] font-semibold uppercase tracking-wider text-muted">Pending</p>
                <p className="mt-1 text-base font-bold text-foreground finance-number">{sync.pendingCount}</p>
              </div>
              <div className="rounded-[var(--radius-sm)] bg-surface-muted px-3 py-2">
                <p className="text-[10px] font-semibold uppercase tracking-wider text-muted">Failed</p>
                <p className="mt-1 text-base font-bold text-foreground finance-number">{sync.failedCount}</p>
              </div>
              <div className="rounded-[var(--radius-sm)] bg-surface-muted px-3 py-2">
                <p className="text-[10px] font-semibold uppercase tracking-wider text-muted">Last sync</p>
                <p className="mt-1 text-xs font-medium text-foreground">{sync.lastSyncedAt}</p>
              </div>
            </div>
          </div>
        ) : null}
      </div>

      {/* Notifications */}
      <div className="relative">
        <button
          type="button"
          aria-label="Open notifications"
          aria-expanded={showNotifications}
          onClick={() => {
            setShowNotifications((value) => !value);
            setShowSyncPanel(false);
            setShowProfilePanel(false);
          }}
          className="relative inline-flex h-8 w-8 items-center justify-center rounded-[var(--radius-sm)] text-muted transition-colors hover:bg-surface-strong"
        >
          <Bell className="h-4 w-4" />
          {unresolvedNotifications > 0 ? (
            <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-danger px-1 text-[10px] font-bold text-white">
              {unresolvedNotifications}
            </span>
          ) : null}
        </button>

        {showNotifications ? (
          <div
            data-testid="notifications-panel"
            className="fade-in-panel absolute right-0 top-[calc(100%+4px)] z-20 w-[300px] rounded-[var(--radius)] border border-border bg-surface p-2.5 shadow-lg"
          >
            <div className="mb-2 flex items-center justify-between gap-3 px-1">
              <p className="section-title">Notifications</p>
              <span className="badge badge-neutral">{notifications.length}</span>
            </div>
            <div className="custom-scrollbar max-h-[280px] space-y-1 overflow-y-auto">
              {notifications.map((notification) => (
                <Link
                  key={notification.id}
                  href={notification.href}
                  className={`block rounded-[var(--radius-sm)] px-3 py-2 transition-colors hover:bg-surface-muted ${notification.isRead ? "opacity-70" : ""}`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0 flex items-center gap-2">
                      {!notification.isRead && (
                        <div className="h-2 w-2 shrink-0 rounded-full bg-accent" />
                      )}
                      <div>
                        <p className={`text-[13px] truncate ${notification.isRead ? "font-normal text-muted" : "font-medium text-foreground"}`}>
                          {notification.title}
                        </p>
                        <p className="mt-0.5 text-[11px] text-muted">
                          {notification.timeLabel}
                        </p>
                      </div>
                    </div>
                    <StatusPill label={notification.severity} tone={notification.severity} compact />
                  </div>
                </Link>
              ))}
            </div>
          </div>
        ) : null}
      </div>

      {/* Profile/Live Data */}
      <div className="relative">
        <button
          type="button"
          aria-label="Open live data profile"
          aria-expanded={showProfilePanel}
          onClick={() => {
            setShowProfilePanel((value) => !value);
            setShowNotifications(false);
            setShowSyncPanel(false);
            setShowSearchPanel(false);
          }}
          className="inline-flex h-8 items-center gap-1.5 rounded-[var(--radius-sm)] px-2 transition-colors hover:bg-surface-strong"
        >
          {liveUser ? (
            <ShieldCheck className="h-4 w-4 text-success" />
          ) : (
            <CircleUserRound className="h-4 w-4 text-muted" />
          )}
          <span className="hidden text-[12px] font-medium text-foreground lg:inline">
            {liveUser ? liveUser.display_name.split(" ")[0] : "Live"}
          </span>
        </button>

        {showProfilePanel ? (
          <div
            data-testid="live-profile-panel"
            className="fade-in-panel absolute right-0 top-[calc(100%+4px)] z-20 w-[290px] rounded-[var(--radius)] border border-border bg-surface p-3.5 shadow-lg"
          >
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="section-title">Production service</p>
                <p className="mt-0.5 text-[11px] text-muted">
                  School-linked live data
                </p>
              </div>
              <StatusPill
                label={
                  liveSessionLoading
                    ? "Checking"
                    : liveUser
                      ? "Connected"
                      : liveApiConfigured
                        ? "Ready"
                        : "Unavailable"
                }
                tone={
                  liveSessionLoading
                    ? "warning"
                    : liveUser
                      ? "ok"
                      : liveApiConfigured
                        ? "warning"
                        : "critical"
                }
              />
            </div>

            {liveSessionError ? (
              <div className="mt-3 flex gap-2 rounded-[var(--radius-sm)] border border-danger/20 bg-danger-soft px-3 py-2">
                <CircleAlert className="mt-0.5 h-3.5 w-3.5 shrink-0 text-danger" />
                <p className="text-[13px] text-foreground">{liveSessionError}</p>
              </div>
            ) : null}

            {liveUser ? (
              <div className="mt-3 space-y-3">
                <div className="rounded-[var(--radius-sm)] bg-surface-muted px-3 py-2.5">
                  <p className="text-[13px] font-semibold text-foreground">
                    {liveUser.display_name}
                  </p>
                  <p className="mt-0.5 text-[11px] text-muted">{liveUser.email}</p>
                  <div className="mt-2 flex flex-wrap gap-1.5">
                    <StatusPill label={liveUser.role} tone="ok" />
                    <StatusPill label={liveUser.tenant_id ?? "Platform"} tone="warning" />
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    onLiveLogout();
                    setShowProfilePanel(false);
                  }}
                  className="inline-flex w-full items-center justify-center gap-2 rounded-[var(--radius-sm)] border border-border bg-surface px-3 py-2 text-[13px] font-semibold text-foreground transition-colors hover:bg-surface-muted"
                >
                  <LogOut className="h-3.5 w-3.5" />
                  Disconnect
                </button>
              </div>
            ) : liveApiConfigured ? (
              <div className="mt-3 space-y-2">
                <label className="block">
                  <span className="mb-1 block text-[11px] font-semibold uppercase tracking-wider text-muted">
                    Email
                  </span>
                  <input
                    type="email"
                    value={liveEmail}
                    onChange={(event) => setLiveEmail(event.target.value)}
                    placeholder="School account email"
                    className="input-base"
                  />
                </label>
                <label className="block">
                  <span className="mb-1 block text-[11px] font-semibold uppercase tracking-wider text-muted">
                    Password
                  </span>
                  <input
                    type="password"
                    value={livePassword}
                    onChange={(event) => setLivePassword(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                        void handleLiveLogin();
                      }
                    }}
                    placeholder="Enter password"
                    className="input-base"
                  />
                </label>
                <button
                  type="button"
                  onClick={() => void handleLiveLogin()}
                  disabled={
                    liveSessionLoading ||
                    liveSessionSubmitting ||
                    !liveEmail.trim() ||
                    !livePassword.trim()
                  }
                  className="inline-flex w-full items-center justify-center gap-2 rounded-[var(--radius-sm)] bg-accent px-3 py-2 text-[13px] font-semibold text-white transition-colors hover:bg-accent-hover disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {liveSessionSubmitting ? (
                    <LoaderCircle className="h-3.5 w-3.5 animate-spin" />
                  ) : (
                    <LogIn className="h-3.5 w-3.5" />
                  )}
                  {liveSessionSubmitting ? "Connecting..." : "Connect"}
                </button>
              </div>
            ) : (
              <div className="mt-3 rounded-[var(--radius-sm)] bg-surface-muted px-3 py-2.5">
                <p className="text-[13px] text-muted">
                  Live account access is currently unavailable for this workspace.
                </p>
              </div>
            )}
          </div>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  BarChart3,
  Bell,
  BookOpen,
  ChevronDown,
  GraduationCap,
  LayoutDashboard,
  LogOut,
  Menu,
  MessageSquare,
  Search,
  Settings,
  Smartphone,
  UserPlus,
  Users,
  Wallet,
  X,
} from "lucide-react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useState, useEffect, type ReactNode } from "react";
import { isProductionReadyModule } from "@/lib/features/module-readiness";
import type { OperationalSearchAction } from "@/lib/search/operational-search-registry";
import { resolveOperationalSearch } from "@/lib/search/operational-search-resolver";
import { usePermissions } from "@/components/providers/permission-context";
import { NotificationBell, type BadgesResponse } from "@/components/common/notifications/notification-bell";

const schoolNavItems = [
  { id: "dashboard", label: "Dashboard", href: "", icon: LayoutDashboard, requiredPermission: "" },
  { id: "students", label: "Students", href: "/students", icon: Users, requiredPermission: "students.profile.view" },
  { id: "admissions", label: "Admissions", href: "/admissions", icon: UserPlus, requiredPermission: "admissions.applications.view" },
  { id: "finance", label: "Finance", href: "/finance", icon: Wallet, requiredPermission: "finance.overview.view" },
  { id: "mpesa", label: "MPESA", href: "/mpesa", icon: Smartphone, requiredPermission: "finance.receipts.view" },
  { id: "academics", label: "Academics", href: "/academics", icon: GraduationCap, requiredPermission: "academics.overview.view" },
  { id: "exams", label: "Exams", href: "/exams", icon: BookOpen, requiredPermission: "exams.results.view" },
  { id: "reports", label: "Reports", href: "/reports", icon: BarChart3, requiredPermission: "reports.overview.view" },
  { id: "communication", label: "Communication", href: "/communication", icon: MessageSquare, requiredPermission: "communication.messages.view" },
  { id: "settings", label: "Settings", href: "/settings", icon: Settings, requiredPermission: "platform.settings.view" },
];

const globalSearchRoles = new Set(["principal", "deputy-principal", "secretary", "accountant"]);

type SchoolShellSearchResult = {
  id: string;
  label: string;
  detail: string;
  href: string;
  tag: string;
  actions?: OperationalSearchAction[];
};

export function SchoolShell({
  role,
  schoolName,
  schoolCounty,
  userName,
  userRole,
  onLogout,
  children,
}: {
  role: string;
  schoolName?: string;
  schoolCounty?: string;
  userName?: string;
  userRole?: string;
  onLogout?: () => void;
  children: ReactNode;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [searchOpen, setSearchOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const { hasPermission } = usePermissions();
  const basePath = `/school/${role}`;
  const visibleSchoolNavItems = schoolNavItems.filter((item) => isProductionReadyModule(item.id) && hasPermission(item.requiredPermission));
  const mainItems = visibleSchoolNavItems.filter((i) => i.id !== "settings");
  const bottomItems = visibleSchoolNavItems.filter((i) => i.id === "settings");
  const canUseGlobalSearch = globalSearchRoles.has(role);
  const normalizedSearchTerm = searchTerm.trim().toLowerCase();
  const [badges, setBadges] = useState<BadgesResponse | null>(null);

  useEffect(() => {
    const fetchBadges = async () => {
      try {
        const token = localStorage.getItem("auth_token") || "";
        const res = await fetch("/api/v1/notifications/badges", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          setBadges(data);
        }
      } catch (e) {
        console.error("Failed to fetch notification badges", e);
      }
    };
    fetchBadges();
    const interval = setInterval(fetchBadges, 30000);
    return () => clearInterval(interval);
  }, []);

  function toRoleHref(href: string) {
    const [rawPath, rawQuery] = href.split("?");
    const normalizedPath = rawPath.startsWith("/") ? rawPath : `/${rawPath}`;
    const schoolPath = normalizedPath.startsWith("/finance/mpesa")
      ? "/mpesa"
      : normalizedPath;

    return `${basePath}${schoolPath}${rawQuery ? `?${rawQuery}` : ""}`;
  }

  function openSearchResult(href: string) {
    setSearchTerm("");
    setSearchOpen(false);
    setNotificationsOpen(false);
    router.push(href);
  }

  function defaultResultHref(type: string) {
    const deskByType: Record<string, string> = {
      student: "/students",
      parent: "/students",
      receipt: "/finance",
      invoice: "/finance",
      mpesa: "/mpesa",
      visitor: "/visitors",
      admission: "/admissions",
      disciplineCase: "/discipline",
      healthCase: "/clinic",
      book: "/library",
      inventory: "/inventory",
      route: "/transport",
      bus: "/transport",
      assignment: "/academics",
      exam: "/exams",
      document: "/reports",
    };

    return `${basePath}${deskByType[type] ?? ""}`;
  }

  const navigationSearchResults: SchoolShellSearchResult[] = visibleSchoolNavItems.map((item) => ({
      id: `nav-${item.id}`,
      label: item.label,
      detail: `Open ${item.label.toLowerCase()} desk`,
      href: item.href ? `${basePath}${item.href}` : basePath,
      tag: "Section",
  }));
  const operationalSearchResults: SchoolShellSearchResult[] = canUseGlobalSearch && normalizedSearchTerm
    ? resolveOperationalSearch(searchTerm, { role })
      .map((record) => ({
        id: record.id,
        label: record.title,
        detail: record.detail,
        href: defaultResultHref(record.type),
        tag: record.typeLabel,
        actions: record.actions.slice(0, 3),
      }))
    : [];
  const searchResults = [...navigationSearchResults, ...operationalSearchResults];
  const visibleSearchResults = normalizedSearchTerm
    ? searchResults
        .filter((item) => `${item.label} ${item.detail} ${item.tag}`.toLowerCase().includes(normalizedSearchTerm))
        .slice(0, 6)
    : [];

  function openRoleNotifications() {
    setSearchOpen(false);
    setNotificationsOpen((value) => !value);
  }

  return (
    <div className="min-h-screen bg-[#f7f8fa]">
      {/* Desktop Sidebar */}
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-[248px] flex-col border-r border-[#e8eaed] bg-white lg:flex">
        <div className="border-b border-[#e8eaed] px-5 py-5">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 shadow-sm">
              <span className="text-sm font-bold text-white">{(schoolName ?? "GF").slice(0, 2).toUpperCase()}</span>
            </div>
            <div className="min-w-0">
              <p className="truncate text-[14px] font-semibold text-[#1a1d26]">{schoolName ?? "School portal"}</p>
              <p className="text-[11px] text-[#8b8f9a]">{schoolCounty ?? "Secure school access"}</p>
            </div>
          </div>
        </div>
        <div className="border-b border-[#e8eaed] px-5 py-3">
          <div className="flex items-center justify-between">
            <span className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#8b8f9a]">Current term</span>
            <span className="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-bold text-emerald-700">Configured live</span>
          </div>
        </div>
        <nav className="flex-1 overflow-y-auto px-3 py-3 custom-scrollbar">
          <div className="space-y-0.5">
            {mainItems.map((item) => {
              const Icon = item.icon;
              const href = item.href ? `${basePath}${item.href}` : basePath;
              const isActive = pathname === href || (item.href !== "" && pathname.startsWith(href));
              const badgeCount = badges?.byModule?.[item.id] || 0;

              return (
                <Link
                  key={item.id}
                  href={href}
                  className={`group flex items-center justify-between rounded-xl px-3 py-2.5 text-[13px] font-medium transition ${
                    isActive ? "bg-emerald-50 text-emerald-700" : "text-[#5a5e6a] hover:bg-[#f3f4f6] hover:text-[#1a1d26]"
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <Icon className={`h-4 w-4 ${isActive ? "text-emerald-600" : "text-[#8b8f9a] group-hover:text-[#5a5e6a]"}`} />
                    {item.label}
                  </div>
                  {badgeCount > 0 && (
                    <span className={`flex h-5 items-center justify-center rounded-full px-2 text-[10px] font-bold ${
                      isActive ? "bg-emerald-200 text-emerald-800" : "bg-[#e8eaed] text-[#5a5e6a] group-hover:bg-[#d1d5db]"
                    }`}>
                      {badgeCount > 99 ? "99+" : badgeCount}
                    </span>
                  )}
                </Link>
              );
            })}
          </div>
        </nav>
        <div className="border-t border-[#e8eaed] px-3 py-3 space-y-1">
          {bottomItems.map((item) => {
            const Icon = item.icon;
            const href = `${basePath}${item.href}`;
            return (
              <Link key={item.id} href={href} className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-medium text-[#5a5e6a] hover:bg-[#f3f4f6]">
                <Icon className="h-[18px] w-[18px] shrink-0" /><span>{item.label}</span>
              </Link>
            );
          })}
          <button type="button" onClick={onLogout} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-medium text-red-500/70 transition hover:bg-red-50 hover:text-red-600">
            <LogOut className="h-[18px] w-[18px] shrink-0" /><span>Sign out</span>
          </button>
        </div>
        <div className="border-t border-[#e8eaed] px-4 py-4">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 text-xs font-bold text-white shadow-sm">{(userName ?? "WM").slice(0, 2).toUpperCase()}</div>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium text-[#1a1d26]">{userName ?? "Signed-in user"}</p>
              <p className="text-[11px] text-[#8b8f9a]">{userRole ?? "School operator"}</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Overlay */}
      {mobileOpen && (
        <div className="fixed inset-0 z-40 lg:hidden">
          <div className="absolute inset-0 bg-[#1a1d26]/40 backdrop-blur-sm" onClick={() => setMobileOpen(false)} />
          <aside className="slide-in-sidebar absolute inset-y-0 left-0 w-[280px] border-r border-[#e8eaed] bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-[#e8eaed] px-5 py-4">
              <p className="text-sm font-semibold text-[#1a1d26]">{schoolName ?? "School desk"}</p>
              <button type="button" onClick={() => setMobileOpen(false)} className="rounded-lg border border-[#e8eaed] p-2 text-[#8b8f9a]"><X className="h-4 w-4" /></button>
            </div>
            <nav className="px-3 py-3">
              <div className="space-y-0.5">
                {visibleSchoolNavItems.map((item) => {
                  const Icon = item.icon;
                  const href = item.href ? `${basePath}${item.href}` : basePath;
                  const isActive = pathname === href || (item.href !== "" && pathname.startsWith(href));
                  const badgeCount = badges?.byModule?.[item.id] || 0;

                  return (
                    <Link
                      key={item.id}
                      href={href}
                      onClick={() => setMobileOpen(false)}
                      className={`group flex items-center justify-between rounded-xl px-3 py-2.5 text-sm font-medium transition ${
                        isActive ? "bg-emerald-50 text-emerald-700" : "text-[#5a5e6a] hover:bg-[#f3f4f6] hover:text-[#1a1d26]"
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Icon className={`h-[18px] w-[18px] ${isActive ? "text-emerald-600" : "text-[#8b8f9a] group-hover:text-[#5a5e6a]"}`} />
                        {item.label}
                      </div>
                      {badgeCount > 0 && (
                        <span className={`flex h-5 items-center justify-center rounded-full px-2 text-[10px] font-bold ${
                          isActive ? "bg-emerald-200 text-emerald-800" : "bg-[#e8eaed] text-[#5a5e6a] group-hover:bg-[#d1d5db]"
                        }`}>
                          {badgeCount > 99 ? "99+" : badgeCount}
                        </span>
                      )}
                    </Link>
                  );
                })}
              </div>
            </nav>
          </aside>
        </div>
      )}

      {/* Main Content */}
      <div className="lg:pl-[248px]">
        <header className="sticky top-0 z-20 border-b border-[#e8eaed] bg-white/95 backdrop-blur-lg">
          <div className="mx-auto flex h-[56px] max-w-[1360px] items-center justify-between gap-4 px-4 md:px-6 lg:px-8">
            <div className="flex items-center gap-3">
              <button type="button" onClick={() => setMobileOpen(true)} className="rounded-xl border border-[#e8eaed] p-2.5 text-[#5a5e6a] lg:hidden"><Menu className="h-4 w-4" /></button>
              <div className="hidden items-center gap-2 md:flex">
                <div className="h-2 w-2 rounded-full bg-emerald-500" />
                <span className="text-[11px] font-semibold uppercase tracking-[0.12em] text-[#8b8f9a]">School synced</span>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {canUseGlobalSearch ? (
                <div className="relative hidden md:block">
                  <label className="flex items-center gap-2 rounded-xl border border-[#e8eaed] bg-[#f7f8fa] px-3.5 py-2">
                    <Search className="h-4 w-4 text-[#9ca0ab]" />
                    <input
                      type="search"
                      aria-label="School search"
                      value={searchTerm}
                      onChange={(event) => {
                        setSearchTerm(event.target.value);
                        setSearchOpen(true);
                      }}
                      onFocus={() => setSearchOpen(true)}
                      onBlur={() => {
                        window.setTimeout(() => setSearchOpen(false), 120);
                      }}
                      onKeyDown={(event) => {
                        if (event.key === "Enter" && visibleSearchResults[0]) {
                          event.preventDefault();
                          openSearchResult(visibleSearchResults[0].href);
                        }
                      }}
                      placeholder="Search students, payments, visitors"
                      className="w-[240px] bg-transparent text-sm text-[#1a1d26] outline-none placeholder:text-[#b0b4be]"
                    />
                  </label>
                  {searchOpen && normalizedSearchTerm ? (
                    <div className="absolute right-0 top-[calc(100%+8px)] z-30 w-[340px] rounded-xl border border-[#e8eaed] bg-white p-2 shadow-xl">
                      {visibleSearchResults.length > 0 ? (
                        visibleSearchResults.map((result) => (
                          <div
                            key={result.id}
                            className="rounded-lg px-3 py-2 transition hover:bg-[#f3f4f6]"
                          >
                            <button
                              type="button"
                              onMouseDown={(event) => event.preventDefault()}
                              onClick={() => openSearchResult(result.href)}
                              className="flex w-full items-start justify-between gap-3 text-left"
                            >
                              <span className="min-w-0">
                                <span className="block text-sm font-bold text-[#1a1d26]">{result.label}</span>
                                <span className="mt-0.5 block text-xs leading-5 text-[#5a5e6a]">{result.detail}</span>
                              </span>
                              <span className="shrink-0 rounded-full bg-emerald-50 px-2 py-0.5 text-[10px] font-bold uppercase tracking-[0.12em] text-emerald-700">
                                {result.tag}
                              </span>
                            </button>
                            {result.actions?.length ? (
                              <div className="mt-2 flex flex-wrap gap-1.5">
                                {result.actions.map((action) => (
                                  <button
                                    key={`${result.id}-${action.label}`}
                                    type="button"
                                    onMouseDown={(event) => event.preventDefault()}
                                    onClick={() => openSearchResult(toRoleHref(action.href))}
                                    className="rounded-full border border-emerald-100 bg-emerald-50 px-2.5 py-1 text-[10px] font-bold text-emerald-700 transition hover:border-emerald-200 hover:bg-emerald-100"
                                  >
                                    {action.label}
                                  </button>
                                ))}
                              </div>
                            ) : null}
                          </div>
                        ))
                      ) : (
                        <div className="rounded-lg px-3 py-3 text-sm text-[#5a5e6a]">
                          No school records found for &ldquo;{searchTerm}&rdquo;.
                        </div>
                      )}
                    </div>
                  ) : null}
                </div>
              ) : null}
              <NotificationBell basePath={basePath} badges={badges} onBadgesUpdate={setBadges} />
              <button
                type="button"
                onClick={() => router.push(`${basePath}/settings`)}
                className="hidden items-center gap-2 rounded-xl border border-[#e8eaed] px-3 py-2 text-sm text-[#5a5e6a] md:flex"
              >
                <span>{userName ?? "Account"}</span>
                <ChevronDown className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>
        </header>
        <main className="mx-auto max-w-[1360px] px-4 py-5 md:px-6 lg:px-8">
          <div className="page-enter">{children}</div>
        </main>
      </div>
    </div>
  );
}

"use client";

import {
  Activity,
  Bell,
  Building2,
  ChevronDown,
  CircleDollarSign,
