                {searchTerm.trim() ? (
                  <div className="absolute right-0 top-12 z-30 w-80 overflow-hidden rounded-xl border border-border bg-white shadow-xl">
                    {searchResults.length ? (
                      searchResults.map((item) => (
                        <button
                          key={item.id}
