function Heatmap() {
  const cells = [
    86, 92, 94, 88, 95, 0, 0,
    91, 87, 96, 93, 90, 0, 0,
    82, 78, 94, 88, 97, 0, 0,
    89, 93, 92, 85, 96, 0, 0,
  ];

  return (
    <div className="grid grid-cols-7 gap-2" aria-label="Monthly attendance heatmap">
      {cells.map((value, index) => {
        const bg =
          value === 0
            ? "bg-white/6"
            : value < 84
              ? "bg-orange-300/55"
              : value < 90
                ? "bg-blue-300/55"
                : "bg-emerald-300/70";
        return (
          <span
            key={`${value}-${index}`}
            className={`h-9 rounded-[var(--radius-sm)] border border-white/10 ${bg}`}
            title={value === 0 ? "Weekend" : `${value}% attendance`}
          />
        );
      })}
    </div>
  );
}

