              </button>
              <span className="grid h-10 w-10 place-items-center rounded-[var(--radius)] border border-white/12 bg-white/12 text-xs font-black">
                MW
              </span>
            </div>
          </div>
        </header>

        <main className="mt-5 space-y-6">
