            {notice}
          </div>
          <section className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_390px]">
            <GlassCard className="overflow-hidden p-5 md:p-7">
              <div className="grid gap-6 2xl:grid-cols-[minmax(0,1fr)_280px] 2xl:items-end">
