                      <div key={message} className="rounded-[var(--radius)] border border-white/12 bg-white/[0.07] px-4 py-3 text-sm font-semibold text-white/76">
                        {message}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="rounded-[var(--radius-xl)] border border-white/12 bg-white/[0.08] p-4 shadow-[0_20px_56px_rgba(0,0,0,0.18)]">
                  <div className="flex items-center gap-4">
                    <div className="grid h-20 w-20 place-items-center rounded-[var(--radius-xl)] bg-gradient-to-br from-orange-400 to-blue-500 text-2xl font-black text-white shadow-[0_18px_38px_rgba(0,0,0,0.25)]">
                      {activeLearner.initials}
                    </div>
                    <div>
                      <p className="text-lg font-black text-white">{activeLearner.name}</p>
                      <p className="mt-1 text-sm text-white/58">{activeLearner.className} - {activeLearner.school}</p>
                    </div>
                  </div>
                  <div className="mt-4 grid grid-cols-2 gap-3">
                    <MetricPill icon={ClipboardCheck} label="Attendance" value={activeLearner.attendance} />
                    <MetricPill icon={ShieldCheck} label="Discipline" value={activeLearner.discipline} />
                    <MetricPill icon={GraduationCap} label="Average" value={activeLearner.average} />
                    <MetricPill icon={Bus} label="Bus" value={activeLearner.bus} />
                  </div>
                  <div className="mt-4 rounded-[var(--radius)] border border-emerald-300/25 bg-emerald-400/10 px-4 py-3">
                    <div className="flex items-center gap-2 text-sm font-bold text-emerald-100">
                      <LockKeyhole className="h-4 w-4" />
                      Verified school badge
                    </div>
                    <p className="mt-1 text-xs leading-5 text-emerald-100/72">Encrypted parent communication. Last login today.</p>
                  </div>
                </div>
              </div>
            </GlassCard>

            <GlassCard className="p-5">
              <SectionHeader icon={Sparkles} label="Quick summary" title="Peace-of-mind scan" />
              <div className="space-y-4">
                <ProgressDonut value={92} label="Child safety confidence" tone="good" />
                <div className="grid gap-3">
                  <div className="rounded-[var(--radius)] border border-white/12 bg-white/[0.07] px-4 py-3">
                    <p className="text-sm font-bold text-white">Financial status</p>
                    <p className="mt-1 text-sm text-orange-100/76">Exam clearance pending fee balance review.</p>
                  </div>
                  <div className="rounded-[var(--radius)] border border-white/12 bg-white/[0.07] px-4 py-3">
                    <p className="text-sm font-bold text-white">Health status</p>
                    <p className="mt-1 text-sm text-emerald-100/76">Clinic case closed. No emergency action needed.</p>
                  </div>
                </div>
              </div>
            </GlassCard>
          </section>

          <section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {[
              {
                id: "fees",
                label: "Fee Balance",
                value: dashboard?.feeBalance != null ? `KES ${dashboard?.feeBalance.toLocaleString()}` : (isLoading ? "Loading..." : "KES 0"),
                helper: "Current outstanding fee balance.",
                trend: "due",
                tone: "warning" as AlertTone,
                icon: CreditCard,
                sparkline: [80, 77, 70, 63, 58, 42, 36],
                href: "fees" as PortalSection,
              },
              {
                id: "attendance",
                label: "Attendance",
                value: dashboard?.attendance?.status || "Present",
                helper: "Latest attendance record.",
                trend: dashboard?.attendance?.attendance_date ? new Date(dashboard.attendance.attendance_date).toLocaleDateString() : "live",
                tone: "info" as AlertTone,
                icon: ClipboardCheck,
                sparkline: [74, 80, 78, 88, 91, 89, 94],
              },
              {
                id: "academics",
                label: "Academics",
                value: dashboard?.academics?.status || "Pending",
                helper: `Term info: ${dashboard?.academics?.term || "-"}`,
                trend: "new",
                tone: "good" as AlertTone,
                icon: GraduationCap,
                sparkline: [58, 61, 64, 63, 68, 70, 72],
                href: "academics" as PortalSection,
              },
              {
                id: "exams",
                label: "Upcoming Exams",
                value: "3",
                helper: "Mathematics CAT opens on Wednesday.",
                trend: "7 days",
                tone: "info" as AlertTone,
                icon: FileText,
                sparkline: [45, 54, 62, 68, 70, 76, 81],
                href: "academics" as PortalSection,
              }
            ].map((item) => (
              <KpiCard key={item.id} item={item} routeMode={routeMode} />
            ))}
          </section>

          <GlassCard className="p-5">
            <SectionHeader icon={Home} label="Parent action center" title="Fast actions for today" />
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {([
                  { id: "fees", label: "Pay with M-PESA", detail: "Open the verified fee account.", icon: CreditCard, href: "fees" as PortalSection, tone: "warning" as AlertTone },
                  { id: "message", label: "Message Teacher", detail: "Ask a class or welfare question.", icon: MessageCircle, href: "messages" as PortalSection, tone: "info" as AlertTone },
                  { id: "results", label: "Open Results", detail: "Review CAT and exam progress.", icon: GraduationCap, href: "academics" as PortalSection, tone: "info" as AlertTone },
                  { id: "health", label: "Clinic Log", detail: "View nurse remarks and care notes.", icon: HeartPulse, href: "health" as PortalSection, tone: "good" as AlertTone },
                ]).map((item) => (
                  <ActionButton
                    key={item.id}
                    item={item}
                    routeMode={routeMode}
                    onAction={setNotice}
                    learnerName={activeLearnerName}
                    feedCount={visibleLiveFeed.length}
                  />
                ))}
            </div>
          </GlassCard>

          <section className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
            <div className="space-y-6">
              <GlassCard id="alerts" className="p-5">
                <SectionHeader
                  icon={AlertTriangle}
                  label="Live risk feed"
                  title="Real-time alerts center"
                  action={
                    <span className="rounded-full border border-red-300/30 bg-red-400/12 px-3 py-1.5 text-xs font-bold text-red-100">
