"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { DataTable } from "@/components/ui/data-table";
import { Modal } from "@/components/ui/modal";
import { Tabs } from "@/components/ui/tabs";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { MetricGrid } from "@/components/experience/metric-grid";
import { StatusPill } from "@/components/ui/status-pill";
import { getSchoolWorkspace, type SchoolExperienceRole, buildSchoolStudentHref } from "@/lib/experiences/school-data";
import { AcademicSetup } from "@/components/modules/academics/AcademicSetup";
import { MarksEntryTable } from "@/components/modules/exams/MarksEntryTable";
import { ReportCardGenerator } from "@/components/modules/exams/ReportCardGenerator";

import type { SchoolRouteMode } from "@/components/school/school-pages";

export function SchoolAcademicsPage({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
}) {
  const { model } = getSchoolWorkspace(role, tenantSlug);
  const [summaryData, setSummaryData] = useState<any>(null);
  const [summaryLoading, setSummaryLoading] = useState(true);

  useEffect(() => {
    async function loadSummary() {
      setSummaryLoading(true);
      try {
        const response = await fetch(buildBillingApiPath("/api/academics/summary", tenantSlug), {
          cache: "no-store",
        });
        if (response.ok) {
          setSummaryData(await response.json());
        }
      } catch (e) {
      } finally {
        setSummaryLoading(false);
      }
    }
    loadSummary();
  }, [tenantSlug]);

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Academics"
        title="CBC academics"
        description="Marks entry, subject oversight, report cards, and classroom performance in a structure that feels familiar to schools."
      />
      {!summaryLoading && summaryData ? (
        <MetricGrid
          columns="three"
          items={[
            {
              id: "exam",
              label: "Next Exam",
              value: summaryData.nextExam || "Not scheduled",
              helper: "Upcoming assessments",
              trend: "Stable",
            },
            {
              id: "grading",
              label: "Grading Queue",
              value: summaryData.gradingQueue || "0 pending",
              helper: "Assignments to grade",
            },
            {
              id: "performance",
              label: "Performance Trend",
              value: summaryData.performanceTrend || "Stable",
              helper: "School-wide average",
              trend: "Stable",
            },
          ]}
        />
      ) : (
        <MetricGrid
          items={model.academics.summary.map((item) => ({
            id: item.id,
            label: item.label,
            value: item.value,
            helper: item.helper,
          }))}
        />
      )}
      <Tabs
        items={[
          {
            id: "setup",
            label: "Academic Setup",
            panel: <AcademicSetup tenantId={tenantSlug || undefined} />,
          },
          {
            id: "marks",
            label: "Marks Entry",
            panel: (
              <MarksEntryTable 
                tenantId={tenantSlug || undefined} 
                examSeriesId="series-uuid" 
                assessmentId="assessment-uuid" 
                classSectionId="class-uuid" 
                subjectId="subject-uuid" 
                academicTermId="term-uuid" 
              />
            ),
          },
          {
            id: "report-cards",
            label: "Publish Reports",
            panel: (
              <ReportCardGenerator 
                tenantId={tenantSlug || undefined} 
                examSeriesId="series-uuid" 
              />
            ),
          },
        ]}
      />
    </div>
  );
}

"use client";

import { DashboardEngine } from "@/components/dashboard/dashboard-engine";
import { FeeStructuresWorkspace } from "@/components/school/accountant/fee-structures-workspace";
import { InvoicesWorkspace } from "@/components/school/accountant/invoices-workspace";
import { PaymentsWorkspace } from "@/components/school/accountant/payments-workspace";
import { MPesaReconciliationWorkspace } from "@/components/school/accountant/m-pesa-reconciliation-workspace";
import { OverviewWorkspace } from "@/components/school/accountant/overview-workspace";
import { ExpensesWorkspace } from "@/components/school/accountant/expenses-workspace";
import { ArrearsWorkspace } from "@/components/school/accountant/arrears-workspace";
import { ReceiptsWorkspace } from "@/components/school/accountant/receipts-workspace";
import { ReportsWorkspace } from "@/components/school/accountant/reports-workspace";
import { WaiversDiscountsWorkspace } from "@/components/school/accountant/waivers-discounts-workspace";
import type { SchoolExperienceRole } from "@/lib/experiences/school-data";
import type { SchoolRouteMode } from "@/components/school/school-pages";

export function AccountantCommandCenter({ 
  routeMode,
  activeSection,
  role,
  tenantSlug
}: { 
  routeMode?: SchoolRouteMode;
  activeSection?: string;
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
}) {
  if (activeSection === "fee-structures") {
    return <FeeStructuresWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="fee-structures" />;
  }
  if (activeSection === "invoices") {
    return <InvoicesWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="invoices" />;
  }
  if (activeSection === "payments") {
    return <PaymentsWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="payments" />;
  }
  if (activeSection === "mpesa") {
    return <MPesaReconciliationWorkspace role={role} tenantSlug={tenantSlug} />;
  }
  if (activeSection === "expenses") {
    return <ExpensesWorkspace />;
  }
  if (activeSection === "arrears") {
    return <ArrearsWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="arrears" />;
  }
  if (activeSection === "receipts") {
    return <ReceiptsWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="receipts" />;
  }
  if (activeSection === "reports") {
    return <ReportsWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="reports" />;
  }
  if (activeSection === "waivers-discounts") {
    return <WaiversDiscountsWorkspace role={role} tenantSlug={tenantSlug} routeMode={routeMode ?? "hosted"} activeSection="waivers-discounts" />;
  }
  if (activeSection === "overview") {
    // We haven't built this one fully isolated, maybe just pass it down or show dashboard
    // The user didn't mention it explicitly but "Overview" might be the dashboard
    return <DashboardEngine role="accountant" />;
  }

  return <DashboardEngine role="accountant" />;
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { SchoolExperienceRole } from "@/lib/experiences/school-data";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { DataTable } from "@/components/ui/data-table";
import { Button } from "@/components/ui/button";
import { buildBillingApiPath, formatMinorKes } from "@/lib/billing/billing-utils";
import { StudentFeeBalanceResponse } from "@/components/school/school-pages";

type SchoolRouteMode = "hosted" | "public";

export function ArrearsWorkspace({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
  routeMode?: SchoolRouteMode;
  activeSection?: string;
}) {
  const [balances, setBalances] = useState<StudentFeeBalanceResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadArrears() {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(
          buildBillingApiPath("/api/billing/student-balances", tenantSlug || "demo"),
          { cache: "no-store" }
        );

        if (!response.ok) {
          throw new Error("Failed to load student balances.");
        }

        const data = (await response.json()) as StudentFeeBalanceResponse[];
        setBalances(data);
      } catch (e: any) {
        setError(e.message || "An error occurred");
      } finally {
        setLoading(false);
      }
    }

    loadArrears();
  }, [tenantSlug]);

  const arrears = useMemo(() => {
    return balances.filter(b => {
      try {
        return BigInt(b.balance_amount_minor) > BigInt(0);
      } catch {
        return false;
      }
    });
  }, [balances]);

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Accountant"
        title="Student Arrears"
        description="View and manage outstanding fee balances for all students."
        actions={
          <Button variant="default" disabled={loading || arrears.length === 0}>
            Send Reminders
          </Button>
        }
      />

      <div className="rounded-md border border-slate-200 bg-white p-6 shadow-sm">
        {error ? (
          <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
            {error}
          </div>
        ) : (
          <DataTable
            rows={arrears}
            getRowKey={(row: any) => row.student_id || String(Math.random())}
            columns={[
              { id: "student_id", header: "Student ID", render: (row: any) => row.student_id },
              { id: "student_name", header: "Student Name", render: (row: any) => row.student_name || "Unknown" },
              { id: "invoiced_amount_minor", header: "Total Invoiced", render: (row: any) => formatMinorKes(row.invoiced_amount_minor) },
              { id: "paid_amount_minor", header: "Total Paid", render: (row: any) => formatMinorKes(row.paid_amount_minor) },
              { 
                id: "balance_amount_minor", 
                header: "Arrears Balance", 
                render: (row: any) => (
                  <span className="font-semibold text-red-600">
                    {formatMinorKes(row.balance_amount_minor)}
                  </span>
                )
              }
            ]}
            emptyMessage="No students currently in arrears."
          />
        )}
      </div>
    </div>
  );
}

