          </label>
          <label className="space-y-2 text-sm text-foreground md:col-span-2">
            <span className="font-medium">Payer name</span>
            <input
              aria-label="Payment payer name"
              value={paymentDraft.payer_name}
              onChange={(event) => {
                setPaymentDraft((current) => ({ ...current, payer_name: event.target.value }));
                setPaymentError(null);
              }}
              className="input-base"
              placeholder="Parent or payer name"
            />
          </label>
          <label className="space-y-2 text-sm text-foreground md:col-span-2">
            <span className="font-medium">Reference</span>
            <input
              aria-label="Payment reference"
              value={paymentDraft.reference}
              onChange={(event) => {
                setPaymentDraft((current) => ({ ...current, reference: event.target.value }));
                setPaymentError(null);
              }}
              className="input-base"
              placeholder="Payment reference"
            />
          </label>
        </div>
        </div>
      </Modal>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { SchoolExperienceRole } from "@/lib/experiences/school-data";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { DataTable } from "@/components/ui/data-table";
import { buildBillingApiPath, formatActivityDate, formatMinorKes } from "@/lib/billing/billing-utils";
import { StatusPill } from "@/components/ui/status-pill";
import { FinanceActivityResponse, FinanceActivityRow } from "@/components/school/school-pages";
import { Button } from "@/components/ui/button";

type SchoolRouteMode = "hosted" | "public";

export function ReceiptsWorkspace({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
  routeMode?: SchoolRouteMode;
  activeSection?: string;
}) {
  const [activities, setActivities] = useState<FinanceActivityResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadReceipts() {
      setLoading(true);
      setError(null);
      try {
        // Fetch up to 100 recent activities to filter receipts
        const response = await fetch(
          buildBillingApiPath("/api/billing/finance-activity?limit=100&offset=0", tenantSlug || "demo"),
          { cache: "no-store" }
        );

        if (!response.ok) {
          throw new Error("Failed to load receipts.");
        }

        const data = (await response.json()) as FinanceActivityResponse[];
        setActivities(data);
      } catch (e: any) {
        setError(e.message || "An error occurred");
      } finally {
        setLoading(false);
      }
    }

    loadReceipts();
  }, [tenantSlug]);

  const rows = useMemo(() => {
    return activities
      .filter((activity) => activity.kind === "receipt")
      .map((activity) => ({
        id: activity.id,
        student: activity.student_name ?? activity.student_id ?? "Unknown",
        amount: formatMinorKes(activity.amount_minor),
        method: activity.method,
        date: formatActivityDate(activity.occurred_at),
        reference: activity.reference,
        status: activity.status,
        statusTone: activity.status === "completed" || activity.status === "cleared" ? "ok" : "warning",
      } as FinanceActivityRow));
  }, [activities]);

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Accountant"
        title="Receipts"
        description="View and manage all payment receipts."
        actions={
          <Button variant="default">
            Record Manual Receipt
          </Button>
        }
      />

      <div className="rounded-md border border-slate-200 bg-white p-6 shadow-sm">
        {error ? (
          <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
            {error}
          </div>
        ) : (
          <DataTable
            rows={rows}
            getRowKey={(row: any) => row.id || String(Math.random())}
            columns={[
              { id: "date", header: "Date", render: (row: any) => row.date },
              { id: "student", header: "Student", render: (row: any) => row.student },
              { id: "amount", header: "Amount", render: (row: any) => row.amount },
              { id: "method", header: "Method", render: (row: any) => row.method },
              { id: "reference", header: "Reference", render: (row: any) => row.reference },
              {
                id: "status",
                header: "Status",
                render: (row: any) => <StatusPill tone={row.statusTone} label={row.status} />,
              },
              {
                id: "actions",
                header: "",
                render: () => (
                  <Button variant="ghost" size="sm">
                    View
                  </Button>
                )
              }
            ]}
            emptyMessage="No receipts found."
          />
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { SchoolExperienceRole } from "@/lib/experiences/school-data";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { buildBillingApiPath } from "@/lib/billing/billing-utils";
import { downloadTextFile, CsvReportArtifactResponse } from "@/lib/dashboard/export";
import { Button } from "@/components/ui/button";

type SchoolRouteMode = "hosted" | "public";

export function ReportsWorkspace({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
  routeMode?: SchoolRouteMode;
  activeSection?: string;
}) {
  const [downloading, setDownloading] = useState<Record<string, boolean>>({});
  const [error, setError] = useState<string | null>(null);

  const handleDownload = async (reportId: string, apiPath: string) => {
    setDownloading(prev => ({ ...prev, [reportId]: true }));
    setError(null);
    try {
      const response = await fetch(buildBillingApiPath(apiPath, tenantSlug || "demo"), {
        cache: "no-store"
      });

      if (!response.ok) {
        throw new Error(`Failed to generate ${reportId} report`);
      }

      const payload = (await response.json()) as CsvReportArtifactResponse;
      downloadTextFile({
        filename: payload.filename,
        content: payload.csv,
        mimeType: payload.content_type,
      });
    } catch (e: any) {
      setError(e.message || "An error occurred during report generation");
    } finally {
      setDownloading(prev => ({ ...prev, [reportId]: false }));
    }
  };

  const reports = [
    {
      id: "student-balances",
      title: "Student Balances Report",
      description: "A complete CSV export of all student fee balances and total amounts invoiced.",
      apiPath: "/api/billing/student-balances/csv"
    },
    {
      id: "finance-reconciliation",
      title: "Finance Reconciliation",
      description: "A detailed reconciliation of expected vs collected payments over the current period.",
      apiPath: "/api/billing/reconciliation/csv"
    }
  ];

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Accountant"
        title="Finance Reports"
        description="Generate and download standard financial reports for auditing and record-keeping."
      />

      {error && (
        <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
          {error}
        </div>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        {reports.map(report => (
          <div key={report.id} className="flex flex-col justify-between rounded-md border border-slate-200 bg-white p-6 shadow-sm">
            <div>
              <h3 className="text-lg font-medium text-slate-900">{report.title}</h3>
              <p className="mt-2 text-sm text-slate-500">{report.description}</p>
            </div>
            <div className="mt-6">
              <Button 
                onClick={() => handleDownload(report.id, report.apiPath)}
                disabled={downloading[report.id]}
              >
                {downloading[report.id] ? "Generating..." : "Download CSV"}
              </Button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { SchoolExperienceRole } from "@/lib/experiences/school-data";
import { SchoolPageHeader } from "@/components/school/school-page-header";
import { DataTable } from "@/components/ui/data-table";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { buildBillingApiPath } from "@/lib/billing/billing-utils";
import { StatusPill } from "@/components/ui/status-pill";

type SchoolRouteMode = "hosted" | "public";

export function WaiversDiscountsWorkspace({
  role,
  tenantSlug,
}: {
  role: SchoolExperienceRole;
  tenantSlug?: string | null;
  routeMode?: SchoolRouteMode;
  activeSection?: string;
}) {
  const [waivers, setWaivers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [showModal, setShowModal] = useState(false);
  const [formDraft, setFormDraft] = useState({ studentId: "", amount: "", reason: "" });
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    async function loadWaivers() {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(
          buildBillingApiPath("/api/billing/waivers", tenantSlug || "demo"),
          { cache: "no-store" }
        );

        if (!response.ok) {
          throw new Error("Waivers endpoints are not fully implemented yet in the backend.");
        }

        const data = await response.json();
        setWaivers(data);
      } catch (e: any) {
        setError(e.message || "An error occurred");
      } finally {
        setLoading(false);
      }
    }

    loadWaivers();
  }, [tenantSlug]);

  async function handleApplyWaiver(e: React.FormEvent) {
    e.preventDefault();
    if (!formDraft.studentId || !formDraft.amount || !formDraft.reason) {
      setSubmitError("Please fill out all fields.");
      return;
    }
    setSubmitError(null);
    setSubmitting(true);

    try {
      const response = await fetch(buildBillingApiPath("/api/billing/waivers", tenantSlug || "demo"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formDraft),
      });

      if (!response.ok) {
        throw new Error("Failed to apply waiver. The backend endpoint might not be ready.");
      }

      setShowModal(false);
      // Reload logic here if we wanted
    } catch (e: any) {
      setSubmitError(e.message);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="space-y-6">
      <SchoolPageHeader
        eyebrow="Accountant"
        title="Waivers & Discounts"
        description="Manage fee waivers, discounts, and bursary allocations."
        actions={
          <Button onClick={() => setShowModal(true)} disabled={loading}>
            Apply Waiver
          </Button>
        }
      />

      <div className="rounded-md border border-slate-200 bg-white p-6 shadow-sm">
        {error ? (
          <div className="rounded-md bg-red-50 p-4 text-sm text-red-600">
            {error}
          </div>
        ) : (
          <DataTable
            rows={waivers}
            getRowKey={(row: any) => row.id || String(Math.random())}
            columns={[
              { id: "created_at", header: "Date", render: (row: any) => row.created_at },
              { id: "student_name", header: "Student", render: (row: any) => row.student_name },
              { id: "amount", header: "Amount", render: (row: any) => row.amount },
              { id: "reason", header: "Reason", render: (row: any) => row.reason },
              {
                id: "status",
                header: "Status",
                render: (row: any) => <StatusPill tone={row.status === "approved" ? "ok" : "warning"} label={row.status} />,
              },
            ]}
            emptyMessage="No waivers or discounts found."
          />
        )}
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Apply Fee Waiver">
        <form onSubmit={handleApplyWaiver} className="space-y-4 py-4">
          {submitError && (
            <div className="rounded bg-red-50 p-3 text-sm text-red-600">
              {submitError}
            </div>
          )}

          <div className="space-y-1">
            <label className="text-sm font-medium">Student ID / Name</label>
            <input
              type="text"
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.studentId}
              onChange={(e) => setFormDraft({ ...formDraft, studentId: e.target.value })}
              placeholder="e.g. STU-123"
            />
          </div>

          <div className="space-y-1">
            <label className="text-sm font-medium">Amount (KES)</label>
            <input
              type="number"
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.amount}
              onChange={(e) => setFormDraft({ ...formDraft, amount: e.target.value })}
              placeholder="0.00"
            />
          </div>

          <div className="space-y-1">
            <label className="text-sm font-medium">Reason</label>
            <textarea
              className="w-full rounded border border-slate-300 p-2 text-sm"
              value={formDraft.reason}
              onChange={(e) => setFormDraft({ ...formDraft, reason: e.target.value })}
              placeholder="e.g. Merit scholarship"
              rows={3}
            />
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-slate-100">
            <Button type="button" variant="outline" onClick={() => setShowModal(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? "Applying..." : "Apply Waiver"}
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

"use client";

import { useState } from "react";
import { BookOpen, Layers, Calendar, Plus, Settings2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";

export function ClassesStreamsWorkspace() {
  const [activeTab, setActiveTab] = useState<"sections" | "years">("sections");

  const { data: yearsList, refetch: refetchYears } = useSchoolQuery<any[]>("/api/academics/academic-years", { enabled: activeTab === "years" });
  const { data: termsList, refetch: refetchTerms } = useSchoolQuery<any[]>("/api/academics/academic-terms", { enabled: activeTab === "years" });
  const { data: classSectionsList, refetch: refetchSections } = useSchoolQuery<any[]>("/api/academics/class-sections", { enabled: activeTab === "sections" });

  const createYearMutation = useSchoolMutation("/api/academics/years");
  const createTermMutation = useSchoolMutation("/api/academics/terms");
  const createSectionMutation = useSchoolMutation("/api/academics/class-sections");

  const [newYearName, setNewYearName] = useState("");
  const [newYearStart, setNewYearStart] = useState("");
  const [newYearEnd, setNewYearEnd] = useState("");

  const handleCreateYear = async () => {
    if (!newYearName || !newYearStart || !newYearEnd) return;
    await createYearMutation.mutateAsync({ name: newYearName, starts_on: newYearStart, ends_on: newYearEnd });
    setNewYearName(""); setNewYearStart(""); setNewYearEnd("");
    refetchYears();
  };

  const [newSecName, setNewSecName] = useState("");
  const [newSecGrade, setNewSecGrade] = useState("");
  const [newSecCapacity, setNewSecCapacity] = useState(30);

  const handleCreateSection = async () => {
    if (!newSecName || !newSecGrade) return;
    // Assuming academic_year_id is required. We'll grab the first year or empty for now if no years exist.
    // In a real app, there'd be a dropdown for the current academic year.
    const yearId = yearsList?.[0]?.id || "";
    await createSectionMutation.mutateAsync({ 
      academic_year_id: yearId, 
      name: newSecName, 
      grade_level: newSecGrade, 
      capacity: newSecCapacity 
    });
    setNewSecName(""); setNewSecGrade(""); setNewSecCapacity(30);
    refetchSections();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Classes & Streams</h2>
          <p className="text-sm text-slate-500 mt-1">Manage academic structure, years, terms, and classes.</p>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 pb-0">
        <button
          onClick={() => setActiveTab("sections")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "sections" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Layers className="w-4 h-4" />
          Class Sections
        </button>
        <button
          onClick={() => setActiveTab("years")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "years" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Calendar className="w-4 h-4" />
          Academic Calendar
        </button>
      </div>

      {activeTab === "sections" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Add Class Section
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Form 1 East"
                    value={newSecName} onChange={e => setNewSecName(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Grade Level</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Form 1"
                    value={newSecGrade} onChange={e => setNewSecGrade(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Capacity</label>
                  <input 
                    type="number" 
                    value={newSecCapacity} onChange={e => setNewSecCapacity(Number(e.target.value))}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <Button onClick={handleCreateSection} disabled={createSectionMutation.isPending || !newSecName || !newSecGrade} className="w-full">
                  Create Class
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Name</th>
                    <th className="px-4 py-3 font-medium">Grade</th>
                    <th className="px-4 py-3 font-medium">Capacity</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {classSectionsList?.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-8 text-center text-slate-500">No classes defined yet.</td></tr>
                  ) : (
                    classSectionsList?.map((sec: any) => (
                      <tr key={sec.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{sec.name}</td>
                        <td className="px-4 py-3">{sec.grade_level}</td>
                        <td className="px-4 py-3 text-slate-500">{sec.capacity || 'Not set'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}

      {activeTab === "years" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Add Academic Year
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Year Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. 2026-2027"
                    value={newYearName} onChange={e => setNewYearName(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Starts On</label>
                    <input 
                      type="date" 
                      value={newYearStart} onChange={e => setNewYearStart(e.target.value)}
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Ends On</label>
                    <input 
                      type="date" 
                      value={newYearEnd} onChange={e => setNewYearEnd(e.target.value)}
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    />
                  </div>
                </div>
                <Button onClick={handleCreateYear} disabled={createYearMutation.isPending || !newYearName || !newYearStart || !newYearEnd} className="w-full">
                  Create Year
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2 space-y-4">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Academic Year</th>
                    <th className="px-4 py-3 font-medium">Starts On</th>
                    <th className="px-4 py-3 font-medium">Ends On</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {yearsList?.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-8 text-center text-slate-500">No academic years defined yet.</td></tr>
                  ) : (
                    yearsList?.map((yr: any) => (
                      <tr key={yr.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{yr.name}</td>
                        <td className="px-4 py-3">{new Date(yr.starts_on).toLocaleDateString()}</td>
                        <td className="px-4 py-3">{new Date(yr.ends_on).toLocaleDateString()}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import { Upload } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type ImportsData = {
  metrics: Record<string, number>;
  items: any[];
};

export function ImportsWorkspace() {
  const { data, isLoading } = useSchoolQuery<ImportsData>("/admin-command/admin/imports");
  const items = data?.items || [];

  return (
    <section className="rounded-2xl border border-[#D8E0EC] bg-white p-5 shadow-[0_18px_50px_rgba(7,29,73,0.08)]">
      <div className="mb-4 flex min-w-0 gap-3">
        <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#EEF5FF] text-[#1D4ED8]">
          <Upload className="h-5 w-5" aria-hidden="true" />
        </span>
        <div>
          <h2 className="text-xl font-black tracking-[-0.01em] text-[#071D49]">Data Imports</h2>
          <p className="mt-1 text-sm leading-6 text-[#64748B]">Import data in bulk.</p>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-1 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Imports</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_imports ?? 0}</div>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold">File</th>
              <th className="px-4 py-3 font-bold">Type</th>
              <th className="px-4 py-3 font-bold">Records</th>
              <th className="px-4 py-3 font-bold">Date</th>
              <th className="px-4 py-3 font-bold">Status</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">Loading...</td></tr>
            ) : items.length === 0 ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No records found. Create the first entry to get started.</td></tr>
            ) : (
              items.map((row: any, i: number) => (
                <tr key={row.id || i} className="border-t border-[#D8E0EC] hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{row.filename}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.import_type}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.record_count}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.date}</td>
                  <td className="px-4 py-3"><span className="inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap">{row.status}</span></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </section>
  );
}

"use client";

import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Card } from "@/components/ui/card";
import { Users, Banknote, BookOpen, Activity, AlertCircle, CheckCircle, Clock } from "lucide-react";
import { Button } from "@/components/ui/button";

export function OverviewWorkspace() {
  const { data: dashboard, isLoading, error } = useSchoolQuery<any>("/api/dashboard/layout");

  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center text-slate-500">
        Loading dashboard overview...
      </div>
    );
  }

  if (error || !dashboard) {
    return (
      <div className="flex h-64 flex-col items-center justify-center text-slate-500 gap-4">
        <AlertCircle className="w-8 h-8 text-rose-500" />
        <p>Failed to load dashboard overview.</p>
      </div>
    );
  }

  const { buttons, widgets } = dashboard;

  const studentsWidget = widgets.find((w: any) => w.widget_id === "students_summary");
  const financeWidget = widgets.find((w: any) => w.widget_id === "finance_summary");
  const academicsWidget = widgets.find((w: any) => w.widget_id === "academics_summary");
  const activityWidget = widgets.find((w: any) => w.widget_id === "activity_feed");

  return (
    <div className="space-y-6">
      {/* Header and Quick Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Overview</h2>
          <p className="text-sm text-slate-500 mt-1">Welcome back. Here is the operational summary of your school.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          {buttons?.map((btn: any) => (
            <Button
              key={btn.id}
              disabled={btn.state !== "ACTIVE"}
              variant={btn.state === "ACTIVE" ? "default" : "secondary"}
              className="relative"
            >
              {btn.label}
              {btn.state === "LOCKED" && (
                <span className="absolute -top-1 -right-1 w-2 h-2 rounded-full bg-rose-500" title="Locked by capabilities" />
              )}
            </Button>
          ))}
        </div>
      </div>

      {/* KPI Widgets Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        
        {/* Students Summary */}
        <Card className="p-6 border border-slate-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-medium text-slate-900 flex items-center gap-2">
              <Users className="w-5 h-5 text-blue-500" />
              Students
            </h3>
            {studentsWidget?.state === 'FAILED' && <AlertCircle className="w-4 h-4 text-rose-500"  />}
          </div>
          {studentsWidget?.state === 'ACTIVE' && studentsWidget.data ? (
            <div className="space-y-4">
              <div className="flex items-baseline gap-2">
                <span className="text-3xl font-semibold text-slate-900">{studentsWidget.data.totalStudents}</span>
                <span className="text-sm font-medium text-emerald-600">{studentsWidget.data.trendLabel}</span>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-100">
                <div>
                  <p className="text-xs text-slate-500 mb-1">New Enrollments</p>
                  <p className="text-sm font-medium text-slate-900">{studentsWidget.data.newEnrollments}</p>
                </div>
                <div>
                  <p className="text-xs text-slate-500 mb-1">Absent Today</p>
                  <p className="text-sm font-medium text-slate-900">{studentsWidget.data.absentToday}</p>
                </div>
              </div>
            </div>
          ) : (
            <p className="text-sm text-slate-500">Data unavailable.</p>
          )}
        </Card>

        {/* Finance Summary */}
        <Card className="p-6 border border-slate-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-medium text-slate-900 flex items-center gap-2">
              <Banknote className="w-5 h-5 text-emerald-500" />
              Finance
            </h3>
            {financeWidget?.state === 'FAILED' && <AlertCircle className="w-4 h-4 text-rose-500"  />}
          </div>
          {financeWidget?.state === 'ACTIVE' && financeWidget.data ? (
            <div className="space-y-4">
              <div className="flex items-baseline gap-2">
                <span className="text-3xl font-semibold text-slate-900">{financeWidget.data.collectionsToday}</span>
                <span className="text-sm font-medium text-slate-500">collected today</span>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-100">
                <div>
                  <p className="text-xs text-slate-500 mb-1">Outstanding</p>
                  <p className="text-sm font-medium text-slate-900">{financeWidget.data.outstandingInvoices}</p>
                </div>
                <div>
                  <p className="text-xs text-slate-500 mb-1">Failed</p>
                  <p className="text-sm font-medium text-rose-600">{financeWidget.data.failedPayments}</p>
                </div>
              </div>
            </div>
          ) : (
            <p className="text-sm text-slate-500">Data unavailable.</p>
          )}
        </Card>

        {/* Academics Summary */}
        <Card className="p-6 border border-slate-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-medium text-slate-900 flex items-center gap-2">
              <BookOpen className="w-5 h-5 text-purple-500" />
              Academics
            </h3>
            {academicsWidget?.state === 'FAILED' && <AlertCircle className="w-4 h-4 text-rose-500"  />}
          </div>
          {academicsWidget?.state === 'ACTIVE' && academicsWidget.data ? (
            <div className="space-y-4">
              <div className="flex flex-col gap-1">
                <span className="text-sm text-slate-500">Next Exam:</span>
                <span className="text-base font-medium text-slate-900">{academicsWidget.data.nextExam}</span>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-100">
                <div>
                  <p className="text-xs text-slate-500 mb-1">Grading Queue</p>
                  <p className="text-sm font-medium text-slate-900">{academicsWidget.data.gradingQueue}</p>
                </div>
                <div>
                  <p className="text-xs text-slate-500 mb-1">Performance Trend</p>
                  <p className="text-sm font-medium text-emerald-600">{academicsWidget.data.performanceTrend}</p>
                </div>
              </div>
            </div>
          ) : (
            <p className="text-sm text-slate-500">Data unavailable.</p>
          )}
        </Card>
      </div>

      {/* Activity Feed */}
      <Card className="border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h3 className="font-medium text-slate-900 flex items-center gap-2">
            <Activity className="w-4 h-4 text-slate-500" />
            Recent Activity
          </h3>
        </div>
        <div className="divide-y divide-slate-100">
          {activityWidget?.state === 'ACTIVE' && activityWidget.data && Array.isArray(activityWidget.data) && activityWidget.data.length > 0 ? (
            activityWidget.data.map((item: any) => (
              <div key={item.id} className="p-4 flex items-start gap-4 hover:bg-slate-50/50 transition-colors">
                <div className="mt-1">
                  {item.category === 'payment' ? <Banknote className="w-4 h-4 text-emerald-500" /> :
                   item.category === 'student' ? <Users className="w-4 h-4 text-blue-500" /> :
                   <CheckCircle className="w-4 h-4 text-slate-400" />}
                </div>
                <div className="flex-1">
                  <p className="text-sm font-medium text-slate-900">{item.title}</p>
                  <p className="text-xs text-slate-500 mt-0.5">{item.detail}</p>
                </div>
                <div className="text-right">
                  <span className="text-xs font-medium text-slate-500 flex items-center justify-end gap-1">
                    <Clock className="w-3 h-3" />
                    {item.timeLabel}
                  </span>
                  <span className="text-xs text-slate-400 block mt-0.5">{item.actor}</span>
                </div>
              </div>
            ))
          ) : (
            <div className="p-8 text-center text-slate-500">
              No recent activity found.
            </div>
          )}
        </div>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Users, UserPlus, Mail, Phone, Link as LinkIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";

export function ParentsWorkspace() {
  const [activeTab, setActiveTab] = useState<"directory" | "add">("directory");

  const { data: guardiansList, isLoading, refetch: refetchGuardians } = useSchoolQuery<any[]>("/api/students/guardians/directory", { enabled: activeTab === "directory" });
  const { data: studentsList } = useSchoolQuery<any[]>("/api/students", { enabled: activeTab === "add" });
  
  const createGuardianMutation = useSchoolMutation("/api/students/guardians");

  const [studentId, setStudentId] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [relationship, setRelationship] = useState("Father");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");

  const handleCreateGuardian = async () => {
    if (!studentId || !displayName || !relationship) return;
    await createGuardianMutation.mutateAsync({
      student_profile_id: studentId,
      display_name: displayName,
      relationship,
      email,
      phone
    });
    setStudentId("");
    setDisplayName("");
    setEmail("");
    setPhone("");
    setActiveTab("directory");
    refetchGuardians();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Parents & Guardians</h2>
          <p className="text-sm text-slate-500 mt-1">Manage guardian profiles and their linked students.</p>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 pb-0">
        <button
          onClick={() => setActiveTab("directory")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "directory" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Users className="w-4 h-4" />
          Guardians Directory
        </button>
        <button
          onClick={() => setActiveTab("add")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "add" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <UserPlus className="w-4 h-4" />
          Add Guardian
        </button>
      </div>

      {activeTab === "directory" && (
        <Card className="border border-slate-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 font-medium">Guardian Name</th>
                  <th className="px-4 py-3 font-medium">Relationship</th>
                  <th className="px-4 py-3 font-medium">Linked Student</th>
                  <th className="px-4 py-3 font-medium">Contact Details</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {isLoading ? (
                  <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-500">Loading directory...</td></tr>
                ) : guardiansList?.length === 0 ? (
                  <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-500">No guardians defined yet.</td></tr>
                ) : (
                  guardiansList?.map((g: any) => (
                    <tr key={g.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-4 py-3 font-medium text-slate-900">{g.display_name}</td>
                      <td className="px-4 py-3 capitalize">{g.relationship}</td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-1.5 text-slate-700">
                          <LinkIcon className="w-3 h-3 text-slate-400" />
                          {g.student_first_name} {g.student_last_name}
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="space-y-1">
                          {g.phone && (
                            <div className="flex items-center gap-1.5 text-xs text-slate-600">
                              <Phone className="w-3 h-3" />
                              {g.phone}
                            </div>
                          )}
                          {g.email && (
                            <div className="flex items-center gap-1.5 text-xs text-slate-600">
                              <Mail className="w-3 h-3" />
                              {g.email}
                            </div>
                          )}
                          {!g.phone && !g.email && <span className="text-xs text-slate-400">No contact info</span>}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === "add" && (
        <div className="max-w-2xl mx-auto">
          <Card className="p-6 border border-slate-200">
            <h3 className="font-medium text-slate-900 mb-6 flex items-center gap-2">
              <UserPlus className="w-5 h-5" />
              Add Guardian Profile
            </h3>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-sm font-medium text-slate-700">Link to Student</label>
                <select 
                  value={studentId}
                  onChange={e => setStudentId(e.target.value)}
                  className="flex h-10 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                >
                  <option value="">Select Student...</option>
                  {studentsList?.filter(s => s.status !== 'archived').map(s => (
                    <option key={s.id} value={s.id}>{s.first_name} {s.last_name}</option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-sm font-medium text-slate-700">Guardian Name</label>
                  <input 
                    type="text" 
                    value={displayName}
                    onChange={e => setDisplayName(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-medium text-slate-700">Relationship</label>
                  <select 
                    value={relationship}
                    onChange={e => setRelationship(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="Father">Father</option>
                    <option value="Mother">Mother</option>
                    <option value="Guardian">Guardian</option>
                    <option value="Uncle">Uncle</option>
                    <option value="Aunt">Aunt</option>
                    <option value="Grandparent">Grandparent</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-sm font-medium text-slate-700">Phone (Optional)</label>
                  <input 
                    type="text" 
                    value={phone}
                    onChange={e => setPhone(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-medium text-slate-700">Email (Optional)</label>
                  <input 
                    type="email" 
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
              </div>
              <div className="pt-4 flex justify-end">
                <Button 
                  onClick={handleCreateGuardian} 
                  disabled={createGuardianMutation.isPending || !studentId || !displayName || !relationship}
                >
                  Create Guardian Profile
                </Button>
              </div>
            </div>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { FileText, Download, PieChart, TrendingUp, Users, Banknote } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery } from "@/lib/data/school-hooks";

export function ReportsWorkspace() {
  const [activeCategory, setActiveCategory] = useState<"all" | "students" | "finance" | "academics">("all");

  const { data: reportsList, isLoading } = useSchoolQuery<any[]>("/api/admin-command/principal/reports");

  const standardReports = [
    { id: "demographics", title: "Enrollment & Demographics", desc: "Detailed breakdown of students by age, gender, and class.", icon: Users, category: "students" },
    { id: "attendance", title: "Monthly Attendance Summary", desc: "Aggregated absence rates across all grades.", icon: PieChart, category: "students" },
    { id: "fee-balances", title: "Outstanding Fee Balances", desc: "List of students with pending invoices for the current term.", icon: Banknote, category: "finance" },
    { id: "collections", title: "Revenue Collections", desc: "Daily/weekly payment mix and total collections.", icon: TrendingUp, category: "finance" },
    { id: "exam-mastersheet", title: "Term Exam Mastersheet", desc: "Comprehensive score matrix across all subjects and classes.", icon: FileText, category: "academics" },
    { id: "teacher-loads", title: "Teacher Workloads", desc: "Assigned lessons and subjects per staff member.", icon: Users, category: "academics" },
  ];

  const handleDownload = async (reportId: string) => {
    // In reality, this would fetch a blob and trigger browser download
    toast.info(`Generating report: ${reportId}. The download will begin shortly.`);
  };

  const filteredReports = activeCategory === "all" ? standardReports : standardReports.filter(r => r.category === activeCategory);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Reports Center</h2>
          <p className="text-sm text-slate-500 mt-1">Generate and download operational reports for your school.</p>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 pb-0">
        <button
          onClick={() => setActiveCategory("all")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeCategory === "all" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          All Reports
        </button>
        <button
          onClick={() => setActiveCategory("students")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeCategory === "students" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Users className="w-4 h-4" />
          Students
        </button>
        <button
          onClick={() => setActiveCategory("finance")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeCategory === "finance" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Banknote className="w-4 h-4" />
          Finance
        </button>
        <button
          onClick={() => setActiveCategory("academics")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeCategory === "academics" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <FileText className="w-4 h-4" />
          Academics
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredReports.map((report) => (
          <Card key={report.id} className="p-6 border border-slate-200 flex flex-col h-full hover:border-slate-300 transition-colors">
            <div className="flex items-start justify-between mb-4">
              <div className="p-2 bg-slate-50 rounded-md">
                <report.icon className="w-5 h-5 text-slate-700" />
              </div>
              <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">{report.category}</span>
            </div>
            <h3 className="font-medium text-slate-900 mb-2">{report.title}</h3>
            <p className="text-sm text-slate-500 mb-6 flex-1">{report.desc}</p>
            <div className="flex items-center gap-3 pt-4 border-t border-slate-100">
              <Button variant="default" size="sm" className="w-full gap-2" onClick={() => handleDownload(report.id)}>
                <Download className="w-4 h-4" /> Generate PDF
              </Button>
              <Button variant="outline" size="sm" className="w-full gap-2" onClick={() => handleDownload(report.id + "_csv")}>
                <Download className="w-4 h-4" /> Export CSV
              </Button>
            </div>
          </Card>
        ))}
      </div>

      {/* Generated Reports List (from Backend) */}
      <div className="pt-8">
        <h3 className="text-lg font-medium text-slate-900 mb-4">Recent Custom Reports</h3>
        <Card className="border border-slate-200 overflow-hidden">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
              <tr>
                <th className="px-4 py-3 font-medium">Report Name</th>
                <th className="px-4 py-3 font-medium">Requested By</th>
                <th className="px-4 py-3 font-medium">Generated At</th>
                <th className="px-4 py-3 font-medium text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-500">Loading recent reports...</td></tr>
              ) : reportsList?.length === 0 || !reportsList ? (
                <tr><td colSpan={4} className="px-4 py-8 text-center text-slate-500">No custom reports generated recently.</td></tr>
              ) : (
                reportsList?.map((r: any) => (
                  <tr key={r.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-4 py-3 font-medium text-slate-900 flex items-center gap-2">
                      <FileText className="w-4 h-4 text-slate-400" />
                      {r.name}
                    </td>
                    <td className="px-4 py-3 text-slate-500">{r.requested_by}</td>
                    <td className="px-4 py-3 text-slate-500">{new Date(r.created_at).toLocaleString()}</td>
                    <td className="px-4 py-3 text-right">
                      <Button variant="ghost" size="sm" className="h-8">Download</Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { UserPlus, CheckCircle, RotateCcw, CalendarDays, Users, FileText } from "lucide-react";
import { Card } from "@/components/ui/card";
import { StatusPill } from "@/components/ui/status-pill";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { Button } from "@/components/ui/button";
import { Modal } from "@/components/ui/modal";
import { toast } from "sonner";

export function StaffRecordsWorkspace() {
  const [activeTab, setActiveTab] = useState<"directory" | "attendance" | "leave" | "structure" | "payroll" | "performance">("directory");
  const [attendanceDate, setAttendanceDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [payslipMonth, setPayslipMonth] = useState(new Date().getMonth() + 1);
  const [payslipYear, setPayslipYear] = useState(new Date().getFullYear());

  const { data: staffList, isLoading, refetch } = useSchoolQuery<any[]>("/api/hr/staff", { enabled: activeTab === "directory" || activeTab === "leave" || activeTab === "payroll" || activeTab === "performance" });
  const { data: departmentList, refetch: refetchDepts } = useSchoolQuery<any[]>("/api/hr/departments");
  const { data: jobTitleList, refetch: refetchJobs } = useSchoolQuery<any[]>("/api/hr/job-titles");
  const { data: attendanceList, isLoading: attLoading, refetch: refetchAtt } = useSchoolQuery<any[]>(`/api/hr/attendance?date=${attendanceDate}`, { enabled: activeTab === "attendance" });
  const { data: leaveList, isLoading: leaveLoading, refetch: refetchLeave } = useSchoolQuery<any[]>("/api/hr/leave", { enabled: activeTab === "leave" });
  const { data: bandList, refetch: refetchBands } = useSchoolQuery<any[]>("/api/hr/payroll/bands", { enabled: activeTab === "payroll" || activeTab === "directory" });
  const { data: payslipList, refetch: refetchPayslips } = useSchoolQuery<any[]>(`/api/hr/payroll/payslips?month=${payslipMonth}&year=${payslipYear}`, { enabled: activeTab === "payroll" });
  const { data: reviewsList, refetch: refetchReviews } = useSchoolQuery<any[]>("/api/hr/performance/reviews", { enabled: activeTab === "performance" });
  const { data: disciplinaryList, refetch: refetchDisciplinary } = useSchoolQuery<any[]>("/api/hr/performance/disciplinary", { enabled: activeTab === "performance" });
  
  const inviteMutation = useSchoolMutation("/api/hr/staff/invite");
  const approveMutation = useSchoolMutation("/api/hr/staff/approve");
  const reactivateMutation = useSchoolMutation("/api/hr/staff/reactivate");
  const acceptInviteMutation = useSchoolMutation("/api/hr/staff/accept-invite");
  const completeProfileMutation = useSchoolMutation("/api/hr/staff/complete-profile");
  const markAttendanceMutation = useSchoolMutation("/api/hr/attendance");
  const requestLeaveMutation = useSchoolMutation("/api/hr/leave/request");
  const updateLeaveStatusMutation = useSchoolMutation((vars: { id: string; status: string; reason?: string }) => `/api/hr/leave/${vars.id}/status`);
  const createDeptMutation = useSchoolMutation("/api/hr/departments");
  const createJobTitleMutation = useSchoolMutation("/api/hr/job-titles");
  const assignRoleMutation = useSchoolMutation("/api/hr/staff/role", "PATCH");
  const createBandMutation = useSchoolMutation("/api/hr/payroll/bands");
  const setSalaryMutation = useSchoolMutation("/api/hr/staff/salary", "PATCH");
  const generatePayslipMutation = useSchoolMutation("/api/hr/payroll/payslips");
  const createReviewMutation = useSchoolMutation("/api/hr/performance/reviews");
  const createDisciplinaryMutation = useSchoolMutation("/api/hr/performance/disciplinary");

  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteName, setInviteName] = useState("");
  
  const handleInvite = async () => {
    if (!inviteEmail || !inviteName) return;
    await inviteMutation.mutateAsync({ email: inviteEmail, display_name: inviteName });
    setInviteEmail("");
    setInviteName("");
    refetch();
  };

  const handleApprove = async (id: string) => {
    const defaultStaffNumber = `STF-${id.replace(/[^a-zA-Z0-9]/g, "").slice(-4).padStart(4, "0").toUpperCase()}`;
    const num = prompt("Enter new Staff Number", defaultStaffNumber);
    if (!num) return;
    await approveMutation.mutateAsync({
      staff_profile_id: id,
      staff_number: num,
      contract: { role_title: "Teacher", starts_on: new Date().toISOString() }
    });
    refetch();
  };

  const handleReactivate = async (id: string) => {
    await reactivateMutation.mutateAsync({ staff_profile_id: id, reason: "Returned to duty" });
    refetch();
  };

  const handleMarkAttendance = async (id: string, status: string) => {
    await markAttendanceMutation.mutateAsync({ staff_profile_id: id, date: attendanceDate, status });
    refetchAtt();
  };

  const [leaveStaffId, setLeaveStaffId] = useState("");
  const [leaveType, setLeaveType] = useState("annual");
  const [leaveDays, setLeaveDays] = useState(1);
  const [leaveReason, setLeaveReason] = useState("");

  const handleRequestLeave = async () => {
    if (!leaveStaffId || leaveDays < 1) return;
    await requestLeaveMutation.mutateAsync({
      staff_profile_id: leaveStaffId,
      leave_type: leaveType,
      requested_days: leaveDays,
      reason: leaveReason
    });
    setLeaveStaffId("");
    setLeaveReason("");
    setLeaveDays(1);
    refetchLeave();
  };

  const handleUpdateLeaveStatus = async (id: string, status: "approved" | "rejected", isOverride = false) => {
    let reason = "";
    if (isOverride) {
      const p = prompt("Enter override reason for approval beyond balance (or leave rejection reason):");
      if (!p) return;
      reason = p;
    }
    try {
      await updateLeaveStatusMutation.mutateAsync({ id, status, reason });
    } catch (e: any) {
      if (e.message?.includes("override")) {
        handleUpdateLeaveStatus(id, status, true);
        return;
      }
      toast.error(e.message || "An error occurred");
    }
    refetchLeave();
  };

  const [newDeptName, setNewDeptName] = useState("");
  const [newJobTitle, setNewJobTitle] = useState("");
  const [newJobDeptId, setNewJobDeptId] = useState("");

  const handleCreateDept = async () => {
    if (!newDeptName) return;
    await createDeptMutation.mutateAsync({ name: newDeptName });
    setNewDeptName("");
    refetchDepts();
  };

  const handleCreateJob = async () => {
    if (!newJobTitle) return;
    await createJobTitleMutation.mutateAsync({ title: newJobTitle, department_id: newJobDeptId || undefined });
    setNewJobTitle("");
    refetchJobs();
  };

  const [assignRoleStaffId, setAssignRoleStaffId] = useState("");
  const [assignDeptId, setAssignDeptId] = useState("");
  const [assignJobId, setAssignJobId] = useState("");

  const handleAssignRole = async () => {
    if (!assignRoleStaffId) return;
    await assignRoleMutation.mutateAsync({ staff_profile_id: assignRoleStaffId, department_id: assignDeptId || undefined, job_title_id: assignJobId || undefined });
    setAssignRoleStaffId("");
    refetch();
  };

  const [newBandName, setNewBandName] = useState("");
  const [newBandSalary, setNewBandSalary] = useState<number | "">("");

  const handleCreateBand = async () => {
    if (!newBandName || !newBandSalary) return;
    await createBandMutation.mutateAsync({ name: newBandName, base_salary: Number(newBandSalary) });
    setNewBandName("");
    setNewBandSalary("");
    refetchBands();
  };

  const [assignSalaryStaffId, setAssignSalaryStaffId] = useState("");
  const [assignBandId, setAssignBandId] = useState("");
  const [assignCustomSalary, setAssignCustomSalary] = useState<number | "">("");

  const handleAssignSalary = async () => {
    if (!assignSalaryStaffId) return;
    await setSalaryMutation.mutateAsync({ staff_profile_id: assignSalaryStaffId, payroll_band_id: assignBandId || undefined, custom_base_salary: assignCustomSalary ? Number(assignCustomSalary) : undefined });
    setAssignSalaryStaffId("");
    refetch();
  };

  const [generatePayslipStaffId, setGeneratePayslipStaffId] = useState("");
  const [generateDeductions, setGenerateDeductions] = useState<number>(0);
  const [generateBonuses, setGenerateBonuses] = useState<number>(0);

  const handleGeneratePayslip = async () => {
    if (!generatePayslipStaffId) return;
    try {
      await generatePayslipMutation.mutateAsync({
        staff_profile_id: generatePayslipStaffId,
        month: payslipMonth,
        year: payslipYear,
        deductions: generateDeductions,
        bonuses: generateBonuses
      });
      setGeneratePayslipStaffId("");
      refetchPayslips();
      toast.success("Payslip generated successfully");
    } catch (e: any) {
      toast.error(e.message || "Failed to generate payslip");
    }
  };

  const [reviewStaffId, setReviewStaffId] = useState("");
  const [reviewDate, setReviewDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [reviewScore, setReviewScore] = useState<number>(3);
  const [reviewComments, setReviewComments] = useState("");
  const [reviewGoals, setReviewGoals] = useState("");

  const handleCreateReview = async () => {
    if (!reviewStaffId || !reviewComments) return;
    await createReviewMutation.mutateAsync({ staff_profile_id: reviewStaffId, review_date: reviewDate, score: reviewScore, comments: reviewComments, goals_for_next_period: reviewGoals });
    setReviewStaffId("");
    setReviewComments("");
    setReviewGoals("");
    refetchReviews();
  };

  const [discStaffId, setDiscStaffId] = useState("");
  const [discDate, setDiscDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [discSeverity, setDiscSeverity] = useState<"low" | "medium" | "high" | "critical">("low");
  const [discDescription, setDiscDescription] = useState("");
  const [discAction, setDiscAction] = useState("");

  const handleCreateDisciplinary = async () => {
    if (!discStaffId || !discDescription) return;
    await createDisciplinaryMutation.mutateAsync({ staff_profile_id: discStaffId, incident_date: discDate, severity: discSeverity, description: discDescription, action_taken: discAction });
    setDiscStaffId("");
    setDiscDescription("");
    setDiscAction("");
    refetchDisciplinary();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold tracking-tight">Staff Lifecycle Management</h2>
          <p className="text-sm text-slate-500">Invite, approve, and manage the complete lifecycle of school staff.</p>
        </div>
      </div>

      <div className="flex border-b border-slate-200">
        <button
          onClick={() => setActiveTab("directory")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "directory" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Users className="w-4 h-4" />
          Staff Directory
        </button>
        <button
          onClick={() => setActiveTab("attendance")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "attendance" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <CalendarDays className="w-4 h-4" />
          Daily Attendance
        </button>
        <button
          onClick={() => setActiveTab("leave")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "leave" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <FileText className="w-4 h-4" />
          Leave Management
        </button>
        <button
          onClick={() => setActiveTab("structure")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "structure" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <RotateCcw className="w-4 h-4" />
          Structure & Roles
        </button>
        <button
          onClick={() => setActiveTab("payroll")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "payroll" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <FileText className="w-4 h-4" />
          Payroll & Comp
        </button>
        <button
          onClick={() => setActiveTab("performance")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "performance" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <CheckCircle className="w-4 h-4" />
          Performance & HR
        </button>
      </div>

      {activeTab === "directory" && (
        <div className="space-y-6">
          <Card className="p-4 border border-slate-200">
            <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
              <UserPlus className="w-4 h-4" />
              Invite New Staff
            </h3>
            <div className="flex flex-wrap gap-4 items-end">
              <div className="space-y-1">
                <label className="text-xs font-medium text-slate-700">Display Name</label>
                <input 
                  value={inviteName} 
                  onChange={e => setInviteName(e.target.value)} 
                  placeholder="Jane Doe" 
                  className="flex h-9 w-64 rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors placeholder:text-slate-500 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950 disabled:cursor-not-allowed disabled:opacity-50" 
                />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-medium text-slate-700">Email Address</label>
                <input 
                  value={inviteEmail} 
                  onChange={e => setInviteEmail(e.target.value)} 
                  placeholder="jane@myshule.app" 
                  className="flex h-9 w-64 rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors placeholder:text-slate-500 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950 disabled:cursor-not-allowed disabled:opacity-50" 
                />
              </div>
              <Button onClick={handleInvite} disabled={inviteMutation.isPending || !inviteEmail}>
                {inviteMutation.isPending ? "Inviting..." : "Send Invitation"}
              </Button>
            </div>
          </Card>

          <div className="bg-white rounded-lg border border-slate-200 shadow-sm overflow-hidden">
            <table className="w-full text-sm text-left">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 font-medium text-slate-500">Staff Name</th>
                  <th className="px-4 py-3 font-medium text-slate-500">Staff Number</th>
                  <th className="px-4 py-3 font-medium text-slate-500">Department / Role</th>
                  <th className="px-4 py-3 font-medium text-slate-500">Status</th>
                  <th className="px-4 py-3 font-medium text-slate-500 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
