                        <tr key={p.id} className="hover:bg-slate-50/50">
                          <td className="px-4 py-3 font-medium text-slate-900">{p.display_name} <span className="text-slate-500 font-normal ml-1">({p.staff_number || "—"})</span></td>
                          <td className="px-4 py-3 text-right">{p.base_amount}</td>
                          <td className="px-4 py-3 text-right text-green-600">+{p.bonuses}</td>
                          <td className="px-4 py-3 text-right text-red-600">-{p.deductions}</td>
                          <td className="px-4 py-3 text-right font-medium">{p.net_pay}</td>
                          <td className="px-4 py-3">
                            <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${p.status === 'draft' ? 'bg-yellow-100 text-yellow-700' : p.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-700'}`}>
                              {p.status.toUpperCase()}
                            </span>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </Card>
          </div>
        </div>
      )}

      {activeTab === "performance" && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="space-y-6">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <CheckCircle className="w-4 h-4" />
                Performance Reviews
              </h3>
              <div className="space-y-4 mb-6">
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Staff Member</label>
                    <select 
                      value={reviewStaffId} 
                      onChange={e => setReviewStaffId(e.target.value)} 
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    >
                      <option value="">Select Staff...</option>
                      {staffList?.filter(s => s.status === 'active').map(s => (
                        <option key={s.id} value={s.id}>{s.display_name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Date</label>
                    <input 
                      type="date"
                      value={reviewDate} 
                      onChange={e => setReviewDate(e.target.value)} 
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                    />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Score (1-5)</label>
                  <input 
                    type="number"
                    min="1" max="5"
                    value={reviewScore} 
                    onChange={e => setReviewScore(Number(e.target.value))} 
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Comments</label>
                  <textarea 
                    value={reviewComments} 
                    onChange={e => setReviewComments(e.target.value)} 
                    className="flex min-h-[60px] w-full rounded-md border border-slate-200 bg-transparent px-3 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Goals for Next Period (Optional)</label>
                  <textarea 
                    value={reviewGoals} 
                    onChange={e => setReviewGoals(e.target.value)} 
                    className="flex min-h-[60px] w-full rounded-md border border-slate-200 bg-transparent px-3 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                  />
                </div>
                <Button onClick={handleCreateReview} disabled={createReviewMutation.isPending || !reviewStaffId || !reviewComments} className="w-full">
                  Record Review
                </Button>
              </div>

              <div className="space-y-3">
                <h4 className="text-sm font-medium text-slate-900">Recent Reviews</h4>
                {reviewsList?.length === 0 ? (
                  <p className="text-sm text-slate-500">No performance reviews recorded.</p>
                ) : (
                  <div className="space-y-2">
                    {reviewsList?.map(r => (
                      <div key={r.id} className="p-3 bg-slate-50 rounded-md border border-slate-100 text-sm">
                        <div className="flex justify-between font-medium text-slate-900 mb-1">
                          <span>{r.display_name}</span>
                          <span className="flex items-center gap-1">Score: {r.score}/5</span>
                        </div>
                        <div className="text-xs text-slate-500 mb-2">{new Date(r.review_date).toLocaleDateString()}</div>
                        <p className="text-slate-700">{r.comments}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </Card>
          </div>

          <div className="space-y-6">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <FileText className="w-4 h-4 text-red-500" />
                Disciplinary Records
              </h3>
              <div className="space-y-4 mb-6">
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Staff Member</label>
                    <select 
                      value={discStaffId} 
                      onChange={e => setDiscStaffId(e.target.value)} 
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                    >
                      <option value="">Select Staff...</option>
                      {staffList?.map(s => (
                        <option key={s.id} value={s.id}>{s.display_name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-700">Date</label>
                    <input 
                      type="date"
                      value={discDate} 
                      onChange={e => setDiscDate(e.target.value)} 
                      className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                    />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Severity</label>
                  <select 
                    value={discSeverity} 
                    onChange={e => setDiscSeverity(e.target.value as any)} 
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="low">Low</option>
                    <option value="medium">Medium</option>
                    <option value="high">High</option>
                    <option value="critical">Critical</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Description</label>
                  <textarea 
                    value={discDescription} 
                    onChange={e => setDiscDescription(e.target.value)} 
                    className="flex min-h-[60px] w-full rounded-md border border-slate-200 bg-transparent px-3 py-2 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Action Taken (Optional)</label>
                  <input 
                    value={discAction} 
                    onChange={e => setDiscAction(e.target.value)} 
                    placeholder="e.g. Verbal Warning"
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950" 
                  />
                </div>
                <Button variant="danger" onClick={handleCreateDisciplinary} disabled={createDisciplinaryMutation.isPending || !discStaffId || !discDescription} className="w-full">
                  Record Disciplinary Action
                </Button>
              </div>

              <div className="space-y-3">
                <h4 className="text-sm font-medium text-slate-900">Recent Records</h4>
                {disciplinaryList?.length === 0 ? (
                  <p className="text-sm text-slate-500">No disciplinary records found.</p>
                ) : (
                  <div className="space-y-2">
                    {disciplinaryList?.map(d => (
                      <div key={d.id} className="p-3 bg-red-50/50 rounded-md border border-red-100 text-sm">
                        <div className="flex justify-between font-medium text-slate-900 mb-1">
                          <span>{d.display_name}</span>
                          <span className={`text-xs px-2 py-0.5 rounded-full capitalize ${d.severity === 'critical' || d.severity === 'high' ? 'bg-red-100 text-red-700' : 'bg-orange-100 text-orange-700'}`}>
                            {d.severity}
                          </span>
                        </div>
                        <div className="text-xs text-slate-500 mb-2">{new Date(d.incident_date).toLocaleDateString()}</div>
                        <p className="text-slate-700">{d.description}</p>
                        {d.action_taken && <p className="text-xs text-slate-500 mt-2"><strong>Action:</strong> {d.action_taken}</p>}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { BookOpen, Users, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";

export function SubjectsWorkspace() {
  const [activeTab, setActiveTab] = useState<"subjects" | "teachers">("subjects");

  const { data: subjectsList, refetch: refetchSubjects } = useSchoolQuery<any[]>("/api/academics/subjects", { enabled: activeTab === "subjects" || activeTab === "teachers" });
  const { data: assignmentsList, refetch: refetchAssignments } = useSchoolQuery<any[]>("/api/academics/teacher-assignments", { enabled: activeTab === "teachers" });
  
  const { data: staffList } = useSchoolQuery<any[]>("/api/hr/staff", { enabled: activeTab === "teachers" });
  const { data: sectionsList } = useSchoolQuery<any[]>("/api/academics/class-sections", { enabled: activeTab === "teachers" });
  const { data: termsList } = useSchoolQuery<any[]>("/api/academics/academic-terms", { enabled: activeTab === "teachers" });

  const createSubjectMutation = useSchoolMutation("/api/academics/subjects");
  const assignTeacherMutation = useSchoolMutation("/api/academics/teacher-assignments");

  const [newSubCode, setNewSubCode] = useState("");
  const [newSubName, setNewSubName] = useState("");

  const handleCreateSubject = async () => {
    if (!newSubCode || !newSubName) return;
    await createSubjectMutation.mutateAsync({ code: newSubCode, name: newSubName });
    setNewSubCode(""); setNewSubName("");
    refetchSubjects();
  };

  const [assignTermId, setAssignTermId] = useState("");
  const [assignSectionId, setAssignSectionId] = useState("");
  const [assignSubjectId, setAssignSubjectId] = useState("");
  const [assignTeacherId, setAssignTeacherId] = useState("");

  const handleAssignTeacher = async () => {
    if (!assignTermId || !assignSectionId || !assignSubjectId || !assignTeacherId) return;
    await assignTeacherMutation.mutateAsync({
      academic_term_id: assignTermId,
      class_section_id: assignSectionId,
      subject_id: assignSubjectId,
      teacher_user_id: assignTeacherId // Actually user_id but maybe staff_profile_id. Assuming the backend accepts the staff_profile_id or user_id. We'll use staff_profile_id from staffList.
    });
    setAssignSubjectId("");
    setAssignTeacherId("");
    refetchAssignments();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 tracking-tight">Curriculum & Subjects</h2>
          <p className="text-sm text-slate-500 mt-1">Manage subjects and class teacher assignments.</p>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 pb-0">
        <button
          onClick={() => setActiveTab("subjects")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "subjects" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <BookOpen className="w-4 h-4" />
          Subjects Directory
        </button>
        <button
          onClick={() => setActiveTab("teachers")}
          className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 ${
            activeTab === "teachers" ? "border-slate-900 text-slate-900" : "border-transparent text-slate-500 hover:text-slate-700"
          }`}
        >
          <Users className="w-4 h-4" />
          Teacher Assignments
        </button>
      </div>

      {activeTab === "subjects" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Add Subject
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Code</label>
                  <input 
                    type="text" 
                    placeholder="e.g. MAT101"
                    value={newSubCode} onChange={e => setNewSubCode(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Name</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Mathematics"
                    value={newSubName} onChange={e => setNewSubName(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  />
                </div>
                <Button onClick={handleCreateSubject} disabled={createSubjectMutation.isPending || !newSubCode || !newSubName} className="w-full">
                  Create Subject
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Code</th>
                    <th className="px-4 py-3 font-medium">Name</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {subjectsList?.length === 0 ? (
                    <tr><td colSpan={2} className="px-4 py-8 text-center text-slate-500">No subjects defined yet.</td></tr>
                  ) : (
                    subjectsList?.map((sub: any) => (
                      <tr key={sub.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{sub.code}</td>
                        <td className="px-4 py-3">{sub.name}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}

      {activeTab === "teachers" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <Card className="p-4 border border-slate-200">
              <h3 className="font-medium text-slate-900 mb-4 flex items-center gap-2">
                <Plus className="w-4 h-4" />
                Assign Teacher
              </h3>
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Academic Term</label>
                  <select 
                    value={assignTermId} onChange={e => setAssignTermId(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="">Select Term...</option>
                    {termsList?.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Class Section</label>
                  <select 
                    value={assignSectionId} onChange={e => setAssignSectionId(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="">Select Class...</option>
                    {sectionsList?.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Subject</label>
                  <select 
                    value={assignSubjectId} onChange={e => setAssignSubjectId(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="">Select Subject...</option>
                    {subjectsList?.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-medium text-slate-700">Teacher</label>
                  <select 
                    value={assignTeacherId} onChange={e => setAssignTeacherId(e.target.value)}
                    className="flex h-9 w-full rounded-md border border-slate-200 bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-slate-950"
                  >
                    <option value="">Select Staff...</option>
                    {staffList?.map(s => <option key={s.id} value={s.id}>{s.display_name}</option>)}
                  </select>
                </div>
                <Button onClick={handleAssignTeacher} disabled={assignTeacherMutation.isPending || !assignTermId || !assignSectionId || !assignSubjectId || !assignTeacherId} className="w-full">
                  Assign Teacher
                </Button>
              </div>
            </Card>
          </div>
          <div className="lg:col-span-2">
            <Card className="border border-slate-200 overflow-hidden">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 uppercase bg-slate-50/50 border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-3 font-medium">Class</th>
                    <th className="px-4 py-3 font-medium">Subject</th>
                    <th className="px-4 py-3 font-medium">Teacher</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {assignmentsList?.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-8 text-center text-slate-500">No teacher assignments yet.</td></tr>
                  ) : (
                    assignmentsList?.map((asmt: any) => (
                      <tr key={asmt.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-4 py-3 font-medium text-slate-900">{asmt.class_name}</td>
                        <td className="px-4 py-3">{asmt.subject_name}</td>
                        <td className="px-4 py-3 text-slate-500">{asmt.teacher_name}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import { Users } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type ApplicantProfilesData = {
  metrics: Record<string, number>;
  items: any[];
};

export function ApplicantProfilesWorkspace() {
  const { data, isLoading } = useSchoolQuery<ApplicantProfilesData>("/admin-command/admissions/applicant-profiles");
  const items = data?.items || [];

  return (
    <section className="rounded-2xl border border-[#D8E0EC] bg-white p-5 shadow-[0_18px_50px_rgba(7,29,73,0.08)]">
      <div className="mb-4 flex min-w-0 gap-3">
        <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#EEF5FF] text-[#1D4ED8]">
          <Users className="h-5 w-5" aria-hidden="true" />
        </span>
        <div>
          <h2 className="text-xl font-black tracking-[-0.01em] text-[#071D49]">Applicant Profiles</h2>
          <p className="mt-1 text-sm leading-6 text-[#64748B]">View detailed applicant information.</p>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-1 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Profiles</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total ?? 0}</div>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold">Name</th>
              <th className="px-4 py-3 font-bold">Class Applied</th>
              <th className="px-4 py-3 font-bold">Date</th>
              <th className="px-4 py-3 font-bold">Parent</th>
              <th className="px-4 py-3 font-bold">Status</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">Loading...</td></tr>
            ) : items.length === 0 ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No records found. Create the first entry to get started.</td></tr>
            ) : (
              items.map((row: any, i: number) => (
                <tr key={row.id || i} className="border-t border-[#D8E0EC] hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{row.applicant_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.class_applied}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.date}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.parent_name}</td>
                  <td className="px-4 py-3"><span className="inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap">{row.status}</span></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </section>
  );
}

"use client";
import { Calendar } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type AppointmentsData = {
  metrics: Record<string, number>;
  items: any[];
};

export function AppointmentsWorkspace() {
  const { data, isLoading } = useSchoolQuery<AppointmentsData>("/admin-command/admissions/appointments");
