function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

type NavItem = {
  id: string;
  label: string;
  icon: LucideIcon;
  group: string;
};

const BASE_NAV_ITEMS: NavItem[] = [
  { id: "overview", label: "Overview", icon: Home, group: "Command Center" },
  { id: "daily-operations", label: "Daily Operations", icon: Activity, group: "Command Center" },
  { id: "attendance", label: "Attendance & Punctuality", icon: UserRoundCheck, group: "Student Management" },
  { id: "discipline", label: "Discipline & Behaviour", icon: ShieldAlert, group: "Student Management" },
  { id: "welfare", label: "Student Welfare", icon: Stethoscope, group: "Student Management" },
  { id: "staff-duty", label: "Staff Duty", icon: UsersRound, group: "Staff Management" },
  { id: "timetable", label: "Timetable & Relief", icon: CalendarClock, group: "Staff Management" },
  { id: "academics", label: "Academics Monitoring", icon: GraduationCap, group: "Academics" },
  { id: "exams", label: "Exams & Marks", icon: ClipboardCheck, group: "Academics" },
  { id: "classes", label: "Classes & Streams", icon: Layers, group: "Academics" },
  { id: "approvals", label: "Approvals & Escalations", icon: CheckCircle2, group: "Administration" },
  { id: "communication", label: "Communication", icon: MessageSquareText, group: "Administration" },
  { id: "reports", label: "Reports & Downloads", icon: FileBarChart2, group: "Administration" },
  { id: "staff-roles", label: "Staff & Roles", icon: ShieldCheck, group: "Administration" },
  { id: "settings", label: "Settings", icon: Settings, group: "Administration" },
];

export function DeputyPrincipalCommandCenter({ activeSection, routeMode }: { activeSection?: string; routeMode?: "hosted" | "public" }) {
  const [activeWorkspace, setActiveWorkspaceState] = useState(activeSection && activeSection !== "dashboard" ? activeSection : "overview");

  const setActiveWorkspace = (view: string) => {
    setActiveWorkspaceState(view);
    const newPath = buildSchoolSectionHref("deputy-principal", view, routeMode ?? "hosted");
    window.history.replaceState(null, "", newPath);
  };
  const [isTeachingEnabled, setIsTeachingEnabled] = useState(true);

  // Listen to teaching toggle from settings workspace
  useEffect(() => {
    const handleToggle = (e: Event) => {
      const customEvent = e as CustomEvent;
      setIsTeachingEnabled(customEvent.detail);
      if (!customEvent.detail && activeWorkspace === "teaching") {
        setActiveWorkspace("overview");
      }
    };
    window.addEventListener("deputy-teaching-toggle", handleToggle);
    return () => window.removeEventListener("deputy-teaching-toggle", handleToggle);
  }, [activeWorkspace]);

  const navItems = useMemo(() => {
    if (isTeachingEnabled) {
      const teachingItem = { id: "teaching", label: "Teaching Workspace", icon: BookOpen, group: "My Duties" };
      return [
        ...BASE_NAV_ITEMS.slice(0, 8),
        teachingItem,
        ...BASE_NAV_ITEMS.slice(8)
      ];
    }
    return BASE_NAV_ITEMS;
  }, [isTeachingEnabled]);

  const groups = useMemo(() => {
    return navItems.reduce<Record<string, NavItem[]>>((acc, item) => {
      acc[item.group] = [...(acc[item.group] ?? []), item];
      return acc;
    }, {});
  }, [navItems]);

  const renderWorkspace = () => {
    switch (activeWorkspace) {
      case "overview": return <DeputyOverviewWorkspace />;
      case "daily-operations": return <DeputyDailyOperationsWorkspace />;
      case "attendance": return <DeputyAttendanceWorkspace />;
      case "discipline": return <DeputyDisciplineWorkspace />;
      case "welfare": return <DeputyWelfareWorkspace />;
      case "staff-duty": return <DeputyStaffDutyWorkspace />;
      case "timetable": return <DeputyTimetableReliefWorkspace />;
      case "academics": return <DeputyAcademicsMonitoringWorkspace />;
      case "teaching": return <DeputyTeachingWorkspace />;
      case "exams": return <DeputyExamsMarksWorkspace />;
      case "classes": return <DeputyClassesStreamsWorkspace />;
      case "approvals": return <DeputyApprovalsWorkspace />;
      case "communication": return <DeputyCommunicationWorkspace />;
      case "reports": return <DeputyReportsDownloadsWorkspace />;
      case "staff-roles": return <DeputyStaffRolesWorkspace />;
      case "settings": return <DeputySettingsWorkspace />;
      default: return <DeputyOverviewWorkspace />;
    }
  };

  return (
    <div data-route-mode={routeMode} className="min-h-screen bg-[#F3F4F6] pb-24 lg:pb-6">
      <div className="grid gap-5 p-3 md:p-5 xl:grid-cols-[300px_minmax(0,1fr)]">
        {/* Sidebar */}
        <aside className="hidden h-[calc(100vh-40px)] rounded-[var(--radius-xl)] border border-[#C8D5EA]/50 bg-[#071D49] p-4 text-white shadow-[0_24px_70px_rgba(7,29,73,0.22)] xl:sticky xl:top-5 xl:flex xl:flex-col">
          <div className="rounded-[var(--radius-lg)] border border-white/10 bg-white/[0.06] p-4">
            <p className="text-xs font-black uppercase text-cyan-200">Deputy Command</p>
            <h2 className="mt-2 text-2xl font-black">Operations Control</h2>
          </div>
          <nav className="mt-5 flex-1 space-y-5 overflow-auto pr-1 pb-10 custom-scrollbar">
            {Object.entries(groups).map(([group, items]) => (
              <div key={group}>
                <p className="px-3 text-[11px] font-black uppercase tracking-[0.16em] text-white/45">{group}</p>
                <div className="mt-2 grid gap-1">
                  {items.map((item) => {
                    const Icon = item.icon;
                    const active = activeWorkspace === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => setActiveWorkspace(item.id)}
                        className={cn(
                          "flex min-h-10 w-full items-center gap-3 rounded-[var(--radius)] px-3 py-2 text-sm font-bold transition hover:-translate-y-0.5",
                          active
                            ? "border border-cyan-300/35 bg-cyan-300/12 text-cyan-100 shadow-[inset_4px_0_0_#22D3EE]"
                            : "text-white/72 hover:bg-white/10 hover:text-white"
                        )}
                      >
                        <Icon className="h-4 w-4 shrink-0" aria-hidden="true" />
                        <span className="truncate">{item.label}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            ))}
          </nav>
        </aside>

        {/* Main Content */}
        <main className="min-w-0 space-y-5">
          <header className="rounded-[var(--radius-xl)] border border-[#C8D5EA] bg-white p-4 text-[#071D49] shadow-[0_18px_50px_rgba(7,29,73,0.12)] md:p-5">
            <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
              <div className="flex items-center gap-4">
                <div className="grid h-12 w-12 place-items-center rounded-[var(--radius-lg)] bg-[#071D49] text-sm font-black text-white shadow-[0_16px_34px_rgba(7,29,73,0.18)]">MS</div>
                <div>
                  <p className="text-xs font-black uppercase tracking-[0.16em] text-[#5F6F89]">MyShule operations intelligence</p>
                  <p className="mt-1 text-lg font-black md:text-2xl">Deputy Principal Dashboard</p>
                </div>
              </div>
              <div className="grid gap-3 lg:min-w-[640px]">
                <div className="relative">
                  <Search className="pointer-events-none absolute left-4 top-3.5 h-5 w-5 text-[#5F6F89]" aria-hidden="true" />
                  <input
                    placeholder="Search student, teacher, incident, class, parent, or report"
                    className="h-12 w-full rounded-[var(--radius-lg)] border border-[#C8D5EA] bg-[#F8FAFC] pl-12 pr-4 text-sm font-semibold text-[#071D49] outline-none transition focus:border-cyan-400 focus:ring-4 focus:ring-cyan-300/20"
                  />
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <TaskQueue />
                  <ApprovalInbox currentUserId="school" />
                  <NotificationBell />
                </div>
              </div>
            </div>
          </header>

          <div className="rounded-[var(--radius-xl)] bg-[#071D49] p-5 shadow-[0_24px_70px_rgba(7,29,73,0.22)]">
            <h1 className="mb-6 text-3xl font-black text-white">
              {navItems.find((n) => n.id === activeWorkspace)?.label}
            </h1>
            {renderWorkspace()}
          </div>
        </main>
      </div>

      {/* Mobile nav */}
      <div className="fixed inset-x-0 bottom-0 z-40 border-t border-white/10 bg-[#071D49]/94 px-2 py-2 text-white shadow-[0_-18px_50px_rgba(0,0,0,0.28)] backdrop-blur-xl lg:hidden">
        <div className="grid grid-cols-5 gap-1">
          {navItems.slice(0, 5).map((item) => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => setActiveWorkspace(item.id)}
                className={cn(
                  "flex min-h-14 flex-col items-center justify-center gap-1 rounded-[var(--radius)] px-1 text-center text-[10px] font-black active:scale-95",
                  activeWorkspace === item.id ? "text-cyan-400" : "text-white/70"
                )}
              >
                <Icon className="h-4 w-4" aria-hidden="true" />
                <span className="truncate w-full">{item.label.split(' ')[0]}</span>
              </button>
            );
          })}
        </div>
      </div>
      
    </div>
  );
}

"use client";
import { useState } from "react";
import { GraduationCap } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";

export type AcademicIntervention = {
  id: string;
  className: string;
  subject: string;
  teacher: string;
  coverage: string;
  concern: "Behind Schedule" | "Low Average" | "Missed Lessons";
  actionTaken?: string;
};

type AcademicsData = {
  metrics: {
    active_subjects: number;
  };
  interventions: AcademicIntervention[];
};

import { createIntervention } from "./api-client";

export function DeputyAcademicsMonitoringWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading } = useSchoolQuery<AcademicsData>('/admin-command/deputy/academics');
  const [showModal, setShowModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({ className: '', subject: '', teacher: '', concern: 'Low Average' });

  const messageMutation = useSchoolMutation<{ id: string }, { id: string }>(
    ({ id }) => `/admin-command/deputy/academics/${id}/message-hod`,
    'POST',
    {
      onSuccess: () => queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/academics'] })
    }
  );

  const interventions = data?.interventions || [];

  const handleMessageHOD = async (id: string, subject: string, teacher: string) => {
    try {
      await messageMutation.mutateAsync({ id });
      toast.success(`Message sent to ${subject} HOD regarding ${teacher}.`);
    } catch (e) {
      toast.error("Failed to send message.");
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await createIntervention(formData);
      toast.success("Intervention created successfully");
      setShowModal(false);
      setFormData({ className: '', subject: '', teacher: '', concern: 'Low Average' });
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/academics'] });
    } catch (error) {
      toast.error("Failed to create intervention");
    } finally {
      setIsSubmitting(false);
    }
  };

  const getConcernTone = (st: string): Tone => {
    return "warning";
  };

  return (
    <>
      <Panel title="Academics Monitoring" description="Syllabus progress, weak classes, and academic interventions." icon={GraduationCap} actions={
        <button onClick={() => setShowModal(true)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Create Intervention</button>
      }>
        <div className="grid gap-4 md:grid-cols-2 mb-6">
          <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
            <div className="text-sm font-semibold text-[#64748B]">Active Subjects</div>
            <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.active_subjects || 0}</div>
          </div>
        </div>
        <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
          <table className="w-full text-sm text-left whitespace-nowrap">
            <thead className="bg-[#F8FAFC] text-[#071D49]">
              <tr>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Subject</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Teacher</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Coverage %</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Concern</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
                <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#D8E0EC]">
              {interventions.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-[#64748B]">No current academic interventions.</td>
                </tr>
              ) : (
                interventions.map((inv) => (
                  <tr key={inv.id} className="hover:bg-[#F8FAFC]">
                    <td className="px-4 py-3 font-semibold text-[#071D49]">{inv.className}</td>
                    <td className="px-4 py-3 text-[#64748B]">{inv.subject}</td>
                    <td className="px-4 py-3 text-[#64748B]">{inv.teacher}</td>
                    <td className="px-4 py-3 font-bold">{inv.coverage}</td>
                    <td className="px-4 py-3"><StatusChip label={inv.concern} tone={getConcernTone(inv.concern)} /></td>
                    <td className="px-4 py-3"><StatusChip label={inv.actionTaken || "Pending Action"} tone={inv.actionTaken ? "info" : "danger"} /></td>
                    <td className="px-4 py-3 text-right">
                      {!inv.actionTaken && (
                        <button onClick={() => handleMessageHOD(inv.id, inv.subject, inv.teacher)} className="text-blue-600 hover:underline font-semibold text-xs mr-3">Message HOD</button>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Panel>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <h2 className="mb-4 text-xl font-bold text-[#071D49]">Create Academic Intervention</h2>
            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Class</label>
                <input required type="text" value={formData.className} onChange={e => setFormData({ ...formData, className: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]" placeholder="e.g. Form 3 East" />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Subject</label>
                <input required type="text" value={formData.subject} onChange={e => setFormData({ ...formData, subject: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]" placeholder="e.g. Mathematics" />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Teacher</label>
                <input required type="text" value={formData.teacher} onChange={e => setFormData({ ...formData, teacher: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]" placeholder="e.g. Mr. Kamau" />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Concern</label>
                <select value={formData.concern} onChange={e => setFormData({ ...formData, concern: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]">
                  <option value="Low Average">Low Average</option>
                  <option value="Behind Schedule">Behind Schedule</option>
                  <option value="Missed Lessons">Missed Lessons</option>
                </select>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t border-[#D8E0EC]">
                <button type="button" onClick={() => setShowModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC]">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-bold text-white hover:bg-blue-900 disabled:opacity-50">
                  {isSubmitting ? "Saving..." : "Create"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
}

