              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Target Class</label>
                <input required type="text" value={streamData.targetClass} onChange={e => setStreamData({ ...streamData, targetClass: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]" placeholder="e.g. Form 1" />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-[#64748B]">Stream Name</label>
                <input required type="text" value={streamData.streamName} onChange={e => setStreamData({ ...streamData, streamName: e.target.value })} className="w-full rounded-lg border border-[#D8E0EC] px-3 py-2 outline-none focus:border-[#071D49]" placeholder="e.g. Form 1 North" />
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t border-[#D8E0EC]">
                <button type="button" onClick={() => setShowManageModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC]">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-bold text-white hover:bg-blue-900 disabled:opacity-50">
                  {isSubmitting ? "Saving..." : "Save Changes"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
}

"use client";
import { useState } from "react";
import { MessageSquareText } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { Modal } from "@/components/ui/modal";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { toast } from "sonner";
import { requestDashboardApi } from "@/lib/dashboard/api-client";

export type CommMessage = {
  id: string;
  created_at: string;
  recipient_phone: string;
  status: "Sent" | "Failed";
  content?: string;
};

export function DeputyCommunicationWorkspace() {
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ recipient: "All Staff", message: "" });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { data: smsData, isLoading, refetch } = useSchoolQuery<{ data: CommMessage[] }>('/api/communication/sms');
  const messages = smsData?.data || [];

  const [viewingMessage, setViewingMessage] = useState<CommMessage | null>(null);

  const handleSend = async () => {
    try {
      setIsSubmitting(true);
      await requestDashboardApi('/api/communication/sms', {
        method: 'POST',
        body: {
          recipientPhone: formData.recipient,
          message: formData.message
        }
      });
      toast.success('Message queued for sending.');
      setShowModal(false);
      setFormData({ recipient: "All Staff", message: "" });
      refetch();
    } catch (e) {
      toast.error('Failed to send message.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Panel title="Communication" description="Send staff notices, parent messages, and announcements." icon={MessageSquareText} actions={
      <button onClick={() => setShowModal(true)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Compose Message</button>
    }>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Date</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Recipient</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Type</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {messages.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No messages sent yet.</td>
              </tr>
            ) : (
              messages.map((msg) => (
                <tr key={msg.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{new Date(msg.created_at).toLocaleString()}</td>
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{msg.recipient_phone}</td>
                  <td className="px-4 py-3 text-[#64748B]">Notice</td>
                  <td className="px-4 py-3"><StatusChip label={msg.status} tone={msg.status === "Sent" ? "success" : "neutral"} /></td>
                  <td className="px-4 py-3 text-right">
                    <button onClick={() => setViewingMessage(msg)} className="text-blue-600 hover:underline font-semibold text-xs">View</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Compose Message" footer={
        <>
          <button onClick={() => setShowModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-slate-100">Cancel</button>
          <button disabled={!formData.message || isSubmitting} onClick={handleSend} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 disabled:opacity-50">
            {isSubmitting ? "Sending..." : "Send Message"}
          </button>
        </>
      }>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-bold text-[#334155]">Recipient Group</label>
            <select value={formData.recipient} onChange={(e) => setFormData({...formData, recipient: e.target.value})} className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none">
              <option>All Staff</option>
              <option>Parents (All)</option>
              <option>Form 4 Parents</option>
            </select>
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Message Body</label>
            <textarea value={formData.message} onChange={(e) => setFormData({...formData, message: e.target.value})} className="mt-1 h-24 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none"></textarea>
          </div>
        </div>
      </Modal>

      {viewingMessage && (
        <Modal open={true} onClose={() => setViewingMessage(null)} title="Message Details" footer={
          <button onClick={() => setViewingMessage(null)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Close</button>
        }>
          <div className="space-y-4">
            <div>
              <span className="text-xs font-bold text-[#64748B] uppercase">Sent To</span>
              <div className="font-semibold text-[#071D49]">{viewingMessage.recipient_phone}</div>
            </div>
            <div>
              <span className="text-xs font-bold text-[#64748B] uppercase">Date & Time</span>
              <div className="text-[#334155]">{new Date(viewingMessage.created_at).toLocaleString()}</div>
            </div>
            <div>
              <span className="text-xs font-bold text-[#64748B] uppercase">Status</span>
              <div className="mt-1"><StatusChip label={viewingMessage.status} tone={viewingMessage.status === "Sent" ? "success" : "neutral"} /></div>
            </div>
            <div className="rounded-lg bg-slate-50 p-4 border border-slate-200">
              <p className="text-sm text-slate-800 whitespace-pre-wrap">{viewingMessage.content || "No content provided by gateway."}</p>
            </div>
          </div>
        </Modal>
      )}
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { Activity } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, Tone } from "./shared";
import { Modal } from "@/components/ui/modal";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { createDailyOperationNote } from "./api-client";

export type OperationNote = {
  id: string;
  time: string;
  area: string;
  issue: string;
  status: "Active" | "Resolved";
};

type DailyOperationsData = {
  metrics: {
    morning_parade_status: string;
    staff_on_duty_present: number;
    staff_on_duty_total: number;
    gate_security_status: string;
    classes_not_started: number;
  };
  notes: OperationNote[];
};

export function DeputyDailyOperationsWorkspace() {
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ area: "", issue: "" });
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { data, isLoading, refetch } = useSchoolQuery<DailyOperationsData>('/admin-command/deputy/daily-operations');

  const notes = data?.notes || [];
  const metrics = data?.metrics || {
    morning_parade_status: "Pending",
    staff_on_duty_present: 0,
    staff_on_duty_total: 0,
    gate_security_status: "No Report",
    classes_not_started: 0,
  };

  const handleCreate = async () => {
    setIsSubmitting(true);
    try {
      await createDailyOperationNote({
        area: formData.area,
        issue: formData.issue
      });
      toast.success("Operation Note created successfully.");
      setShowModal(false);
      setFormData({ area: "", issue: "" });
      refetch();
    } catch (error) {
      toast.error("Failed to create Operation Note.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStatusTone = (st: string): Tone => {
    if (st === "Resolved") return "success";
    return "warning";
  };

  return (
    <Panel title="Daily Operations" description="Manage the school day from morning to evening." icon={Activity} actions={
      <button onClick={() => setShowModal(true)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900">Create Operation Note</button>
    }>
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Morning Parade</div>
          <div className="mt-1 text-lg font-black text-emerald-600">{isLoading ? "..." : metrics.morning_parade_status}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Staff on Duty</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : `${metrics.staff_on_duty_present} / ${metrics.staff_on_duty_total} Present`}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Gate Security</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : metrics.gate_security_status}</div>
        </div>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
          <div className="text-sm font-semibold text-rose-700">Classes Not Started</div>
          <div className="mt-1 text-lg font-black text-rose-700">{isLoading ? "..." : metrics.classes_not_started}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Time</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Area</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Issue</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {notes.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No operational notes logged today.</td>
              </tr>
            ) : (
              notes.map((note) => (
                <tr key={note.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{note.time}</td>
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{note.area}</td>
                  <td className="px-4 py-3 text-[#64748B]">{note.issue}</td>
                  <td className="px-4 py-3"><StatusChip label={note.status} tone={getStatusTone(note.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    <button className="text-blue-600 hover:underline font-semibold text-xs">View Note</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Log Daily Operation Note" footer={
        <>
          <button onClick={() => setShowModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-slate-100">Cancel</button>
          <button disabled={!formData.area || !formData.issue || isSubmitting} onClick={handleCreate} className="rounded-lg bg-rose-600 px-4 py-2 text-sm font-black text-white hover:bg-rose-700 disabled:opacity-50">
            {isSubmitting ? "Saving..." : "Save Note"}
          </button>
        </>
      }>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-bold text-[#334155]">Area</label>
            <input value={formData.area} onChange={(e) => setFormData({...formData, area: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Issue Details</label>
            <input value={formData.issue} onChange={(e) => setFormData({...formData, issue: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
        </div>
      </Modal>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { ShieldAlert, Search, PlusCircle } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { Modal } from "@/components/ui/modal";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { createDisciplineIncident, escalateDisciplineIncident } from "./api-client";

export type DisciplineIncident = {
  id: string;
  caseNo: string;
  studentName: string;
  incidentType: string;
  severity: "High" | "Critical" | "Low" | "Medium";
  status: "New" | "In Review" | "Escalated" | "Resolved";
};

type DisciplineIncidentDraft = {
  studentName: string;
  incidentType: string;
  severity: DisciplineIncident["severity"];
};

export function DeputyDisciplineWorkspace() {
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState<DisciplineIncidentDraft>({ studentName: "", incidentType: "", severity: "High" });
  const [isSubmittingCreate, setIsSubmittingCreate] = useState(false);

  const queryClient = useQueryClient();
  const { data: incidents = [], isLoading } = useSchoolQuery<DisciplineIncident[]>('/admin-command/deputy/discipline');
  
  const handleCreate = async () => {
    setIsSubmittingCreate(true);
    try {
      await createDisciplineIncident({
        studentName: formData.studentName,
        incidentType: formData.incidentType,
        severity: formData.severity,
      });
      setShowModal(false);
      setFormData({ studentName: "", incidentType: "", severity: "High" });
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/discipline'] });
      toast.success("Incident logged successfully.");
    } catch (error: any) {
      toast.error(error.message || "Failed to log incident.");
    } finally {
      setIsSubmittingCreate(false);
    }
  };

  const handleEscalate = async (id: string, caseNo: string) => {
    try {
      await escalateDisciplineIncident(id);
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/discipline'] });
      toast.success(`Case ${caseNo} escalated to Principal.`);
    } catch (e: any) {
      toast.error(e.message || "Failed to escalate case.");
    }
  };

  const getTone = (sev: string): Tone => {
    if (sev === "Critical") return "danger";
    if (sev === "High") return "warning";
    return "info";
  };

  const getStatusTone = (st: string): Tone => {
    if (st === "New") return "danger";
    if (st === "In Review") return "warning";
    if (st === "Resolved") return "success";
    return "neutral";
  };

  return (
    <Panel title="Discipline & Behaviour" description="Student behaviour incidents, investigations, and escalations." icon={ShieldAlert} actions={
      <button onClick={() => setShowModal(true)} className="flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">
        <PlusCircle className="w-4 h-4" /> Log Incident
      </button>
    }>
      <div className="flex flex-col sm:flex-row gap-3 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-[#64748B]" />
          <input type="text" placeholder="Search case no, student..." className="w-full rounded-xl border border-[#D8E0EC] py-2 pl-9 pr-3 text-sm focus:border-[#071D49] focus:outline-none" />
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Case No.</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Student</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Incident</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Severity</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {incidents.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-[#64748B]">No recent discipline cases found.</td>
              </tr>
            ) : (
              incidents.map((inc) => (
                <tr key={inc.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{inc.caseNo}</td>
                  <td className="px-4 py-3 text-[#64748B]">{inc.studentName}</td>
                  <td className="px-4 py-3 text-[#64748B]">{inc.incidentType}</td>
                  <td className="px-4 py-3"><StatusChip label={inc.severity} tone={getTone(inc.severity)} /></td>
                  <td className="px-4 py-3"><StatusChip label={inc.status} tone={getStatusTone(inc.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    {inc.status !== "Escalated" && (
                      <button onClick={() => handleEscalate(inc.id, inc.caseNo)} className="text-blue-600 hover:underline font-semibold text-xs mr-3">Escalate</button>
                    )}
                    <button className="text-blue-600 hover:underline font-semibold text-xs">Open Case</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Log New Incident" footer={
        <>
          <button disabled={isSubmittingCreate} onClick={() => setShowModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-slate-100">Cancel</button>
          <button disabled={isSubmittingCreate || !formData.studentName} onClick={handleCreate} className="rounded-lg bg-rose-600 px-4 py-2 text-sm font-black text-white hover:bg-rose-700 disabled:opacity-50">
            {isSubmittingCreate ? "Saving..." : "Save Incident"}
          </button>
        </>
      }>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-bold text-[#334155]">Student Name</label>
            <input value={formData.studentName} onChange={(e) => setFormData({...formData, studentName: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Incident Details</label>
            <input value={formData.incidentType} onChange={(e) => setFormData({...formData, incidentType: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Severity</label>
            <select value={formData.severity} onChange={(e) => setFormData({...formData, severity: e.target.value as DisciplineIncident["severity"]})} className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none">
              <option>Low</option>
              <option>Medium</option>
              <option>High</option>
              <option>Critical</option>
            </select>
          </div>
        </div>
      </Modal>
    </Panel>
  );
}

"use client";
import { ClipboardCheck } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useState } from "react";
import { toast } from "sonner";
import { flagExamDelay } from "./api-client";

export type ExamMarkProgress = {
  id: string;
  exam: string;
  className: string;
  subject: string;
  teacher: string;
  progress: "Missing Marks" | "In Progress" | "Completed";
};

type ExamsData = {
  metrics: {
    draft_marks: number;
  };
  examsList: ExamMarkProgress[];
};

export function DeputyExamsMarksWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<ExamsData>('/admin-command/deputy/exams');
  const [submittingId, setSubmittingId] = useState<string | null>(null);

  const exams = data?.examsList || [];

  const handleFlagDelay = async (id: string, teacher: string) => {
    try {
      setSubmittingId(id);
      await flagExamDelay(id);
      toast.success(`Reminder sent to ${teacher} regarding delayed marks.`);
      refetch();
    } catch (e) {
      toast.error("Failed to flag delay.");
    } finally {
      setSubmittingId(null);
    }
  };

  const getTone = (st: string): Tone => {
    if (st === "Missing Marks") return "danger";
    if (st === "In Progress") return "warning";
    return "success";
  };

  return (
    <Panel title="Exams & Marks" description="Monitor exams at senior level and enter marks for assigned classes." icon={ClipboardCheck} actions={
      <button onClick={() => toast.info("Opening gradebook module...")} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Enter My Marks</button>
    }>
      <div className="grid gap-4 md:grid-cols-2 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Draft Marks Pending</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.draft_marks || 0}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
