          </div>
        </div>
      )}
    </>
  );
}

"use client";
import { BookOpen } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useState } from "react";
import { toast } from "sonner";
import { markTeachingAttendance, logTeachingLesson } from "./api-client";

export type TeachingLesson = {
  id: string;
  className: string;
  subject: string;
  lessonTime: string;
  attendanceStatus: "Pending" | "Marked";
  logStatus: "Pending" | "Logged";
};

type TeachingData = {
  metrics: {
    total_lessons: number;
  };
  lessons: TeachingLesson[];
};

export function DeputyTeachingWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<TeachingData>('/admin-command/deputy/teaching');
  const [submittingId, setSubmittingId] = useState<string | null>(null);

  const lessons = data?.lessons || [];

  const handleAction = async (id: string, type: "Attendance" | "Log") => {
    try {
      setSubmittingId(id);
      if (type === "Attendance") {
        await markTeachingAttendance(id);
        toast.success("Attendance marked successfully.");
      } else {
        await logTeachingLesson(id);
        toast.success("Lesson logged successfully.");
      }
      refetch();
    } catch (e) {
      toast.error(`Failed to ${type === "Attendance" ? "mark attendance" : "log lesson"}.`);
    } finally {
      setSubmittingId(null);
    }
  };

  const getTone = (st: string): Tone => st === "Pending" ? "warning" : "success";

  return (
    <Panel title="Teaching Workspace" description="Manage your assigned classes, attendance, and lesson logs." icon={BookOpen}>
      <div className="grid gap-4 md:grid-cols-2 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Lessons</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_lessons || 0}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Subject</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Lesson Time</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Attendance</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Lesson Log</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {lessons.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-[#64748B]">No assigned lessons.</td>
              </tr>
            ) : (
              lessons.map((ls) => (
                <tr key={ls.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{ls.className}</td>
                  <td className="px-4 py-3 text-[#64748B]">{ls.subject}</td>
                  <td className="px-4 py-3 text-[#64748B]">{ls.lessonTime}</td>
                  <td className="px-4 py-3"><StatusChip label={ls.attendanceStatus} tone={getTone(ls.attendanceStatus)} /></td>
                  <td className="px-4 py-3"><StatusChip label={ls.logStatus} tone={getTone(ls.logStatus)} /></td>
                  <td className="px-4 py-3 text-right">
                    {ls.attendanceStatus === "Pending" && (
                      <button 
                        onClick={() => handleAction(ls.id, "Attendance")} 
                        disabled={submittingId === ls.id}
                        className="text-blue-600 hover:underline font-semibold text-xs mr-3 disabled:opacity-50"
                      >
                        {submittingId === ls.id ? "Marking..." : "Mark"}
                      </button>
                    )}
                    {ls.logStatus === "Pending" && (
                      <button 
                        onClick={() => handleAction(ls.id, "Log")} 
                        disabled={submittingId === ls.id}
                        className="text-blue-600 hover:underline font-semibold text-xs disabled:opacity-50"
                      >
                        {submittingId === ls.id ? "Logging..." : "Log"}
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { CalendarClock } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { assignReliefTeacher, autoAssignRelief } from "./api-client";

export type ReliefLesson = {
  id: string;
  lessonTime: string;
  className: string;
  subject: string;
  absentTeacher: string;
  reliefStatus: "Needed" | "Assigned" | "Covered";
  assignedTeacher?: string;
};

type TimetableData = {
  metrics: {
    total_periods: number;
  };
  lessons: ReliefLesson[];
};

export function DeputyTimetableReliefWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading, refetch } = useSchoolQuery<TimetableData>('/admin-command/deputy/timetable');
  const [isAutoAssigning, setIsAutoAssigning] = useState(false);

  const assignMutation = useSchoolMutation<
    { id: string; teacherName: string },
    { id: string; teacherName: string }
  >(
    ({ id }) => `/admin-command/deputy/timetable/${id}/assign`,
    'POST',
    {
      onSuccess: () => queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/timetable'] })
    }
  );

  const lessons = data?.lessons || [];

  const handleAssign = async (id: string, className: string, time: string) => {
    const teacher = prompt("Enter the name of the relief teacher to assign:");
    if (!teacher) return;

    try {
      await assignReliefTeacher(id, teacher);
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/timetable'] });
      toast.success(`${teacher} has been assigned to cover ${className} at ${time}.`);
    } catch (e: any) {
      toast.error(e.message || "Failed to assign relief teacher.");
    }
  };

  const handleAutoAssign = async () => {
    try {
      setIsAutoAssigning(true);
      await autoAssignRelief();
      toast.success("Auto-assignment complete. Free teachers have been assigned to needed lessons.");
      refetch();
    } catch (e: any) {
      toast.error("Failed to run auto-assignment algorithm.");
    } finally {
      setIsAutoAssigning(false);
    }
  };

  const getStatusTone = (st: string): Tone => {
    if (st === "Needed") return "danger";
    if (st === "Assigned") return "warning";
    return "success";
  };

  return (
    <Panel title="Timetable & Relief Lessons" description="Lesson disruptions, absences, and relief coverage." icon={CalendarClock} actions={
      <button 
        onClick={handleAutoAssign} 
        disabled={isAutoAssigning}
        className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50"
      >
        {isAutoAssigning ? "Assigning..." : "Auto-Assign Relief"}
      </button>
    }>
      <div className="grid gap-4 md:grid-cols-2 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Periods Today</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_periods || 0}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Lesson Time</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Subject</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Absent Teacher</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Relief</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {lessons.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-8 text-center text-[#64748B]">No relief lessons found.</td>
              </tr>
            ) : (
              lessons.map((lesson) => (
                <tr key={lesson.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{lesson.lessonTime}</td>
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{lesson.className}</td>
                  <td className="px-4 py-3 text-[#64748B]">{lesson.subject}</td>
                  <td className="px-4 py-3 text-[#64748B]">{lesson.absentTeacher}</td>
                  <td className="px-4 py-3">
                    <StatusChip label={lesson.reliefStatus === "Assigned" ? `Assigned to ${lesson.assignedTeacher}` : lesson.reliefStatus} tone={getStatusTone(lesson.reliefStatus)} />
                  </td>
                  <td className="px-4 py-3 text-right">
                    {lesson.reliefStatus === "Needed" && (
                      <button onClick={() => handleAssign(lesson.id, lesson.className, lesson.lessonTime)} className="text-blue-600 hover:underline font-semibold text-xs">Assign</button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { Stethoscope } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { Modal } from "@/components/ui/modal";
import { useSchoolQuery, useSchoolMutation } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { createWelfareCase, openWelfareCase } from "./api-client";

export type WelfareCase = {
  id: string;
  studentName: string;
  concern: string;
  assignedTo: string;
  status: "Referred" | "In Progress" | "Resolved";
};

type WelfareData = {
  metrics: {
    clinic_visits_today: number;
  };
  cases: WelfareCase[];
};

export function DeputyWelfareWorkspace() {
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ studentName: "", concern: "", assignedTo: "School Counsellor" });

  const queryClient = useQueryClient();
  const { data, isLoading } = useSchoolQuery<WelfareData>('/admin-command/deputy/welfare');

  const createMutation = useSchoolMutation('/admin-command/deputy/welfare', 'POST', {
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/welfare'] })
  });

  const cases = data?.cases || [];

  const handleCreate = async () => {
    try {
      await createWelfareCase({
        studentName: formData.studentName,
        concern: formData.concern,
        assignedTo: formData.assignedTo,
      });
      setShowModal(false);
      setFormData({ studentName: "", concern: "", assignedTo: "School Counsellor" });
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/welfare'] });
      toast.success("Welfare case created and referred successfully.");
    } catch (e: any) {
      toast.error(e.message || "Failed to create welfare case");
    }
  };

  const handleOpenCase = async (id: string, studentName: string) => {
    try {
      await openWelfareCase(id);
      queryClient.invalidateQueries({ queryKey: ["school", "session", '/admin-command/deputy/welfare'] });
      toast.success(`Case for ${studentName} opened. Status updated to In Progress.`);
    } catch (e: any) {
      toast.error(e.message || "Failed to open case.");
    }
  };

  const getStatusTone = (st: string): Tone => {
    if (st === "Referred") return "info";
    if (st === "In Progress") return "warning";
    return "success";
  };

  return (
    <Panel title="Student Welfare" description="Non-punitive student support, counselling, and general welfare." icon={Stethoscope} actions={
      <button onClick={() => setShowModal(true)} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">Create Welfare Case</button>
    }>
      <div className="grid gap-4 md:grid-cols-2 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Clinic Visits Today</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.clinic_visits_today || 0}</div>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Student</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Concern</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Assigned To</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {cases.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No recent welfare cases found.</td>
              </tr>
            ) : (
              cases.map((wc) => (
                <tr key={wc.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{wc.studentName}</td>
                  <td className="px-4 py-3 text-[#64748B]">{wc.concern}</td>
                  <td className="px-4 py-3 text-[#64748B]">{wc.assignedTo}</td>
                  <td className="px-4 py-3"><StatusChip label={wc.status} tone={getStatusTone(wc.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    {wc.status === "Referred" && (
                      <button onClick={() => handleOpenCase(wc.id, wc.studentName)} className="text-blue-600 hover:underline font-semibold text-xs">Open Case</button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal open={showModal} onClose={() => setShowModal(false)} title="Log New Welfare Case" footer={
        <>
          <button onClick={() => setShowModal(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-slate-100">Cancel</button>
          <button disabled={!formData.studentName || createMutation.isPending} onClick={handleCreate} className="rounded-lg bg-rose-600 px-4 py-2 text-sm font-black text-white hover:bg-rose-700 disabled:opacity-50">
            {createMutation.isPending ? "Saving..." : "Save Case"}
          </button>
        </>
      }>
        <div className="space-y-4">
          <div>
            <label className="text-sm font-bold text-[#334155]">Student Name</label>
            <input value={formData.studentName} onChange={(e) => setFormData({...formData, studentName: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Welfare Concern</label>
            <input value={formData.concern} onChange={(e) => setFormData({...formData, concern: e.target.value})} type="text" className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="text-sm font-bold text-[#334155]">Assign To</label>
            <select value={formData.assignedTo} onChange={(e) => setFormData({...formData, assignedTo: e.target.value})} className="mt-1 w-full rounded-xl border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none">
              <option>School Counsellor</option>
              <option>Class Teacher</option>
              <option>Nurse</option>
            </select>
          </div>
        </div>
      </Modal>
    </Panel>
  );
}

