"use client";
import { useState } from "react";
import { ClipboardList, PlusCircle, Search } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { dispenseMedicine } from "./api-client";

type DispenseRecord = {
  id: string;
  student_name: string;
  class_name: string;
  medicine_name: string;
  dosage: string;
  quantity_given: number;
  dispensed_by: string;
  dispensed_at: string;
};

type DispensingData = {
  metrics: { dispensed_today: number; total_this_term: number; unique_students: number };
  records: DispenseRecord[];
};

export function DispensingLogWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading } = useSchoolQuery<DispensingData>('/admin-command/nurse/dispensing-log');
  const [search, setSearch] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [form, setForm] = useState({ student_name: "", class_name: "", medicine_name: "", dosage: "", quantity_given: "" });

  const records = (data?.records || []).filter(r =>
    r.student_name.toLowerCase().includes(search.toLowerCase()) ||
    r.medicine_name.toLowerCase().includes(search.toLowerCase())
  );

  const handleDispense = async () => {
    if (!form.student_name || !form.medicine_name || !form.quantity_given) {
      toast.error("Student, medicine, and quantity are required.");
      return;
    }
    setIsSubmitting(true);
    try {
      await dispenseMedicine({ ...form, quantity_given: Number(form.quantity_given) });
      queryClient.invalidateQueries({ queryKey: ["school", "session", "/admin-command/nurse/dispensing-log"] });
      toast.success("Medicine dispensed and logged.");
      setShowForm(false);
      setForm({ student_name: "", class_name: "", medicine_name: "", dosage: "", quantity_given: "" });
    } catch (e: any) { toast.error(e.message || "Failed to dispense medicine."); }
    finally { setIsSubmitting(false); }
  };

  return (
    <Panel title="Dispensing Log" description="Track all medicine dispensed to students." icon={ClipboardList} actions={
      <button onClick={() => setShowForm(true)} className="flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">
        <PlusCircle className="w-4 h-4" /> Dispense Medicine
      </button>
    }>
      <div className="grid gap-4 md:grid-cols-3 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Dispensed Today</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.dispensed_today ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total This Term</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_this_term ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Unique Students</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.unique_students ?? 0}</div>
        </div>
      </div>

      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 h-4 w-4 text-[#64748B]" />
        <input type="text" placeholder="Search by student or medicine..." value={search} onChange={e => setSearch(e.target.value)} className="w-full rounded-xl border border-[#D8E0EC] py-2 pl-9 pr-3 text-sm focus:border-[#071D49] focus:outline-none" />
      </div>

      {showForm && (
        <div className="mb-4 rounded-xl border border-blue-200 bg-blue-50 p-4">
          <h3 className="text-sm font-bold text-[#071D49] mb-3">Dispense Medicine</h3>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="text-xs font-bold text-[#334155]">Student Name *</label>
              <input value={form.student_name} onChange={e => setForm({...form, student_name: e.target.value})} className="mt-1 w-full rounded-lg border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
            </div>
            <div>
              <label className="text-xs font-bold text-[#334155]">Class</label>
              <input value={form.class_name} onChange={e => setForm({...form, class_name: e.target.value})} className="mt-1 w-full rounded-lg border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
            </div>
            <div>
              <label className="text-xs font-bold text-[#334155]">Medicine *</label>
              <input value={form.medicine_name} onChange={e => setForm({...form, medicine_name: e.target.value})} className="mt-1 w-full rounded-lg border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
            </div>
            <div>
              <label className="text-xs font-bold text-[#334155]">Dosage</label>
              <input value={form.dosage} onChange={e => setForm({...form, dosage: e.target.value})} placeholder="e.g. 500mg x 2" className="mt-1 w-full rounded-lg border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
            </div>
            <div>
              <label className="text-xs font-bold text-[#334155]">Quantity *</label>
              <input type="number" value={form.quantity_given} onChange={e => setForm({...form, quantity_given: e.target.value})} className="mt-1 w-full rounded-lg border border-[#D8E0EC] p-2 text-sm focus:border-blue-500 focus:outline-none" />
            </div>
          </div>
          <div className="mt-3 flex gap-2 justify-end">
            <button onClick={() => setShowForm(false)} className="rounded-lg px-4 py-2 text-sm font-bold text-[#64748B] hover:bg-slate-100">Cancel</button>
            <button disabled={isSubmitting} onClick={handleDispense} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 disabled:opacity-50">
              {isSubmitting ? "Dispensing..." : "Dispense & Log"}
            </button>
          </div>
        </div>
      )}

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Student</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Medicine</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Dosage</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Qty</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Dispensed By</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Date/Time</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={7} className="px-4 py-8 text-center text-[#64748B]">Loading dispensing log...</td></tr>
            ) : records.length === 0 ? (
              <tr><td colSpan={7} className="px-4 py-8 text-center text-[#64748B]">No dispensing records yet. Use &quot;Dispense Medicine&quot; to log medicine given to students.</td></tr>
            ) : (
              records.map(r => (
                <tr key={r.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{r.student_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.class_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.medicine_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.dosage || "—"}</td>
                  <td className="px-4 py-3 font-bold text-[#071D49]">{r.quantity_given}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.dispensed_by}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.dispensed_at}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { FileBarChart, Download, RefreshCw } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { generateHealthReport } from "./api-client";

type ReportRecord = {
  id: string;
  title: string;
  report_type: string;
  period: string;
  generated_at: string;
  status: string;
  total_visits: number;
  total_dispensed: number;
};

type ReportsData = {
  metrics: { total_reports: number; generated_this_term: number };
  reports: ReportRecord[];
};

export function HealthReportsWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading } = useSchoolQuery<ReportsData>('/admin-command/nurse/health-reports');
  const [isGenerating, setIsGenerating] = useState(false);
  const [reportType, setReportType] = useState("weekly");

  const reports = data?.reports || [];

  const getStatusTone = (st: string): Tone => {
    if (st === "Ready") return "success";
    if (st === "Generating") return "info";
    if (st === "Failed") return "danger";
    return "neutral";
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      await generateHealthReport({ report_type: reportType });
      queryClient.invalidateQueries({ queryKey: ["school", "session", "/admin-command/nurse/health-reports"] });
      toast.success(`${reportType.charAt(0).toUpperCase() + reportType.slice(1)} health report generated.`);
    } catch (e: any) { toast.error(e.message || "Failed to generate report."); }
    finally { setIsGenerating(false); }
  };

  return (
    <Panel title="Health Reports" description="Generate and download health summaries for the school." icon={FileBarChart} actions={
      <div className="flex items-center gap-2">
        <select value={reportType} onChange={e => setReportType(e.target.value)} className="rounded-lg border border-[#D8E0EC] px-3 py-2 text-sm focus:border-[#071D49] focus:outline-none">
          <option value="weekly">Weekly</option>
          <option value="monthly">Monthly</option>
          <option value="term">Term</option>
          <option value="annual">Annual</option>
        </select>
        <button disabled={isGenerating} onClick={handleGenerate} className="flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50">
          <RefreshCw className={`w-4 h-4 ${isGenerating ? "animate-spin" : ""}`} />
          {isGenerating ? "Generating..." : "Generate Report"}
        </button>
      </div>
    }>
      <div className="grid gap-4 md:grid-cols-2 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Reports</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_reports ?? 0}</div>
        </div>
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Generated This Term</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.generated_this_term ?? 0}</div>
        </div>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Report</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Type</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Period</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Visits</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Dispensed</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Generated</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">Loading reports...</td></tr>
            ) : reports.length === 0 ? (
              <tr><td colSpan={8} className="px-4 py-8 text-center text-[#64748B]">No reports generated yet. Select a report type and click &quot;Generate Report&quot; to create a health summary.</td></tr>
            ) : (
              reports.map(r => (
                <tr key={r.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{r.title}</td>
                  <td className="px-4 py-3 text-[#64748B] capitalize">{r.report_type}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.period}</td>
                  <td className="px-4 py-3 font-bold text-[#071D49]">{r.total_visits}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.total_dispensed}</td>
                  <td className="px-4 py-3 text-[#64748B]">{r.generated_at}</td>
                  <td className="px-4 py-3"><StatusChip label={r.status} tone={getStatusTone(r.status)} /></td>
                  <td className="px-4 py-3 text-right">
                    {r.status === "Ready" && (
                      <button className="inline-flex items-center gap-1 text-blue-600 hover:underline font-semibold text-xs">
                        <Download className="w-3 h-3" /> Download
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { Pill, PlusCircle, Search, AlertTriangle } from "lucide-react";
import { Panel, StatusChip, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { addMedicineStock, adjustMedicineStock } from "./api-client";

type MedicineItem = {
  id: string;
  name: string;
  category: string;
  quantity: number;
  unit: string;
  reorder_level: number;
  expiry_date: string;
  status: string;
};

type MedicineData = {
  metrics: { total_items: number; low_stock: number; expired: number };
  medicines: MedicineItem[];
};

export function MedicineInventoryWorkspace() {
  const queryClient = useQueryClient();
  const { data, isLoading } = useSchoolQuery<MedicineData>('/admin-command/nurse/medicine-inventory');
  const [search, setSearch] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [form, setForm] = useState({ name: "", category: "", quantity: "", unit: "tablets", reorder_level: "", expiry_date: "" });

  const medicines = (data?.medicines || []).filter(m =>
    m.name.toLowerCase().includes(search.toLowerCase()) ||
    m.category.toLowerCase().includes(search.toLowerCase())
  );

  const getStatusTone = (st: string): Tone => {
    if (st === "In Stock") return "success";
    if (st === "Low Stock") return "warning";
    if (st === "Out of Stock") return "danger";
    if (st === "Expired") return "danger";
    return "neutral";
  };

  const handleAdd = async () => {
    if (!form.name || !form.quantity) { toast.error("Medicine name and quantity are required."); return; }
    setIsSubmitting(true);
    try {
      await addMedicineStock({ ...form, quantity: Number(form.quantity), reorder_level: Number(form.reorder_level) || 10 });
      queryClient.invalidateQueries({ queryKey: ["school", "session", "/admin-command/nurse/medicine-inventory"] });
      toast.success("Medicine added to inventory.");
      setShowForm(false);
      setForm({ name: "", category: "", quantity: "", unit: "tablets", reorder_level: "", expiry_date: "" });
    } catch (e: any) { toast.error(e.message || "Failed to add medicine."); }
    finally { setIsSubmitting(false); }
  };

  const handleAdjust = async (id: string, name: string) => {
    const adjustment = prompt(`Enter stock adjustment for ${name} (use negative for reduction):`);
    if (!adjustment) return;
    try {
      await adjustMedicineStock(id, { adjustment: Number(adjustment), reason: "Manual adjustment" });
      queryClient.invalidateQueries({ queryKey: ["school", "session", "/admin-command/nurse/medicine-inventory"] });
      toast.success(`Stock adjusted for ${name}.`);
    } catch (e: any) { toast.error(e.message || "Failed to adjust stock."); }
  };

  return (
    <Panel title="Medicine Inventory" description="Track medicine stock levels, expiry dates, and reorder alerts." icon={Pill} actions={
      <button onClick={() => setShowForm(true)} className="flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition">
        <PlusCircle className="w-4 h-4" /> Add Medicine
      </button>
    }>
      <div className="grid gap-4 md:grid-cols-3 mb-6">
        <div className="rounded-xl border border-[#D8E0EC] bg-[#F8FAFC] p-4">
          <div className="text-sm font-semibold text-[#64748B]">Total Items</div>
          <div className="mt-1 text-lg font-black text-[#071D49]">{isLoading ? "..." : data?.metrics?.total_items ?? 0}</div>
        </div>
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4">
          <div className="flex items-center gap-1 text-sm font-semibold text-amber-700"><AlertTriangle className="w-3 h-3" /> Low Stock</div>
          <div className="mt-1 text-lg font-black text-amber-700">{isLoading ? "..." : data?.metrics?.low_stock ?? 0}</div>
        </div>
        <div className="rounded-xl border border-rose-200 bg-rose-50 p-4">
          <div className="text-sm font-semibold text-rose-700">Expired</div>
          <div className="mt-1 text-lg font-black text-rose-700">{isLoading ? "..." : data?.metrics?.expired ?? 0}</div>
        </div>
      </div>

      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 h-4 w-4 text-[#64748B]" />
