              <tr><td colSpan={4} className="px-4 py-8 text-center text-[#64748B]">No records found. Create the first entry to get started.</td></tr>
            ) : (
              items.map((row: any, i: number) => (
                <tr key={row.id || i} className="border-t border-[#D8E0EC] hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 text-[#64748B]">{row.date}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.title}</td>
                  <td className="px-4 py-3 text-[#64748B]">{row.category}</td>
                  <td className="px-4 py-3"><span className="inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold whitespace-nowrap">{row.status}</span></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import {
  Activity, Bell, BookOpen, CheckCircle2, ClipboardCheck, GraduationCap, Home,
  MessageSquareText, Search, Settings, ShieldAlert, ShieldCheck, UsersRound,
  UserRoundCheck, Layers, LucideIcon, Wallet, BarChart3, Building2, Package, CheckSquare
} from "lucide-react";

import { ApprovalInbox } from "@/components/shared/approval-inbox";
import { NotificationBell } from "@/components/shared/notification-bell";
import { TaskQueue } from "@/components/shared/task-queue";
import { WorkflowToast } from "@/components/shared/workflow-toast";

import { PrincipalOverviewWorkspace } from "./principal-dashboard/overview-workspace";
import { PrincipalSetupChecklistWorkspace } from "./principal-dashboard/setup-checklist-workspace";
import { PrincipalSchoolProfileWorkspace } from "./principal-dashboard/school-profile-workspace";
import { PrincipalAcademicSetupWorkspace } from "./principal-dashboard/academic-setup-workspace";
import { PrincipalClassesStreamsWorkspace } from "./principal-dashboard/classes-streams-workspace";
import { PrincipalSubjectsDepartmentsWorkspace } from "./principal-dashboard/subjects-departments-workspace";
import { PrincipalStaffRolesWorkspace } from "./principal-dashboard/staff-roles-workspace";
import { PrincipalStudentsWorkspace } from "./principal-dashboard/students-workspace";
import { PrincipalAttendanceWorkspace } from "./principal-dashboard/attendance-workspace";
import { PrincipalAcademicsWorkspace } from "./principal-dashboard/academics-workspace";
import { PrincipalExamsReportsWorkspace } from "./principal-dashboard/exams-reports-workspace";
import { PrincipalFinanceOverviewWorkspace } from "./principal-dashboard/finance-overview-workspace";
import { PrincipalDisciplineWorkspace } from "./principal-dashboard/discipline-workspace";
import { PrincipalCommunicationWorkspace } from "./principal-dashboard/communication-workspace";
import { PrincipalApprovalsWorkspace } from "./principal-dashboard/approvals-workspace";
import { PrincipalReportsWorkspace } from "./principal-dashboard/reports-workspace";
import { PrincipalSettingsWorkspace } from "./principal-dashboard/settings-workspace";
import { PrincipalTeachingWorkspace } from "./principal-dashboard/teaching-workspace";

import { DashboardCommunicationProvider } from "@/lib/dashboard-communication/dashboard-communication-provider";

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

type NavItem = {
  id: string;
  label: string;
  icon: LucideIcon;
  group: string;
};

const BASE_NAV_ITEMS: NavItem[] = [
  { id: "overview", label: "Overview", icon: Home, group: "Command Center" },
  { id: "setup-checklist", label: "Setup Checklist", icon: CheckSquare, group: "Command Center" },
  { id: "school-profile", label: "School Profile", icon: Building2, group: "Command Center" },
  { id: "academic-setup", label: "Academic Setup", icon: GraduationCap, group: "Academics" },
  { id: "classes-streams", label: "Classes & Streams", icon: Layers, group: "Academics" },
  { id: "subjects-departments", label: "Subjects & Departments", icon: BookOpen, group: "Academics" },
  { id: "staff-roles", label: "Staff & Roles", icon: UsersRound, group: "People" },
  { id: "students", label: "Students", icon: UserRoundCheck, group: "People" },
  { id: "attendance", label: "Attendance", icon: Activity, group: "Daily Operations" },
  { id: "academics", label: "Academics", icon: GraduationCap, group: "Daily Operations" },
  { id: "exams-reports", label: "Exams & Report Cards", icon: ClipboardCheck, group: "Daily Operations" },
  { id: "finance-overview", label: "Finance Overview", icon: Wallet, group: "Daily Operations" },
  { id: "discipline", label: "Discipline", icon: ShieldAlert, group: "Daily Operations" },
  { id: "communication", label: "Communication", icon: MessageSquareText, group: "Administration" },
  { id: "approvals", label: "Approvals", icon: CheckCircle2, group: "Administration" },
  { id: "reports", label: "Reports", icon: BarChart3, group: "Administration" },
  { id: "settings", label: "Settings", icon: Settings, group: "Administration" },
];

import { buildSchoolSectionHref } from "./school-pages";

export function PrincipalCommandCenter({
  routeMode,
  tenantSlug,
  activeSection,
}: {
  routeMode?: "hosted" | "public";
  tenantSlug?: string | null;
  activeSection?: string;
}) {
  const [activeWorkspaceState, setActiveWorkspaceState] = useState(
    activeSection && activeSection !== "dashboard" ? activeSection : "overview"
  );
  const [isTeachingEnabled, setIsTeachingEnabled] = useState(true);

  const setActiveWorkspace = (id: string) => {
    setActiveWorkspaceState(id);
    const newPath = buildSchoolSectionHref("principal", id, routeMode ?? "hosted");
    window.history.replaceState(null, "", newPath);
  };

  useEffect(() => {
    if (!tenantSlug) return;

    window.localStorage.setItem("myshule.currentSchoolId", tenantSlug);
  }, [tenantSlug]);

  // Listen to teaching toggle from settings workspace
  useEffect(() => {
    const handleToggle = (e: Event) => {
      const customEvent = e as CustomEvent;
      setIsTeachingEnabled(customEvent.detail);
      if (!customEvent.detail && activeWorkspaceState === "teaching") {
        setActiveWorkspace("overview");
      }
    };
    window.addEventListener("principal-teaching-toggle", handleToggle);
    return () => window.removeEventListener("principal-teaching-toggle", handleToggle);
  }, [activeWorkspaceState]);

  const navItems = useMemo(() => {
    if (isTeachingEnabled) {
      const teachingItem = { id: "teaching", label: "My Teaching", icon: BookOpen, group: "Optional Duties" };
      return [
        ...BASE_NAV_ITEMS,
        teachingItem,
      ];
    }
    return BASE_NAV_ITEMS;
  }, [isTeachingEnabled]);

  const groups = useMemo(() => {
    return navItems.reduce<Record<string, NavItem[]>>((acc, item) => {
      acc[item.group] = [...(acc[item.group] ?? []), item];
      return acc;
    }, {});
  }, [navItems]);

  const renderWorkspace = () => {
    switch (activeWorkspaceState) {
      case "overview": return <PrincipalOverviewWorkspace />;
      case "setup-checklist": return <PrincipalSetupChecklistWorkspace />;
      case "school-profile": return <PrincipalSchoolProfileWorkspace />;
      case "academic-setup": return <PrincipalAcademicSetupWorkspace />;
      case "classes-streams": return <PrincipalClassesStreamsWorkspace />;
      case "subjects-departments": return <PrincipalSubjectsDepartmentsWorkspace />;
      case "staff-roles": return <PrincipalStaffRolesWorkspace />;
      case "students": return <PrincipalStudentsWorkspace />;
      case "attendance": return <PrincipalAttendanceWorkspace />;
      case "academics": return <PrincipalAcademicsWorkspace />;
      case "exams-reports": return <PrincipalExamsReportsWorkspace />;
      case "finance-overview": return <PrincipalFinanceOverviewWorkspace />;
      case "discipline": return <PrincipalDisciplineWorkspace />;
      case "communication": return <PrincipalCommunicationWorkspace />;
      case "approvals": return <PrincipalApprovalsWorkspace />;
      case "reports": return <PrincipalReportsWorkspace />;
      case "settings": return <PrincipalSettingsWorkspace />;
      case "teaching": return <PrincipalTeachingWorkspace />;
      default: return <PrincipalOverviewWorkspace />;
    }
  };

  return (
    <DashboardCommunicationProvider>
      <div data-route-mode={routeMode ?? "hosted"} className="min-h-screen bg-[#F3F4F6] pb-24 lg:pb-6">
        <div className="grid gap-5 p-3 md:p-5 xl:grid-cols-[300px_minmax(0,1fr)]">
          {/* Sidebar */}
          <aside className="hidden h-[calc(100vh-40px)] rounded-[var(--radius-xl)] border border-[#C8D5EA]/50 bg-[#071D49] p-4 text-white shadow-[0_24px_70px_rgba(7,29,73,0.22)] xl:sticky xl:top-5 xl:flex xl:flex-col">
            <div className="rounded-[var(--radius-lg)] border border-white/10 bg-white/[0.06] p-4">
              <p className="text-xs font-black uppercase text-cyan-200">Principal Command</p>
              <h2 className="mt-2 text-2xl font-black">School Operations</h2>
            </div>
            <nav className="mt-5 flex-1 space-y-5 overflow-auto pr-1 pb-10 custom-scrollbar">
              {Object.entries(groups).map(([group, items]) => (
                <div key={group}>
                  <p className="px-3 text-[11px] font-black uppercase tracking-[0.16em] text-white/45">{group}</p>
                  <div className="mt-2 grid gap-1">
                    {items.map((item) => {
                      const Icon = item.icon;
                      const active = activeWorkspaceState === item.id;
                      return (
                        <button
                          key={item.id}
                          onClick={() => setActiveWorkspace(item.id)}
                          className={cn(
                            "flex min-h-10 w-full items-center gap-3 rounded-[var(--radius)] px-3 py-2 text-sm font-bold transition hover:-translate-y-0.5",
                            active
                              ? "border border-cyan-300/35 bg-cyan-300/12 text-cyan-100 shadow-[inset_4px_0_0_#22D3EE]"
                              : "text-white/72 hover:bg-white/10 hover:text-white"
                          )}
                        >
                          <Icon className="h-4 w-4 shrink-0" aria-hidden="true" />
                          <span className="truncate">{item.label}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </nav>
          </aside>

          {/* Main Content */}
          <main className="min-w-0 space-y-5">
            <header className="rounded-[var(--radius-xl)] border border-[#C8D5EA] bg-white p-4 text-[#071D49] shadow-[0_18px_50px_rgba(7,29,73,0.12)] md:p-5">
              <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
                <div className="flex items-center gap-4">
                  <div className="grid h-12 w-12 place-items-center rounded-[var(--radius-lg)] bg-[#071D49] text-sm font-black text-white shadow-[0_16px_34px_rgba(7,29,73,0.18)]">
                    MS
                  </div>
                  <div>
                    <p className="text-xs font-black uppercase tracking-[0.16em] text-[#5F6F89]">
                      Good morning, Principal
                    </p>
                    <p className="mt-1 text-lg font-black md:text-2xl">Principal Dashboard</p>
                  </div>
                </div>

                <div className="grid gap-3 lg:min-w-[640px]">
                  <div className="relative">
                    <Search className="pointer-events-none absolute left-4 top-3.5 h-5 w-5 text-[#5F6F89]" aria-hidden="true" />
                    <input
                      placeholder="Search student, teacher, incident, class, parent, or report"
                      className="h-12 w-full rounded-[var(--radius-lg)] border border-[#C8D5EA] bg-[#F8FAFC] pl-12 pr-4 text-sm font-semibold text-[#071D49] outline-none transition focus:border-cyan-400 focus:ring-4 focus:ring-cyan-300/20"
                    />
                  </div>
                  <div className="flex flex-wrap items-center gap-2">
                    <TaskQueue />
                    <ApprovalInbox currentUserId="school" />
                    <NotificationBell />
                  </div>
                </div>
              </div>
            </header>

            <div className="rounded-[var(--radius-xl)] bg-[#071D49] p-5 shadow-[0_24px_70px_rgba(7,29,73,0.22)]">
              <h1 className="mb-6 text-3xl font-black text-white">
                {navItems.find((n) => n.id === activeWorkspaceState)?.label}
              </h1>
              {renderWorkspace()}
            </div>
          </main>
        </div>

        {/* Mobile nav */}
        <div className="fixed inset-x-0 bottom-0 z-40 border-t border-white/10 bg-[#071D49]/94 px-2 py-2 text-white shadow-[0_-18px_50px_rgba(0,0,0,0.28)] backdrop-blur-xl lg:hidden">
          <div className="grid grid-cols-5 gap-1">
            {navItems.slice(0, 5).map((item) => {
              const Icon = item.icon;
              return (
                <button
                  key={item.id}
                  onClick={() => setActiveWorkspace(item.id)}
                  className={cn(
                    "flex min-h-14 flex-col items-center justify-center gap-1 rounded-[var(--radius)] px-1 text-center text-[10px] font-black active:scale-95",
                    activeWorkspaceState === item.id ? "text-cyan-400" : "text-white/70"
                  )}
                >
                  <Icon className="h-4 w-4" aria-hidden="true" />
                  <span className="truncate w-full">{item.label.split(' ')[0]}</span>
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </DashboardCommunicationProvider>
  );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { AlertCircle, GraduationCap, Calendar, Settings, Plus, Loader2, FileText, CheckSquare } from "lucide-react";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { requestDashboardApi } from "@/lib/dashboard/api-client";
import { usePermissions } from "@/components/providers/permission-context";

type AcademicSetupData = {
  status: "active" | "degraded" | "setup_required";
  activeTerm: string;
  weeksRemaining: number;
  gradingsConfigured: boolean;
  subjectsRegistered: number;
  teachersAssigned: number;
  pendingConfigurations: number;
  recentChanges: Array<{ title: string; time: string }>;
};

export function PrincipalAcademicSetupWorkspace() {
  const { data, isLoading, error, refetch } = useSchoolQuery<AcademicSetupData>('/admin-command/principal/academic-setup');
  const { hasPermission } = usePermissions();
  const { data: yearsData } = useSchoolQuery<any[]>('/academics/academic-years');

  const [actionError, setActionError] = useState<string | null>(null);

  const [isYearModalOpen, setIsYearModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formError, setFormError] = useState("");

  const hasYears = yearsData && yearsData.length > 0;

  const handleCreateYear = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/years', {
        method: "POST",
        body: {
          name: formData.get("name"),
          starts_on: formData.get("starts_on"),
          ends_on: formData.get("ends_on"),
        }
      });
      setIsYearModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create academic year");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCreateTerm = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/terms', {
        method: "POST",
        body: {
          academic_year_id: formData.get("academic_year_id"),
          name: formData.get("name"),
          starts_on: formData.get("starts_on"),
          ends_on: formData.get("ends_on"),
        }
      });
      setIsTermModalOpen(false);
      refetch();
    } catch (err: any) {
      setFormError(err.message || "Failed to create academic term");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleArchiveYear = async (id: string) => {
    if (!confirm("Are you sure you want to archive this academic year?")) return;
    setActionError(null);
    try {
      await requestDashboardApi(`/academics/years/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      setActionError(err.message || "Failed to archive year");
    }
  };

  const { data: gradingData } = useSchoolQuery<any[]>('/academics/grading-systems');
  const { data: attendanceData } = useSchoolQuery<any[]>('/academics/attendance-settings');
  const { data: reportCardData } = useSchoolQuery<any[]>('/academics/report-card-settings');

  const [isGradingModalOpen, setIsGradingModalOpen] = useState(false);
  const [isSubmittingGrading, setIsSubmittingGrading] = useState(false);
  const [gradingFormError, setGradingFormError] = useState("");

  const [isAttendanceModalOpen, setIsAttendanceModalOpen] = useState(false);
  const [isSubmittingAttendance, setIsSubmittingAttendance] = useState(false);
  const [attendanceFormError, setAttendanceFormError] = useState("");

  const [isReportCardModalOpen, setIsReportCardModalOpen] = useState(false);
  const [isSubmittingReportCard, setIsSubmittingReportCard] = useState(false);
  const [reportCardFormError, setReportCardFormError] = useState("");

  const handleCreateGrading = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingGrading(true);
    setGradingFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/grading-systems', {
        method: "POST",
        body: {
          name: formData.get("name"),
          description: formData.get("description"),
        }
      });
      setIsGradingModalOpen(false);
      refetch();
    } catch (err: any) {
      setGradingFormError(err.message || "Failed to create grading system");
    } finally {
      setIsSubmittingGrading(false);
    }
  };

  const handleCreateAttendance = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingAttendance(true);
    setAttendanceFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/attendance-settings', {
        method: "POST",
        body: {
          name: formData.get("name"),
          description: formData.get("description"),
        }
      });
      setIsAttendanceModalOpen(false);
      refetch();
    } catch (err: any) {
      setAttendanceFormError(err.message || "Failed to create attendance setting");
    } finally {
      setIsSubmittingAttendance(false);
    }
  };

  const handleCreateReportCard = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmittingReportCard(true);
    setReportCardFormError("");
    const formData = new FormData(e.currentTarget);
    try {
      await requestDashboardApi('/academics/report-card-settings', {
        method: "POST",
        body: {
          name: formData.get("name"),
          grading_system_id: formData.get("grading_system_id") || null,
          show_rank: formData.get("show_rank") === 'on',
          show_attendance: formData.get("show_attendance") === 'on',
        }
      });
      setIsReportCardModalOpen(false);
      refetch();
    } catch (err: any) {
      setReportCardFormError(err.message || "Failed to create report card setting");
    } finally {
      setIsSubmittingReportCard(false);
    }
  };

  const handleArchiveGrading = async (id: string) => {
    if (!confirm("Are you sure you want to archive this grading system?")) return;
    setActionError(null);
    try {
      await requestDashboardApi(`/academics/grading-systems/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      setActionError(err.message || "Failed to archive grading system");
    }
  };

  const handleArchiveAttendance = async (id: string) => {
    if (!confirm("Are you sure you want to archive this attendance setting?")) return;
    setActionError(null);
    try {
      await requestDashboardApi(`/academics/attendance-settings/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      setActionError(err.message || "Failed to archive attendance setting");
    }
  };

  const handleArchiveReportCard = async (id: string) => {
    if (!confirm("Are you sure you want to archive this report card setting?")) return;
    setActionError(null);
    try {
      await requestDashboardApi(`/academics/report-card-settings/${id}`, { method: "DELETE" });
      refetch();
    } catch (err: any) {
      setActionError(err.message || "Failed to archive report card setting");
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="animate-pulse space-y-4">
          <div className="h-24 bg-white/5 rounded-xl border border-white/10" />
          <div className="h-64 bg-white/5 rounded-xl border border-white/10" />
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <Card className="border border-red-500/20 bg-red-500/10 p-6">
        <div className="flex items-center gap-3">
          <AlertCircle className="h-6 w-6 text-red-500" />
          <h2 className="text-xl font-bold text-red-500">Failed to load Academic Setup</h2>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {actionError && (
        <Card className="border border-red-500/20 bg-red-500/10 p-4">
          <div className="flex items-center gap-3">
            <AlertCircle className="h-5 w-5 text-red-500" />
            <p className="text-sm font-medium text-red-500">{actionError}</p>
          </div>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-4">
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Active Term</div>
          <div className="mt-2 text-xl font-black text-white">{data.activeTerm}</div>
          <div className="mt-1 text-xs text-white/50">{data.weeksRemaining} weeks remaining</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Grading System</div>
          <div className="mt-2 text-xl font-black text-white">
            {data.gradingsConfigured ? "Configured" : "Pending"}
          </div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Subjects Registered</div>
          <div className="mt-2 text-2xl font-black text-white">{data.subjectsRegistered}</div>
        </Card>
        <Card className="border border-white/10 bg-white/5 p-5">
          <div className="text-sm font-semibold text-white/70">Teachers Assigned</div>
          <div className="mt-2 text-2xl font-black text-white">{data.teachersAssigned}</div>
        </Card>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        <Card className="border border-white/10 bg-white/5 p-6 flex flex-col h-full min-h-[300px]">
          <div className="flex items-center justify-between mb-6 border-b border-white/10 pb-4">
            <h2 className="text-xl font-bold text-white">Configuration Hub</h2>
          </div>
          
          <div className="space-y-3 flex-1 overflow-y-auto pr-2">
            <div className="flex items-center justify-between p-4 rounded-lg bg-white/5 border border-white/10">
              <div className="flex items-center gap-3">
                <div className="flex-shrink-0 w-10 h-10 rounded-full bg-blue-500/20 flex items-center justify-center border border-blue-500/30">
                  <Calendar className="h-5 w-5 text-blue-400" />
                </div>
                <div>
                  <p className="font-bold text-white">Academic Calendar</p>
                  <p className="text-xs text-white/60">Manage years and terms</p>
                </div>
              </div>
              <div className="flex gap-2">
                {hasPermission('academics:write') && (
                  <>
                    <Button size="sm" variant="outline" onClick={() => setIsYearModalOpen(true)}>
                      <Plus className="h-4 w-4 mr-1" /> Year
                    </Button>
                    <Button 
                      size="sm" 
                      variant="outline" 
                      onClick={() => setIsTermModalOpen(true)}
                      disabled={!hasYears}
                      title={!hasYears ? "Cannot create a term before an academic year exists" : ""}
                    >
                      <Plus className="h-4 w-4 mr-1" /> Term
                    </Button>
                  </>
