"use client";
import { useState } from "react";
import { UserCheck, UserX, Clock, AlertTriangle, Bell } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, MetricCard, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { sendAttendanceAlert } from "./api-client";

type ClassAttendance = {
  id: string;
  class_name: string;
  stream: string;
  total_students: number;
  present: number;
  absent: number;
  rate: number;
  class_teacher: string;
  marked_at: string | null;
};

type AttendanceData = {
  metrics: {
    overall_rate: number;
    total_present: number;
    total_absent: number;
    classes_not_marked: number;
  };
  classes: ClassAttendance[];
};

export function AttendanceMonitoringWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<AttendanceData>('/admin-command/principal/attendance-monitoring');
  const [alertingId, setAlertingId] = useState<string | null>(null);

  const classes = data?.classes || [];

  const getRateTone = (rate: number): Tone => {
    if (rate >= 90) return "success";
    if (rate >= 75) return "warning";
    return "danger";
  };

  const handleAlert = async (classId: string) => {
    setAlertingId(classId);
    try {
      await sendAttendanceAlert(classId);
      toast.success("Attendance alert sent to class teacher.");
    } catch {
      toast.error("Failed to send attendance alert.");
    } finally {
      setAlertingId(null);
    }
  };

  return (
    <Panel title="Attendance Monitoring" description="Track daily attendance rates across all classes." icon={UserCheck}>
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <MetricCard label="Overall Rate" value={isLoading ? "…" : `${data?.metrics?.overall_rate ?? 0}%`} icon={UserCheck} tone={getRateTone(data?.metrics?.overall_rate ?? 0)} />
        <MetricCard label="Present Today" value={isLoading ? "…" : data?.metrics?.total_present ?? 0} icon={UserCheck} tone="success" />
        <MetricCard label="Absent Today" value={isLoading ? "…" : data?.metrics?.total_absent ?? 0} icon={UserX} tone={(data?.metrics?.total_absent ?? 0) > 10 ? "danger" : "neutral"} />
        <MetricCard label="Not Yet Marked" value={isLoading ? "…" : data?.metrics?.classes_not_marked ?? 0} icon={Clock} tone={(data?.metrics?.classes_not_marked ?? 0) > 0 ? "warning" : "success"} />
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Stream</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Total</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Present</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Absent</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Rate</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class Teacher</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Marked</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={9} className="px-4 py-8 text-center text-[#64748B]">Loading attendance data…</td></tr>
            ) : classes.length === 0 ? (
              <tr><td colSpan={9} className="px-4 py-8 text-center text-[#64748B]">No attendance records for today. Attendance will appear once class teachers mark their registers.</td></tr>
            ) : (
              classes.map((c) => (
                <tr key={c.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{c.class_name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.stream || "—"}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.total_students}</td>
                  <td className="px-4 py-3 text-emerald-700 font-bold">{c.present}</td>
                  <td className="px-4 py-3 text-rose-700 font-bold">{c.absent}</td>
                  <td className="px-4 py-3"><StatusChip label={`${c.rate}%`} tone={getRateTone(c.rate)} /></td>
                  <td className="px-4 py-3 text-[#64748B]">{c.class_teacher}</td>
                  <td className="px-4 py-3 text-[#64748B]">{c.marked_at || <StatusChip label="Not Marked" tone="warning" />}</td>
                  <td className="px-4 py-3 text-right">
                    {!c.marked_at && (
                      <button
                        disabled={alertingId === c.id}
                        onClick={() => handleAlert(c.id)}
                        className="inline-flex items-center gap-1 rounded-lg bg-amber-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-amber-700 transition disabled:opacity-50"
                      >
                        <Bell className="h-3 w-3" /> Remind
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { Layers, Plus, Users } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, MetricCard, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { createClass } from "./api-client";

type StreamRecord = { id: string; name: string; students_count: number };
type ClassRecord = {
  id: string;
  name: string;
  level: string;
  class_teacher: string;
  total_students: number;
  streams: StreamRecord[];
  status: string;
};

type ClassesStreamsData = {
  metrics: { total_classes: number; total_streams: number; total_students: number; avg_class_size: number };
  classes: ClassRecord[];
};

export function ClassesStreamsWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<ClassesStreamsData>('/admin-command/principal/classes-streams');
  const [isCreating, setIsCreating] = useState(false);

  const classes = data?.classes || [];

  const handleCreateClass = async () => {
    setIsCreating(true);
    try {
      await createClass({ name: "New Class" });
      await refetch();
      toast.success("Class created successfully.");
    } catch {
      toast.error("Failed to create class.");
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <Panel
      title="Classes & Streams"
      description="Manage class levels, streams, and student distribution."
      icon={Layers}
      actions={
        <button disabled={isCreating} onClick={handleCreateClass} className="inline-flex items-center gap-2 rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50">
          <Plus className="h-4 w-4" />
          {isCreating ? "Creating…" : "Add Class"}
        </button>
      }
    >
      <div className="grid gap-4 md:grid-cols-4 mb-6">
        <MetricCard label="Total Classes" value={isLoading ? "…" : data?.metrics?.total_classes ?? 0} icon={Layers} />
        <MetricCard label="Total Streams" value={isLoading ? "…" : data?.metrics?.total_streams ?? 0} icon={Layers} tone="info" />
        <MetricCard label="Total Students" value={isLoading ? "…" : data?.metrics?.total_students ?? 0} icon={Users} />
        <MetricCard label="Avg Class Size" value={isLoading ? "…" : data?.metrics?.avg_class_size ?? 0} icon={Users} tone="info" />
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Level</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Class Teacher</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Students</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Streams</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC] text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={7} className="px-4 py-8 text-center text-[#64748B]">Loading classes…</td></tr>
            ) : classes.length === 0 ? (
              <tr><td colSpan={7} className="px-4 py-8 text-center text-[#64748B]">No classes configured. Add the first class to begin organizing your school structure.</td></tr>
            ) : (
              classes.map((cls) => (
                <tr key={cls.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{cls.name}</td>
                  <td className="px-4 py-3 text-[#64748B]">{cls.level}</td>
                  <td className="px-4 py-3 text-[#64748B]">{cls.class_teacher || "—"}</td>
                  <td className="px-4 py-3 text-[#64748B]">{cls.total_students}</td>
                  <td className="px-4 py-3 text-[#64748B]">{cls.streams.length > 0 ? cls.streams.map(s => `${s.name} (${s.students_count})`).join(", ") : "No streams"}</td>
                  <td className="px-4 py-3"><StatusChip label={cls.status || "Active"} tone={cls.status === "Active" ? "success" : "neutral"} /></td>
                  <td className="px-4 py-3 text-right">
                    <button className="text-blue-600 hover:underline font-semibold text-xs">Manage</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";
import { useState } from "react";
import { LayoutDashboard, Users, GraduationCap, DollarSign, UserCheck, UserX, AlertTriangle, ClipboardCheck, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { Panel, StatusChip, MetricCard, Tone } from "./shared";
import { useSchoolQuery } from "@/lib/data/school-hooks";

type AlertItem = {
  id: string;
  title: string;
  category: string;
  severity: string;
  timestamp: string;
  status: string;
};

type OverviewData = {
  metrics: {
    total_students: number;
    total_staff: number;
    attendance_rate: number;
    fee_collection_rate: number;
    pending_approvals: number;
    open_discipline_cases: number;
  };
  alerts: AlertItem[];
};

export function OverviewWorkspace() {
  const { data, isLoading, refetch } = useSchoolQuery<OverviewData>('/admin-command/principal/overview');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const metrics = data?.metrics;
  const alerts = data?.alerts || [];

  const handleRefresh = async () => {
    setIsRefreshing(true);
    try {
      await refetch();
      toast.success("Dashboard refreshed.");
    } catch {
      toast.error("Failed to refresh dashboard.");
    } finally {
      setIsRefreshing(false);
    }
  };

  const getSeverityTone = (severity: string): Tone => {
    switch (severity?.toLowerCase()) {
      case "critical": return "danger";
      case "high": return "danger";
      case "medium": return "warning";
      case "low": return "info";
      default: return "neutral";
    }
  };

  const getStatusTone = (status: string): Tone => {
    switch (status?.toLowerCase()) {
      case "resolved": return "success";
      case "in_progress": case "in progress": return "info";
      case "pending": return "warning";
      case "open": return "danger";
      default: return "neutral";
    }
  };

  return (
    <Panel
      title="Principal Overview"
      description="School-wide snapshot — key metrics, alerts, and items requiring your attention."
      icon={LayoutDashboard}
      actions={
        <button disabled={isRefreshing} onClick={handleRefresh} className="rounded-lg bg-[#071D49] px-4 py-2 text-sm font-black text-white hover:bg-blue-900 transition disabled:opacity-50">
          {isRefreshing ? "Refreshing…" : "Refresh"}
        </button>
      }
    >
      {/* Metrics */}
      <div className="grid gap-4 md:grid-cols-3 lg:grid-cols-6 mb-6">
        <MetricCard label="Total Students" value={isLoading ? "…" : metrics?.total_students ?? 0} icon={GraduationCap} />
        <MetricCard label="Total Staff" value={isLoading ? "…" : metrics?.total_staff ?? 0} icon={Users} />
        <MetricCard label="Attendance Rate" value={isLoading ? "…" : `${metrics?.attendance_rate ?? 0}%`} icon={UserCheck} tone={(metrics?.attendance_rate ?? 100) < 80 ? "danger" : "success"} />
        <MetricCard label="Fee Collection" value={isLoading ? "…" : `${metrics?.fee_collection_rate ?? 0}%`} icon={DollarSign} tone={(metrics?.fee_collection_rate ?? 100) < 70 ? "warning" : "success"} />
        <MetricCard label="Pending Approvals" value={isLoading ? "…" : metrics?.pending_approvals ?? 0} icon={ClipboardCheck} tone={(metrics?.pending_approvals ?? 0) > 0 ? "warning" : "success"} />
        <MetricCard label="Discipline Cases" value={isLoading ? "…" : metrics?.open_discipline_cases ?? 0} icon={ShieldAlert} tone={(metrics?.open_discipline_cases ?? 0) > 0 ? "danger" : "success"} />
      </div>

      {/* Alerts Table */}
      <div className="overflow-x-auto rounded-xl border border-[#D8E0EC]">
        <table className="w-full text-sm text-left whitespace-nowrap">
          <thead className="bg-[#F8FAFC] text-[#071D49]">
            <tr>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Severity</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Alert</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Category</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Time</th>
              <th className="px-4 py-3 font-bold border-b border-[#D8E0EC]">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D8E0EC]">
            {isLoading ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">Loading school overview…</td></tr>
            ) : alerts.length === 0 ? (
              <tr><td colSpan={5} className="px-4 py-8 text-center text-[#64748B]">No active alerts. Your school is running smoothly.</td></tr>
            ) : (
              alerts.map((alert) => (
                <tr key={alert.id} className="hover:bg-[#F8FAFC]">
                  <td className="px-4 py-3"><StatusChip label={alert.severity} tone={getSeverityTone(alert.severity)} /></td>
                  <td className="px-4 py-3 font-semibold text-[#071D49]">{alert.title}</td>
                  <td className="px-4 py-3 text-[#64748B]">{alert.category}</td>
                  <td className="px-4 py-3 text-[#64748B]">{alert.timestamp}</td>
                  <td className="px-4 py-3"><StatusChip label={alert.status} tone={getStatusTone(alert.status)} /></td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Search, ShoppingCart, FileText, Truck, DollarSign, LayoutDashboard, Plus, Package } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { StatusPill } from "@/components/ui/status-pill";
import { useSchoolQuery } from "@/lib/data/school-hooks";
import { buildSchoolSectionHref } from "./school-pages";

type ProcurementView = "overview" | "pos" | "suppliers" | "requisitions" | "budget";

function Panel({ title, description, icon: Icon, children, actions }: { title: string; description?: string; icon?: any; children: React.ReactNode; actions?: React.ReactNode }) {
  return (
    <section className="rounded-2xl border border-[#D8E0EC] bg-white p-5 shadow-[0_18px_50px_rgba(7,29,73,0.08)]">
      <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 gap-3">
          {Icon && (
            <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#EEF5FF] text-[#1D4ED8]">
              <Icon className="h-5 w-5" aria-hidden="true" />
            </span>
          )}
          <div>
            <h2 className="text-xl font-black tracking-[-0.01em] text-[#071D49]">{title}</h2>
            {description && <p className="mt-1 text-sm leading-6 text-[#64748B]">{description}</p>}
          </div>
        </div>
        {actions && <div className="shrink-0">{actions}</div>}
      </div>
      {children}
    </section>
  );
}

function OverviewWorkspace() {
  const { data: posData } = useSchoolQuery<any>("/api/inventory/purchase-orders?limit=5");
  const { data: reqsData } = useSchoolQuery<any>("/api/inventory/requests?status=pending");
  const { data: summaryData } = useSchoolQuery<any>("/api/inventory/summary");

  const pendingReqs = reqsData?.meta?.total_items ?? 0;
  const activePOs = posData?.meta?.total_items ?? 0;
  const awaitingDelivery = summaryData?.awaiting_delivery ?? 0;
  const recentPOs = posData?.data ?? [];

  return (
    <>
      <div className="grid gap-6 md:grid-cols-3 mb-8">
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Pending Requisitions</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{pendingReqs}</div>
        </Card>
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Active Purchase Orders</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{activePOs}</div>
        </Card>
        <Card className="p-6">
          <div className="text-sm font-semibold text-gray-500">Awaiting Delivery</div>
          <div className="mt-2 text-3xl font-black text-[#071D49]">{awaitingDelivery}</div>
        </Card>
      </div>

      <Card className="p-6">
        <h2 className="text-xl font-bold text-[#071D49] mb-4">Recent Procurement Activity</h2>
        {recentPOs.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            <ShoppingCart className="h-12 w-12 mx-auto mb-4 opacity-20" />
            <p>Purchase orders and requisitions will appear here.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {recentPOs.map((po: any, i: number) => (
              <div key={i} className="flex items-center justify-between p-4 rounded-xl border border-gray-100 bg-gray-50/50 hover:bg-gray-50 transition">
                <div>
                  <p className="font-semibold text-[#071D49]">{po.order_number}</p>
                  <p className="text-sm text-gray-500 mt-1">{po.supplier_name} • KES {po.total_amount?.toLocaleString()}</p>
                </div>
                <StatusPill label={po.status} tone={po.status === 'approved' ? 'ok' : 'warning'} />
              </div>
            ))}
          </div>
        )}
      </Card>
    </>
  );
}

