        <Card className="p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <p className="eyebrow">Clinic visits</p>
              <h3 className="mt-1 text-lg font-black text-foreground">Today&apos;s sick bay register</h3>
