              </thead>
              <tbody className="divide-y divide-[#E2E8F0] bg-white">
                {visits.map((visit) => (
                  <tr key={visit.id}>
                    <td className="px-3 py-3 font-black text-foreground">
                      {visit.student}
                      <span className="block text-xs font-semibold text-muted">{visit.className} - {visit.time}</span>
