                    Select all visible
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={clearBulkRosterSelection}
                    disabled={selectedBulkStudentIds.size === 0}
                  >
                    Clear selection
                  </Button>
