                      <button disabled={actionId === doc.id} onClick={() => handlePrint(doc.id)} className="inline-flex items-center gap-1 rounded-lg bg-[#071D49] px-3 py-1.5 text-xs font-bold text-white hover:bg-blue-900 disabled:opacity-50">
