type QueueEntry = {
  id: string;
  ticket_number: string;
  visitor_name: string;
  purpose: string;
  person_to_see: string;
  arrival_time: string;
  status: string;
  wait_time_minutes: number;
};

type QueueData = {
  metrics: {
    total_in_queue: number;
    being_served: number;
    completed_today: number;
    avg_wait_minutes: number;
  };
