        </p>
      </div>

      <div className="mt-12 space-y-2">
        <p>Yours sincerely,</p>
        <div className="w-48 border-b border-gray-800 my-8"></div>
        <p><strong>{principalName}</strong></p>
        <p>Principal</p>
      </div>
    </div>
  );
}

