        )}
      </div>

      <ApprovalDetailDrawer 
        request={selectedRequest}
        isOpen={!!selectedRequest}
        onClose={() => setSelectedRequest(null)}
        onProcessed={fetchRequests}
      />
    </div>
  );
}

