        const date = new Date(log.created_at);
        const timeLabel = isNaN(date.getTime()) 
          ? log.created_at 
          : new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: 'numeric', hour12: true }).format(date);

