import { useState, useEffect, useCallback } from 'react';
import { DashboardApi } from '../lib/client/dashboard-api';

export function useNotifications() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchNotifications = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await DashboardApi.getNotifications();
      setNotifications(data);
    } catch (err) {
      console.error('Failed to fetch notifications', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const markAsRead = async (id: string) => {
    try {
      await DashboardApi.markNotificationRead(id);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
    } catch (err) {
      console.error('Failed to mark as read', err);
    }
  };

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  return { notifications, unreadCount, isLoading, markAsRead, refetch: fetchNotifications };
}

"use client";

import { useEffect } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useDashboardEventBus } from "@/lib/dashboard-communication/dashboard-communication-provider";
import { getCurrentSchoolId } from "@/lib/school/school-operational-store";

const STUDENT_EVENTS = [
  "STUDENT_ADMITTED",
  "STUDENT_UPDATED",
  "STUDENT_ENROLLED",
  "STUDENT_CLASS_PLACED",
  "STUDENT_PROMOTED",
  "STUDENT_STATUS_CHANGED",
] as const;

export function useStudentEvents() {
  const queryClient = useQueryClient();
  const eventBus = useDashboardEventBus();

  useEffect(() => {
    if (!eventBus) return;

    const tenantId = getCurrentSchoolId();

    const unsubscribeFunctions = STUDENT_EVENTS.map((eventType) => {
      return eventBus.subscribe(eventType, (event) => {
        // Invalidate all student queries so dashboards auto-refresh
        queryClient.invalidateQueries({ queryKey: ["school", tenantId] });
      });
    });

    return () => {
      unsubscribeFunctions.forEach((unsubscribe) => unsubscribe());
    };
  }, [eventBus, queryClient]);
}

export interface ApprovalRequest {
  id: string;
  module: string;
  action: string;
  targetEntityType: string;
  targetEntityId: string;
  requestedByUserId: string;
  status: 'PENDING_APPROVAL' | 'APPROVED' | 'REJECTED' | 'CHANGES_REQUESTED' | 'ESCALATED';
  reason?: string;
  oldValue?: any;
  newValue?: any;
  createdAt: string;
  updatedAt: string;
  auditLogs?: any[];
}

export const ApprovalsApi = {
  async getPendingRequests(): Promise<ApprovalRequest[]> {
    const res = await fetch('/api/approvals/pending');
    if (!res.ok) throw new Error('Failed to fetch pending approvals');
    const data = await res.json();
    return data.data;
  },

  async getMyRequests(): Promise<ApprovalRequest[]> {
    const res = await fetch('/api/approvals/my-requests');
    if (!res.ok) throw new Error('Failed to fetch my requests');
    const data = await res.json();
    return data.data;
  },

  async processAction(id: string, action: 'APPROVE' | 'REJECT' | 'REQUEST_CHANGES' | 'ESCALATE', comment?: string): Promise<ApprovalRequest> {
    const res = await fetch(`/api/approvals/${id}/action`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, comment })
    });
    if (!res.ok) throw new Error(`Failed to process action ${action}`);
    const data = await res.json();
    return data.data;
  }
};

