class SyncQueueService {
  private dbPromise: Promise<IDBPDatabase<ShuleOfflineDB>> | null = null;

  constructor() {}

  private getDB(): Promise<IDBPDatabase<ShuleOfflineDB>> {
    if (typeof window === 'undefined') {
      return Promise.reject(new Error('IndexedDB is not available on the server'));
    }
    if (!this.dbPromise) {
      this.dbPromise = openDB<ShuleOfflineDB>('myshule-offline-db', 1, {
        upgrade(db) {
          if (!db.objectStoreNames.contains('sync_queue')) {
            const store = db.createObjectStore('sync_queue', { keyPath: 'id' });
            store.createIndex('by-school', 'schoolId');
            store.createIndex('by-status', 'status');
            store.createIndex('by-module', 'module');
          }
        },
      });
    }
    return this.dbPromise;
  }

  /**
   * Adds a new record to the offline queue
   */
  async enqueue(
    recordData: Omit<OfflineSyncRecord, 'id' | 'operationId' | 'status' | 'retryCount' | 'createdAtLocal'>,
    isDraft = false
  ): Promise<OfflineSyncRecord> {
    const db = await this.getDB();
    const id = uuidv4();
    const operationId = uuidv4();

    const record: OfflineSyncRecord = {
      ...recordData,
      id,
      operationId,
      status: isDraft ? 'Draft' : 'Saved offline',
      retryCount: 0,
      createdAtLocal: new Date().toISOString(),
    };

    await db.put('sync_queue', record);
    return record;
  }

  /**
   * Retrieves records for a specific school and status
   */
  async getRecordsBySchoolAndStatus(schoolId: string, status: SyncStatus): Promise<OfflineSyncRecord[]> {
    const db = await this.getDB();
    const allForSchool = await db.getAllFromIndex('sync_queue', 'by-school', schoolId);
    return allForSchool.filter(r => r.status === status);
  }

  /**
   * Retrieves all records for a given school (to ensure tenant isolation on the client)
   */
  async getAllForSchool(schoolId: string): Promise<OfflineSyncRecord[]> {
    const db = await this.getDB();
    return db.getAllFromIndex('sync_queue', 'by-school', schoolId);
  }

  /**
   * Updates the status of a sync record
   */
  async updateStatus(id: string, status: SyncStatus, errorMessage?: string): Promise<void> {
    const db = await this.getDB();
    const record = await db.get('sync_queue', id);
    if (record) {
      record.status = status;
      if (errorMessage) {
        record.errorMessage = errorMessage;
      }
      if (status === 'Failed') {
        record.retryCount += 1;
      }
      if (status === 'Synced') {
        record.syncedAt = new Date().toISOString();
      }
      await db.put('sync_queue', record);
    }
  }

  /**
   * Remove a record completely
   */
  async removeRecord(id: string): Promise<void> {
    const db = await this.getDB();
    await db.delete('sync_queue', id);
  }

  /**
   * Clear all synced records
   */
  async clearSyncedRecords(schoolId: string): Promise<void> {
    const db = await this.getDB();
    const records = await this.getRecordsBySchoolAndStatus(schoolId, 'Synced');
    
    const tx = db.transaction('sync_queue', 'readwrite');
    for (const record of records) {
      await tx.store.delete(record.id);
    }
    await tx.done;
  }
}

export const syncQueue = new SyncQueueService();

import { useMutation, UseMutationOptions, useQueryClient } from '@tanstack/react-query';
import { syncQueue } from './sync-queue';
import { useAuth } from '@/lib/auth/auth-context';
import { toast } from 'sonner';

interface OfflineMutationOptions<TData, TError, TVariables, TContext>
  extends UseMutationOptions<TData, TError, TVariables, TContext> {
  module: string;
  action: string;
  schoolId: string;
  queryKeysToInvalidate?: any[][];
}

export function useOfflineMutation<TData = unknown, TError = Error, TVariables = void, TContext = unknown>({
  module,
  action,
  schoolId,
  queryKeysToInvalidate,
  mutationFn,
  onSuccess,
  onError,
  ...options
}: OfflineMutationOptions<TData, TError, TVariables, TContext>) {
  const queryClient = useQueryClient();
  const auth = useAuth();

  return useMutation<TData, TError, TVariables, TContext>({
    mutationFn: async (variables: TVariables) => {
      try {
        if (!mutationFn) throw new Error("mutationFn is required");
        // Attempt network first
        return await (mutationFn as any)(variables);
      } catch (error: any) {
        // If it's a network error or 5xx, we catch it and queue offline
        const isNetworkError =
          error instanceof TypeError || // e.g. Failed to fetch
          error.message?.includes('Network Error') ||
          error.message?.includes('Failed to fetch') ||
          error.status >= 500;

        if (isNetworkError) {
          const userId = auth?.user?.id || 'unknown-user';
          const deviceId = typeof localStorage !== 'undefined' ? localStorage.getItem('device_id') || 'unknown-device' : 'unknown-device';
          
          await syncQueue.enqueue({
            schoolId,
            userId,
            deviceId,
            module,
            action,
            payload: variables,
          });

          toast?.success("Saved offline. Will sync when connection returns.");

          // Return a mock success response so the UI optimistically updates
          return { _offline: true } as unknown as TData;
        }

        // If it's a 4xx error (validation, auth), rethrow it
        throw error;
      }
    },
    onSuccess: (...args: any[]) => {
      const [data, variables, context] = args;
      // Invalidate relevant queries to update UI optimistically
      if (queryKeysToInvalidate) {
        queryKeysToInvalidate.forEach((key) => {
          queryClient.invalidateQueries({ queryKey: key });
        });
      }
      
      if (onSuccess) {
        (onSuccess as any)(data, variables, context);
      }
    },
    onError: (...args: any[]) => {
      const [error, variables, context] = args;
      if (onError) {
        (onError as any)(error, variables, context);
      }
    },
    ...options,
  });
}

