    const tripCall = fetchMock.mock.calls.find(([url, init]) => String(url) === "/api/transport/trips" && init?.method === "POST");
    expect(JSON.parse(String(tripCall?.[1]?.body))).toEqual(expect.objectContaining({
      route_id: "route-1",
      vehicle_id: "vehicle-1",
